#include <stdio.h>
#include <time.h>

#define MAX_TRANSACTIONS 100

typedef struct {
    int id;
    time_t timestamp;
    double weighted_sum;
} Transaction;

typedef struct {
    int count;
    double max_weighted_sum;
    int max_transaction_id;
} Metrics;

static void filter_transactions(Transaction transactions[], int num_transactions, time_t current_time, double threshold_age, int *recent_count, Metrics *metrics) {
    metrics->count = 0;
    metrics->max_weighted_sum = 0.0;
    metrics->max_transaction_id = -1;

    for (int i = 0; i < num_transactions; i++) {
        Transaction *t = &transactions[i];
        double age = difftime(current_time, t->timestamp);

        if (age <= threshold_age) {
            metrics->count++;
            if (t->weighted_sum > metrics->max_weighted_sum) {
                metrics->max_weighted_sum = t->weighted_sum;
                metrics->max_transaction_id = t->id;
            }
        }
    }

    // Count transactions in the last 3 seconds
    *recent_count = 0;
    for (int i = 0; i < num_transactions; i++) {
        if (difftime(current_time, transactions[i].timestamp) <= 3) {
            (*recent_count)++;
        }
    }
}
