#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ERROR_CODE -1

int load_resource_bundle(const char *path, char ***bundle_items) {
    if (path == NULL || bundle_items == NULL) {
        return ERROR_CODE;
    }

    FILE *file = fopen(path, "r");
    if (file == NULL) {
        perror("Error opening file");
        return ERROR_CODE;
    }

    size_t capacity = 10;
    size_t count = 0;
    char **items = malloc(capacity * sizeof(char *));
    if (items == NULL) {
        fclose(file);
        return ERROR_CODE;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (count >= capacity) {
            capacity *= 2;
            char **new_items = realloc(items, capacity * sizeof(char *));
            if (new_items == NULL) {
                for (size_t i = 0; i < count; i++) {
                    free(items[i]);
                }
                free(items);
                fclose(file);
                return ERROR_CODE;
            }
            items = new_items;
        }
        line[strcspn(line, "\n")] = 0; // Remove newline character
        items[count] = strdup(line);
        if (items[count] == NULL) {
            for (size_t i = 0; i < count; i++) {
                free(items[i]);
            }
            free(items);
            fclose(file);
            return ERROR_CODE;
        }
        count++;
    }

    fclose(file);
    *bundle_items = items;
    return count;
}
