} TIFFImageInfo;

const char* parseTIFF(const char* filename, TIFFImageInfo* info) {
    TIFF* tiff = TIFFOpen(filename, "r");
    if (tiff == NULL) {
        return "Error opening TIFF file.";
    }

    uint16_t samplesPerPixel = 0;
    uint16_t bitsPerSample = 0;
    uint16_t extraSamples = 0;
    uint16_t* sampleInfo = NULL;
    uint16_t sampleCount = 0;

    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) != 1) {
        TIFFClose(tiff);
        return "Error reading samples per pixel.";
    }

    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) != 1) {
        TIFFClose(tiff);
        return "Error reading bits per sample.";
    }

    if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples, &sampleInfo, &sampleCount) != 1) {
        extraSamples = 0; // No extra samples
    }

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
        bitsPerSample != 8 && bitsPerSample != 16) {
        TIFFClose(tiff);
        return "Unsupported bits per sample.";
    }

    info->bitsPerSample = bitsPerSample;
    info->samplesPerPixel = samplesPerPixel;
    info->extraSamples = extraSamples;

    if (sampleCount > 0) {
        snprintf(info->sampleInfo, sizeof(info->sampleInfo), "Extra Samples: %d", extraSamples);
    } else {
        strcpy(info->sampleInfo, "No extra samples.");
    }

    TIFFClose(tiff);
    return NULL; // No error
}
