#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define DNS_RESOLUTION_SUCCESS 0
#define DNS_RESOLUTION_FAIL -1
#define DNS_RESOLUTION_TRY_AGAIN -2

static int dns_resolve(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use AF_INET for IPv4
    hints.ai_socktype = SOCK_STREAM;

    // Perform DNS resolution
    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return (status == EAI_AGAIN) ? DNS_RESOLUTION_TRY_AGAIN : DNS_RESOLUTION_FAIL;
    }

    // Copy the IP address to the provided buffer
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), sizeof(ipv4->sin_addr));

    freeaddrinfo(res); // Free the linked list
    return DNS_RESOLUTION_SUCCESS;
}
