#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <fcntl.h>

#define BUFSIZE 1024

void receive_file(const char *filename, const char *server_ip, int port) {
    int sockfd;
    struct sockaddr_in server_addr;
    char buffer[BUFSIZE];
    ssize_t bytes_received;
    FILE *file;

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        return;
    }

    // Set up server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    // Send a request to the server to start file transfer
    if (sendto(sockfd, filename, strlen(filename), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Send failed");
        close(sockfd);
        return;
    }

    // Open file for writing
    file = fopen(filename, "wb");
    if (file == NULL) {
        perror("File opening failed");
        close(sockfd);
        return;
    }

    // Receive file data
    while ((bytes_received = recvfrom(sockfd, buffer, BUFSIZE, 0, NULL, NULL)) > 0) {
        fwrite(buffer, sizeof(char), bytes_received, file);
    }

    if (bytes_received < 0) {
        perror("Receive failed");
    }

    // Clean up
    fclose(file);
    close(sockfd);
    printf("File received and saved as %s\n", filename);
}
