#include <stdlib.h>
#include <string.h>

void* dynamic_array_copy(const int* input_array, size_t input_size, size_t* output_size) {
    size_t new_size = input_size;
    int* output_array = (int*)malloc(new_size * sizeof(int));

    if (output_array == NULL) {
        return NULL; // Memory allocation failed
    }

    memcpy(output_array, input_array, input_size * sizeof(int));
    *output_size = new_size;

    return output_array;
}

int* expand_and_copy_array(const int* input_array, size_t input_size, size_t additional_size, size_t* output_size) {
    size_t new_size = input_size + additional_size;
    int* output_array = (int*)malloc(new_size * sizeof(int));

    if (output_array == NULL) {
        return NULL; // Memory allocation failed
    }

    memcpy(output_array, input_array, input_size * sizeof(int));

    // Initialize the additional space to zero
    memset(output_array + input_size, 0, additional_size * sizeof(int));

    *output_size = new_size;

    return output_array;
}
