		fsm_state_t prev;

		prev = SINGLETON_DECODE(*setp);

		*setp = state_set_create(alloc);
		if (*setp == NULL) {
			return 0;
		}

		assert(!IS_SINGLETON(*setp));

		if (!state_set_add(setp, alloc, prev)) {
			return 0;
		}

		/* fallthrough */
	}

	if (*setp == NULL) {
		*setp = state_set_create(alloc);
		if (*setp == NULL) {
			return 0;
		}
