#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

#define LEX_EOF 0
#define LEX_ID 1
#define LEX_INT 2
#define LEX_FLOAT 3
#define LEX_STR 4
#define LEX_OPERATOR_START 128
#define LEX_OPERATOR_END 255

int getToken(const char *input) {
    int token = LEX_EOF;
    bool tokenFound = false;
    const char *ptr = input;

    while (*ptr != '\0') {
        if (isspace(*ptr)) {
            ptr++;
            continue;
        }

        if (isalpha(*ptr)) {
            token = LEX_ID;
            tokenFound = true;
            while (isalnum(*ptr) || *ptr == '_') ptr++;
        } else if (isdigit(*ptr)) {
            token = LEX_INT;
            tokenFound = true;
            while (isdigit(*ptr)) ptr++;
            if (*ptr == '.') {
                token = LEX_FLOAT;
                ptr++;
                while (isdigit(*ptr)) ptr++;
            }
        } else if (*ptr == '"') {
            token = LEX_STR;
            tokenFound = true;
            ptr++;
            while (*ptr != '"' && *ptr != '\0') ptr++;
            if (*ptr == '"') ptr++;
        } else {
            switch (*ptr) {
                case '+': case '-': case '*': case '/':
                    token = LEX_OPERATOR_START + (*ptr);
                    tokenFound = true;
                    ptr++;
                    break;
                default:
                    token = LEX_EOF;
                    tokenFound = false;
                    ptr++;
