#include <tiffio.h>

int compressTIFFImage(TIFF* in, TIFF* out, uint8* buffer) {
    uint32 imageWidth, imageLength;
    uint32 scanlineSize;
    tdata_t obuf;
    uint8* bufp;
    uint32 row;

    TIFFGetField(in, TIFFTAG_IMAGEWIDTH, &imageWidth);
    TIFFGetField(in, TIFFTAG_IMAGELENGTH, &imageLength);
    scanlineSize = TIFFScanlineSize(in);

    obuf = _TIFFmalloc(scanlineSize);
    if (obuf == NULL) {
        return 0; // Memory allocation failed
    }

    bufp = buffer;
    for (row = 0; row < imageLength; row++) {
        // Read the scanline
        if (TIFFReadScanline(in, bufp, row) < 0) {
            _TIFFfree(obuf);
            return 0; // Error reading scanline
        }

        // Reverse the order of pixels in the scanline
        for (uint32 col = 0; col < imageWidth / 2; col++) {
            uint8 temp = bufp[col];
            bufp[col] = bufp[imageWidth - col - 1];
            bufp[imageWidth - col - 1] = temp;
        }

        // Write the compressed scanline to the new TIFF file
        if (TIFFWriteScanline(out, bufp, row) < 0) {
            _TIFFfree(obuf);
            return 0; // Error writing scanline
        }
    }

    _TIFFfree(obuf);
    return 1; // Success
}
