#include <stdio.h>
#include <stdint.h>

void parse_ip_options(const uint8_t *packet, int length) {
    int opt_len, opt_type;
    const uint8_t *p = packet;

    while (length > 0) {
        if (length < 2) {
            printf("Packet too short for options\n");
            return;
        }

        opt_type = p[0];
        opt_len = p[1];

        if (opt_len < 2 || opt_len > length) {
            printf("Invalid option length %u for option type %u\n", opt_len, opt_type);
            return;
        }

        printf("Option Type: %u, Length: %u\n", opt_type, opt_len);

        switch (opt_type) {
            case 0: // No Operation
                printf("  No Operation\n");
                break;
            case 1: // End of Options
                printf("  End of Options\n");
                return; // End of options processing
            default:
                printf("  Unknown Option\n");
                break;
        }

        p += opt_len;
        length -= opt_len;
    }
}
