#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <ctype.h>

void analyze_sentence(const char *sentence, int *vowel_count, int *uppercase_count, int *lowercase_count) {
    *vowel_count = 0;
    *uppercase_count = 0;
    *lowercase_count = 0;

    for (const char *p = sentence; *p != '\0'; p++) {
        char ch = *p;
        if (isalpha(ch)) {
            if (isupper(ch)) {
                (*uppercase_count)++;
            } else {
                (*lowercase_count)++;
            }
            if (strchr("AEIOUaeiou", ch)) {
                (*vowel_count)++;
            }
        }
    }
}

int main() {
    pid_t pid;
    int status;
    int pipefd[2];
    char sentence[256];
    int vowel_count, uppercase_count, lowercase_count;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        close(pipefd[1]); // Close write end
        read(pipefd[0], sentence, sizeof(sentence));
        close(pipefd[0]);

        analyze_sentence(sentence, &vowel_count, &uppercase_count, &lowercase_count);

        printf("Vowels: %d\n", vowel_count);
        printf("Uppercase letters: %d\n", uppercase_count);
        printf("Lowercase letters: %d\n", lowercase_count);
        exit(EXIT_SUCCESS);
    } else { // Parent process
        close(pipefd[0]); // Close read end
        printf("Enter a sentence: ");
        fgets(sentence, sizeof(sentence), stdin);
        write(pipefd[1], sentence, strlen(sentence) + 1);
        close(pipefd[1]);

        waitpid(pid, &status, 0); // Wait for child process to finish
    }

    return 0;
}
