#include <stdlib.h>

typedef struct {
    double *data;
    size_t rows;
    size_t cols;
    size_t stride;
} ComplexMatrix;

ComplexMatrix* createComplexMatrix(size_t rows, size_t cols, size_t stride) {
    ComplexMatrix *matrix = (ComplexMatrix *)malloc(sizeof(ComplexMatrix));
    if (matrix == NULL) {
        return NULL;
    }

    matrix->rows = rows;
    matrix->cols = cols;
    matrix->stride = stride;
    matrix->data = (double *)malloc(rows * stride * sizeof(double));

    if (matrix->data == NULL) {
        free(matrix);
        return NULL;
    }

    return matrix;
}

void freeComplexMatrix(ComplexMatrix *matrix) {
    if (matrix != NULL) {
        free(matrix->data);
        free(matrix);
    }
}
