int parseFontSpecification(const char *fontSpec, char *type_face, int *style, int *size) {
  char *token;
  char font[1024];

  if (*fontSpec == '-') {
    fontSpec++;
  }

  strcpy(font, fontSpec);

  *style = 0;

  token = strtok(font, "-");
  if (!token) return 0;
  strcpy(type_face, token);

  token = strtok(NULL, "-");
  if (!token) return 0;

  if (strstr("bold", token)) {
    *style |= 1;
  }

  token = strtok(NULL, "-");
  if (token && (*token == 'i' || *token == 'o')) {
    *style |= 2;
  }

  token = strtok(NULL, "-");
  if (!token) return 0;
  *size = atoi(token);

  if (*size <= 0) return 0;

  return 1;
}
