function permutedMatrix = fillReducingOrdering(matrix, permutation)
    % Check if the permutation is valid
    if any(permutation < 1) || any(permutation > size(matrix, 1)) || length(permutation) ~= size(matrix, 1)
        error('Invalid permutation vector.');
    end

    % Check if the matrix is sparse
    if issparse(matrix)
        matrix = full(matrix); % Convert to full matrix for processing
    end

    % Apply the permutation to the rows of the matrix
    permutedMatrix = matrix(permutation, :);
end
