typedef struct {
    char *value;
} TIGValue;

TIGValue* concatenate_strings(const char *str1, const char *str2, int index) {
    if (str1 == NULL || str2 == NULL) return NULL;

    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);
    size_t new_len = len1 + len2;

    if (index < 0 || index > len1) index = len1; // Adjust index if out of bounds

    TIGValue *result = (TIGValue *)malloc(sizeof(TIGValue));
    if (result == NULL) return NULL;

    result->value = (char *)malloc(new_len + 1);
    if (result->value == NULL) {
        free(result);
        return NULL;
    }

    // Copy first part of str1 up to index
    strncpy(result->value, str1, index);
    // Append str2
    strcpy(result->value + index, str2);
    // Append the rest of str1
    strcpy(result->value + index + len2, str1 + index);

    return result;
}
