#define MAX_LINE_LENGTH 1024

typedef struct {
    char *function_name;
    char **arguments;
    int arg_count;
} ParsedLine;

ParsedLine* process_input_line(const char *input) {
    if (input == NULL || strlen(input) == 0) {
        return NULL; // Handle empty input
    }

    // Allocate memory for the stack
    char *stack = (char *)malloc(MAX_LINE_LENGTH * sizeof(char));
    if (stack == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy input to stack and append newline
    snprintf(stack, MAX_LINE_LENGTH, "%s\n", input);

    // Parse the line into function call and arguments
    ParsedLine *parsed = (ParsedLine *)malloc(sizeof(ParsedLine));
    if (parsed == NULL) {
        free(stack);
        return NULL; // Memory allocation failed
    }

    char *line = strtok(stack, "\n");
    if (line != NULL) {
        parsed->function_name = strtok(line, " ");
        parsed->arg_count = 0;

        // Count arguments
        char *arg = strtok(NULL, " ");
        while (arg != NULL) {
            parsed->arg_count++;
            arg = strtok(NULL, " ");
        }

        // Allocate memory for arguments
        parsed->arguments = (char **)malloc(parsed->arg_count * sizeof(char *));
        if (parsed->arguments == NULL) {
            free(parsed);
            free(stack);
            return NULL; // Memory allocation failed
        }

        // Reset line for argument extraction
        strcpy(stack, line);
        arg = strtok(stack, " ");
        strtok(NULL, " "); // Skip function name

        // Store arguments
        for (int i = 0; i < parsed->arg_count; i++) {
            parsed->arguments[i] = strtok(NULL, " ");
        }
    }

    free(stack);
    return parsed;
}
