PollSet *CreatePollSet(size_t initial_capacity) {
    PollSet *pollset = (PollSet *)malloc(sizeof(PollSet));
    if (pollset == NULL) {
        return NULL;
    }
    pollset->items = (PollItem *)malloc(initial_capacity * sizeof(PollItem));
    if (pollset->items == NULL) {
        free(pollset);
        return NULL;
    }
    pollset->size = 0;
    pollset->capacity = initial_capacity;
    return pollset;
}

void FreePollSet(PollSet *pollset) {
    if (pollset != NULL) {
        free(pollset->items);
        free(pollset);
    }
}

int AddPollItem(PollSet *pollset, int fd, short events) {
    if (pollset->size >= pollset->capacity) {
        size_t new_capacity = pollset->capacity * 2;
        PollItem *new_items = (PollItem *)realloc(pollset->items, new_capacity * sizeof(PollItem));
        if (new_items == NULL) {
            return -1; // Memory allocation failed
        }
        pollset->items = new_items;
        pollset->capacity = new_capacity;
    }
    pollset->items[pollset->size].fd = fd;
    pollset->items[pollset->size].events = events;
    pollset->size++;
    return 0; // Success
}
