double** allocate_symmetric_matrix(size_t size) {
    double** matrix = malloc(size * sizeof(double*));
    if (matrix == NULL) {
        return NULL; // Allocation failed
    }

    for (size_t i = 0; i < size; i++) {
        matrix[i] = malloc((i + 1) * sizeof(double));
