    // Populate the new QDict with options for opening the file
    qdict_set(new_qdict, "file_path", file_info->path);
    qdict_set(new_qdict, "file_mode", file_info->mode);
    qdict_set(new_qdict, "file_access", file_info->access);
    qdict_set(new_qdict, "file_attributes", file_info->attributes);

    // Optionally copy additional options from full_options
    if (full_options)
    {
        qdict_copy(new_qdict, full_options);
    }

    return new_qdict;
}
