char *format_bytes(char *buf, size_t l, unsigned long long bytes) {
    static const struct {
        const char *suffix;
        unsigned long long factor;
    } table[] = {
        { "B", 1ULL },
        { "K", 1024ULL },
        { "M", 1024ULL * 1024ULL },
        { "G", 1024ULL * 1024ULL * 1024ULL },
    };

    char *p = buf;
    assert(buf);
    assert(l > 0);

    if (bytes == 0) {
        strncpy(p, "0 B", l - 1);
        p[l - 1] = 0;
        return p;
    }

    for (size_t i = 0; i < sizeof(table) / sizeof(table[0]); i++) {
        if (bytes < table[i].factor) {
            if (i == 0) {
                snprintf(p, l, "0 B");
                return buf;
            }
            unsigned long long value = bytes / (table[i - 1].factor);
            unsigned long long remainder = bytes % (table[i - 1].factor);
            if (remainder > 0) {
                snprintf(p, l, "%.2f %s", (double)bytes / table[i - 1].factor, table[i - 1].suffix);
            } else {
                snprintf(p, l, "%llu %s", value, table[i - 1].suffix);
            }
            return buf;
        }
    }

    snprintf(p, l, "%llu G", bytes / table[3].factor);
    return buf;
}
