    char timestamp[20];
    snprintf(timestamp, sizeof(timestamp), "%ld", now);

    // Create a buffer for the combined input
    char combined[256];
    snprintf(combined, sizeof(combined), "%s:%s:%s", input_string, timestamp, entropy_value);

    // Generate MD5 hash
