char* format_memory_data(void* address, size_t size, const char* data_type, const char* data_format) {
    if (size <= 0) {
        return "Error: Invalid size.";
    }

    // Check if the requested size exceeds the available memory
    if (size > sizeof(address)) {
        return "Error: Requested size exceeds available memory.";
    }

    char* result = malloc(size * 8); // Allocate enough space for the result
    if (!result) {
        return "Error: Memory allocation failed.";
    }

    if (strcmp(data_format, "binary") == 0) {
        for (size_t i = 0; i < size; i++) {
            uint8_t byte = *((uint8_t*)address + i);
            for (int j = 7; j >= 0; j--) {
                result[i * 8 + (7 - j)] = (byte & (1 << j)) ? '1' : '0';
            }
        }
        result[size * 8] = '\0'; // Null-terminate the string
    } else if (strcmp(data_format, "text") == 0) {
        if (strcmp(data_type, "int") == 0) {
            snprintf(result, size * 8, "%d", *((int*)address));
        } else if (strcmp(data_type, "float") == 0) {
            snprintf(result, size * 8, "%f", *((float*)address));
        } else if (strcmp(data_type, "double") == 0) {
            snprintf(result, size * 8, "%lf", *((double*)address));
        } else {
            free(result);
            return "Error: Unsupported data type.";
        }
    } else {
        free(result);
        return "Error: Unsupported data format.";
    }

    return result;
}
