void convert_to_octal(struct in_addr addr) {
    printf("IP Address in Octal: %o.%o.%o.%o\n", 
           (addr.s_addr >> 24) & 0xFF, 
           (addr.s_addr >> 16) & 0xFF, 
           (addr.s_addr >> 8) & 0xFF, 
           addr.s_addr & 0xFF);
}

int get_ip_address(const char *dns_name) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    status = getaddrinfo(dns_name, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    struct in_addr *addr = &((struct sockaddr_in *)res->ai_addr)->sin_addr;
    convert_to_octal(*addr);

    freeaddrinfo(res);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <DNS name or IP address>\n", argv[0]);
        return 1;
    }

    return get_ip_address(argv[1]);
}
