#include <stdio.h>
#include <string.h>

#define BUFFER_SIZE 1024

typedef struct {
    char buffer[BUFFER_SIZE];
    size_t buffer_length;
    size_t buffer_position;
} LineBuffer;

void init_line_buffer(LineBuffer *line_buffer) {
    line_buffer->buffer_length = 0;
    line_buffer->buffer_position = 0;
}

int push_back_line(LineBuffer *line_buffer, const char *line, size_t length) {
    if (length + line_buffer->buffer_length > BUFFER_SIZE) {
        return -1; // Buffer overflow
    }
    memcpy(line_buffer->buffer + line_buffer->buffer_length, line, length);
    line_buffer->buffer_length += length;
    return 0;
}

int get_next_line(LineBuffer *line_buffer, char *line, size_t max_length) {
    size_t line_length = 0;

    while (line_buffer->buffer_position < line_buffer->buffer_length) {
        if (line_length >= max_length - 1) {
            return -1; // Line too long
        }
        char c = line_buffer->buffer[line_buffer->buffer_position++];
        if (c == '\n') {
            line[line_length] = '\0';
            return line_length; // Return length of the line
        }
        line[line_length++] = c;
    }

    return 0; // No more lines
}

int read_line_from_file(FILE *file, LineBuffer *line_buffer) {
    char temp_buffer[BUFFER_SIZE];
    size_t bytes_read = fread(temp_buffer, 1, BUFFER_SIZE, file);
    if (bytes_read == 0) {
        return 0; // End of file
    }
    return push_back_line(line_buffer, temp_buffer, bytes_read);
}
