            cfg->input_files[cfg->file_count] = strdup(argv[i]);
            cfg->file_count++;
        }
    }
}

static void initialize_sqlite() {
    int rc = sqlite3_initialize();
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQLite initialization failed: %s\n", sqlite3_errmsg(NULL));
        exit(EXIT_FAILURE);
    }
}

int main(int argc, const char **argv) {
    config_t cfg;
    initialize_sqlite();
    parse_args(argc, argv, &cfg);

    if (cfg.verbose) {
