        // Free previously allocated memory in case of failure
        for (int i = 0; i < 3; i++) {
            free(request[i]);
        }
        free(request);
        return NULL; // Allocation failed
    }

    strcpy(request[0], verb);
    strcpy(request[1], path);
    sprintf(request[2], "%s\n", http_version); // Add newline

