#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Card {
    char type[20];
    char name[20];
} Card;

typedef struct Node {
    Card card;
    struct Node* next;
} Node;

void shuffleDeck(Card* deck, int deckSize) {
    srand(time(NULL));
    for (int i = deckSize - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

Node* createLinkedList(Card* deck, int deckSize) {
    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < deckSize; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->card = deck[i];
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }
    return head;
}

Node* shuffleAndReturnLinkedList(Card* deck, int deckSize) {
    shuffleDeck(deck, deckSize);
    return createLinkedList(deck, deckSize);
}
