int count_matching_files(const char *pattern) {
    struct dirent *entry;
    DIR *dp;
    int count = 0;

    dp = opendir(".");
    if (dp == NULL) {
        perror("opendir");
        return -1; // Error opening directory
    }

    while ((entry = readdir(dp)) != NULL) {
        if (fnmatch(pattern, entry->d_name, 0) == 0) {
            count++;
        }
    }

    closedir(dp);
    return count;
}
