#include <numpy/arrayobject.h>

static PyObject* extract_along_axis(PyObject* self, PyObject* args) {
    PyObject *input_array;
    int axis;

    if (!PyArg_ParseTuple(args, "Oi", &input_array, &axis)) {
        PyErr_SetString(PyExc_TypeError, "Invalid arguments");
        return NULL;
    }

    if (!PyArray_Check(input_array)) {
        PyErr_SetString(PyExc_TypeError, "Input must be a NumPy array");
        return NULL;
    }

    PyArrayObject *array = (PyArrayObject *)input_array;
    int ndims = PyArray_NDIM(array);

    if (axis < 0 || axis >= ndims) {
        PyErr_SetString(PyExc_IndexError, "Axis out of bounds");
        return NULL;
    }

    npy_intp *dims = PyArray_DIMS(array);
    npy_intp new_dims[ndims - 1];
    for (int i = 0, j = 0; i < ndims; i++) {
        if (i != axis) {
            new_dims[j++] = dims[i];
        }
    }

    PyArrayObject *result = (PyArrayObject *)PyArray_EMPTY(ndims - 1, new_dims, PyArray_TYPE(array), 0);
    if (result == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy data along the specified axis
    npy_intp *strides = PyArray_STRIDES(array);
    npy_intp *result_strides = PyArray_STRIDES(result);
    for (npy_intp i = 0; i < PyArray_SIZE(result); i++) {
        npy_intp index = i;
        npy_intp source_index = 0;
        for (int j = 0; j < ndims; j++) {
            if (j == axis) {
                source_index += (index % dims[j]) * strides[j] / sizeof(double);
                index /= dims[j];
            } else {
                source_index += (index % new_dims[j]) * strides[j] / sizeof(double);
                index /= new_dims[j];
            }
        }
        *(double *)((char *)PyArray_DATA(result) + i * result_strides[0]) = 
            *(double *)((char *)PyArray_DATA(array) + source_index * strides[0]);
    }

    return (PyObject *)result;
}

static PyMethodDef MyMethods[] = {
    {"extract_along_axis", extract_along_axis, METH_VARARGS, "Extract elements along a specified axis from a multi-dimensional array."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef mymodule = {
    PyModuleDef_HEAD_INIT,
    "mymodule",
    NULL,
    -1,
    MyMethods
};

PyMODINIT_FUNC PyInit_mymodule(void) {
