#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

int count_files_with_string(const char *dir_path, const char *search_string) {
    struct dirent *entry;
    DIR *dp = opendir(dir_path);
    int count = 0;

    if (dp == NULL) {
        perror("opendir");
        return 0;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_type == DT_DIR) {
            // Skip the "." and ".." directories
            if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                char new_path[1024];
                snprintf(new_path, sizeof(new_path), "%s/%s", dir_path, entry->d_name);
                count += count_files_with_string(new_path, search_string);
            }
        } else if (entry->d_type == DT_REG) {
            // Check if the file contains the search string
            char file_path[1024];
            snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, entry->d_name);
            FILE *file = fopen(file_path, "r");
            if (file) {
                char *line = NULL;
                size_t len = 0;
                while (getline(&line, &len, file) != -1) {
                    if (strstr(line, search_string) != NULL) {
                        count++;
                        break; // No need to check further lines
                    }
                }
                free(line);
                fclose(file);
            }
        }
    }

    closedir(dp);
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <search_string>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int total_count = count_files_with_string(argv[1], argv[2]);
    printf("Total files containing '%s': %d\n", argv[2], total_count);
    return EXIT_SUCCESS;
}
