    file_name[file_name_length] = '\0';

    // Calculate the size of the full path
    size_t dir_length = strlen(dir_path);
    size_t prefix_length = strlen(file_prefix);
    size_t total_length = dir_length + prefix_length + file_name_length + 2; // +2 for '/' and '\0'

    if (total_length > max_size) {
        free(file_name);
        return NULL;
    }

    // Allocate memory for the full path
