#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

typedef struct DirectoryEntry {
    char *name;
    struct DirectoryEntry *subdirectories;
    struct DirectoryEntry *next;
} DirectoryEntry;

DirectoryEntry* create_directory_entry(const char *name) {
    DirectoryEntry *entry = malloc(sizeof(DirectoryEntry));
    entry->name = strdup(name);
    entry->subdirectories = NULL;
    entry->next = NULL;
    return entry;
}

void free_directory_entry(DirectoryEntry *entry) {
    if (entry) {
        free(entry->name);
        free_directory_entry(entry->subdirectories);
        free_directory_entry(entry->next);
        free(entry);
    }
}

DirectoryEntry* traverse_directory(const char *path, const char *target, DirectoryEntry *parent) {
    DIR *dir = opendir(path);
    struct dirent *entry;
    char full_path[1024];

    if (!dir) {
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);
        DirectoryEntry *current_entry = create_directory_entry(entry->d_name);

        if (strcmp(full_path, target) == 0) {
            closedir(dir);
            return current_entry;
        }

        current_entry->subdirectories = traverse_directory(full_path, target, current_entry);
        current_entry->next = parent ? parent->subdirectories : NULL;
        if (parent) {
            parent->subdirectories = current_entry;
        } else {
            parent = current_entry;
        }
    }

    closedir(dir);
    return parent;
}

DirectoryEntry* find_directory(const char *root, const char *path) {
    char resolved_path[1024];
    realpath(path, resolved_path);
    return traverse_directory(root, resolved_path, NULL);
}

// Example usage
int main() {
    const char *root = "/path/to/start"; // Change to your starting directory
    const char *target_path = "/path/to/target"; // Change to your target path

    DirectoryEntry *result = find_directory(root, target_path);
    if (result) {
        printf("Found directory: %s\n", result->name);
        free_directory_entry(result);
    } else {
        printf("Directory not found.\n");
    }

    return 0;
}
