            // Find the end of the filename
            const char *filename_end = strchr(filename_start, '\n');
            if (!filename_end) {
                filename_end = line + strlen(line); // End of buffer if no newline
            }
            filename_length = filename_end - filename_start;

            // Check if the filename is too long
            if (filename_length > MAX_FILENAME_LENGTH) {
                line = filename_end + 1; // Move to the next line
                continue;
            }

            // Copy the filename into the struct
            strncpy(file_info->filename, filename_start, filename_length);
            file_info->filename[filename_length] = '\0'; // Null-terminate
            file_info->length = filename_length;

            return file_info->length; // Return the length of the filename
        }
        line = strchr(line, '\n'); // Move to the next line
        if (line) {
            line++; // Move past the newline character
        }
    }

