#include <sys/types.h>
#include <sys/stat.h>
#include <pthread.h>
#include <semaphore.h>

#define QUEUE_SIZE 10
#define OLED_DISPLAY "/dev/oled" // Example path to OLED display device

typedef struct {
    char *messages[QUEUE_SIZE];
    int front;
    int rear;
    sem_t empty;
    sem_t full;
    pthread_mutex_t mutex;
} MessageQueue;

MessageQueue queue;

void initQueue() {
    queue.front = 0;
    queue.rear = 0;
    sem_init(&queue.empty, 0, QUEUE_SIZE);
    sem_init(&queue.full, 0, 0);
    pthread_mutex_init(&queue.mutex, NULL);
}

void enqueue(char *message) {
    sem_wait(&queue.empty);
    pthread_mutex_lock(&queue.mutex);

    queue.messages[queue.rear] = strdup(message);
    queue.rear = (queue.rear + 1) % QUEUE_SIZE;

    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.full);
}

char* dequeue() {
    sem_wait(&queue.full);
    pthread_mutex_lock(&queue.mutex);

    char *message = queue.messages[queue.front];
    queue.front = (queue.front + 1) % QUEUE_SIZE;

    pthread_mutex_unlock(&queue.mutex);
    sem_post(&queue.empty);

    return message;
}

void* displayMessages(void *arg) {
    while (1) {
        char *message = dequeue();
        int fd = open(OLED_DISPLAY, O_WRONLY);
        if (fd != -1) {
            write(fd, message, strlen(message));
            close(fd);
        }
        free(message);
    }
}

void processFormInput(const char *queryString) {
    char message[256];
    snprintf(message, sizeof(message), "Received: %s", queryString);
    enqueue(message);
}

int main() {
    initQueue();

    pthread_t displayThread;
    pthread_create(&displayThread, NULL, displayMessages, NULL);

    // Simulate receiving form input
    processFormInput("example_query_string");

    // Clean up
    pthread_join(displayThread, NULL);
    return 0;
}
