#include <curses.h>
#include <unistd.h>

void display_progress_bar(int total, int current) {
    int width = 50; // Width of the progress bar
    float progress = (float)current / total;
    int bar_length = (int)(width * progress);
    int percentage = (int)(progress * 100);

    // Clear the window
    clear();

    // Draw the progress bar
    mvprintw(1, 1, "[");
    for (int i = 0; i < width; i++) {
        if (i < bar_length) {
            mvaddch(1, 2 + i, '#');
        } else {
            mvaddch(1, 2 + i, ' ');
        }
    }
    mvprintw(1, 2 + width, "] %d%%", percentage);

    // Refresh the window to show the progress bar
    refresh();
}

int main() {
    initscr(); // Initialize the window
    noecho();  // Don't echo input
    cbreak();  // Disable line buffering

    int total = 100; // Total work
    for (int i = 0; i <= total; i++) {
        display_progress_bar(total, i);
        usleep(50000); // Simulate work being done
    }

    getch(); // Wait for user input
    endwin(); // End curses mode
    return 0;
}
