void traverse_directory(const char *dir_path, void (*callback)(const char *file_path), int recurse) {
    struct dirent *entry;
    DIR *dp = opendir(dir_path);
    char path[1024];

    if (dp == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        // Skip the special entries "." and ".."
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);
        callback(path);

        if (recurse && entry->d_type == DT_DIR) {
            traverse_directory(path, callback, recurse);
        }
    }

    closedir(dp);
}

