#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Blob {
    int x;
    int y;
    int lifetime;
    struct Blob* next;
} Blob;

Blob* create_blob(int x, int y, int lifetime) {
    Blob* new_blob = (Blob*)malloc(sizeof(Blob));
    if (!new_blob) {
        return NULL;
    }
    new_blob->x = x;
    new_blob->y = y;
    new_blob->lifetime = lifetime;
    new_blob->next = NULL;
    return new_blob;
}

void update_blobs(Blob** head) {
    Blob* current = *head;
    Blob* prev = NULL;

    while (current != NULL) {
        current->lifetime--;
        if (current->lifetime <= 0) {
            if (prev == NULL) {
                *head = current->next;
                free(current);
                current = *head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void add_blob(Blob** head) {
    int x = rand() % 100; // Random x position
    int y = rand() % 100; // Random y position
    int lifetime = rand() % 10 + 1; // Random lifetime between 1 and 10
    Blob* new_blob = create_blob(x, y, lifetime);
    if (new_blob) {
        new_blob->next = *head;
        *head = new_blob;
    }
}

void print_blobs(Blob* head) {
    Blob* current = head;
    while (current != NULL) {
        printf("Blob at (%d, %d) with lifetime %d\n", current->x, current->y, current->lifetime);
        current = current->next;
    }
}

void free_blobs(Blob* head) {
    Blob* current = head;
    while (current != NULL) {
        Blob* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    srand(time(NULL));
    Blob* blob_list = NULL;

    for (int i = 0; i < 5; i++) {
        add_blob(&blob_list);
    }

    printf("Initial blobs:\n");
    print_blobs(blob_list);

    for (int i = 0; i < 5; i++) {
        update_blobs(&blob_list);
        printf("After update %d:\n", i + 1);
        print_blobs(blob_list);
    }

    free_blobs(blob_list);
    return 0;
}
