#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VERTICES 100

typedef struct {
    char *name;
    int edges[MAX_VERTICES];
    int edge_count;
} Vertex;

typedef struct {
    Vertex vertices[MAX_VERTICES];
    int vertex_count;
} Graph;

void init_graph(Graph *graph) {
    graph->vertex_count = 0;
}

void add_vertex(Graph *graph, const char *name) {
    if (graph->vertex_count < MAX_VERTICES) {
        graph->vertices[graph->vertex_count].name = strdup(name);
        graph->vertices[graph->vertex_count].edge_count = 0;
        graph->vertex_count++;
    } else {
        printf("Graph is full, cannot add more vertices.\n");
    }
}

void add_edge(Graph *graph, int from, int to) {
    if (from < graph->vertex_count && to < graph->vertex_count) {
        graph->vertices[from].edges[graph->vertices[from].edge_count++] = to;
    } else {
        printf("Invalid edge from %d to %d.\n", from, to);
    }
}

void display_graph(Graph *graph) {
    for (int i = 0; i < graph->vertex_count; i++) {
        printf("%s -> ", graph->vertices[i].name);
        for (int j = 0; j < graph->vertices[i].edge_count; j++) {
            printf("%s ", graph->vertices[graph->vertices[i].edges[j]].name);
        }
        printf("\n");
    }
}

void modify_vertex(Graph *graph, int index, const char *new_name) {
    if (index < graph->vertex_count) {
        free(graph->vertices[index].name);
        graph->vertices[index].name = strdup(new_name);
    } else {
        printf("Invalid vertex index %d.\n", index);
    }
}

int main() {
    Graph graph;
    init_graph(&graph);

    add_vertex(&graph, "A");
    add_vertex(&graph, "B");
    add_vertex(&graph, "C");
    add_edge(&graph, 0, 1); // A -> B
    add_edge(&graph, 1, 2); // B -> C

    printf("Initial graph:\n");
    display_graph(&graph);

    int index;
    char new_name[50];
    printf("Enter vertex index to modify (0-%d): ", graph.vertex_count - 1);
    scanf("%d", &index);
    printf("Enter new name for vertex %d: ", index);
    scanf("%s", new_name);
    modify_vertex(&graph, index, new_name);

    char new_vertex_name[50];
    printf("Enter new vertex name to insert: ");
    scanf("%s", new_vertex_name);
    add_vertex(&graph, new_vertex_name);

    printf("Updated graph:\n");
    display_graph(&graph);

    // Free allocated memory
    for (int i = 0; i < graph.vertex_count; i++) {
        free(graph.vertices[i].name);
    }

    return 0;
}
