	if (src_new_n != 0) {
		int i = dst->n;
		dst->n += src_new_n;
		dst->set = (const char**)realloc(dst->set, dst->n * sizeof(dst->set[0]));
		for (int j = 0; j < src->n; j++) {
			if (src_mask[j])
				continue;
			dst->set[i++] = strdup(src->set[j]);
		}
	}
#ifdef _MSC_VER
	free(src_mask);
#endif
