int copy_buffer(const void* src, size_t size, void** dest) {
    if (size == 0) {
        *dest = NULL;
        return 0;
    }

    // Allocate a temporary buffer
    void* temp_buffer = malloc(size);
    if (temp_buffer == NULL) {
        return -1; // Memory allocation failed
    }

    // Copy the contents from the source buffer to the temporary buffer
