void aes_128_ctr_encrypt(const unsigned char *test_vector, const unsigned char *key_schedule, size_t length, unsigned char *output) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    // Create and initialize the context
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        // Handle error
        return;
    }

    // Initialize the encryption operation
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key_schedule, NULL)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Provide the message to be encrypted, and obtain the encrypted output
    if (1 != EVP_EncryptUpdate(ctx, output, &len, test_vector, length)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    ciphertext_len = len;

    // Finalize the encryption
    if (1 != EVP_EncryptFinal_ex(ctx, output + len, &len)) {
        // Handle error
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    ciphertext_len += len;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}
