} JsonValueType;

typedef struct {
    union {
        int intValue;
        float floatValue;
    };
    JsonValueType type;
} ParsedValue;

ParsedValue parseNumber(const char *input) {
    ParsedValue result;
    char *endptr;

    // Check for null input
    if (input == NULL || *input == '\0') {
        result.type = JSON_TYPE_NULL;
        return result;
    }

    // Trim whitespace
    while (isspace((unsigned char)*input)) input++;

    // Try to parse as integer
    long intValue = strtol(input, &endptr, 10);
    if (endptr != input) {
        // Successfully parsed an integer
        if (*endptr == '\0' || isspace((unsigned char)*endptr)) {
