from Crypto.Util.Padding import pad, unpad
from Crypto.Util import Counter
import os

class SymmetricEncryption:
    def __init__(self, key):
        self.key = key

    def encrypt_ecb(self, message):
        cipher = AES.new(self.key, AES.MODE_ECB)
        return cipher.encrypt(pad(message.encode(), AES.block_size))

    def decrypt_ecb(self, ciphertext):
        cipher = AES.new(self.key, AES.MODE_ECB)
        return unpad(cipher.decrypt(ciphertext), AES.block_size).decode()

    def encrypt_cbc(self, message):
        iv = os.urandom(AES.block_size)
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        ciphertext = iv + cipher.encrypt(pad(message.encode(), AES.block_size))
        return ciphertext

    def decrypt_cbc(self, ciphertext):
        iv = ciphertext[:AES.block_size]
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        return unpad(cipher.decrypt(ciphertext[AES.block_size:]), AES.block_size).decode()

    def encrypt_cfb64(self, message):
        iv = os.urandom(AES.block_size)
        cipher = AES.new(self.key, AES.MODE_CFB, iv)
        ciphertext = iv + cipher.encrypt(message.encode())
        return ciphertext

    def decrypt_cfb64(self, ciphertext):
        iv = ciphertext[:AES.block_size]
        cipher = AES.new(self.key, AES.MODE_CFB, iv)
        return cipher.decrypt(ciphertext[AES.block_size:]).decode()

    def process_message(self, message, flag, mode):
        if mode == 'ECB':
            if flag == 'encrypt':
                return self.encrypt_ecb(message)
            elif flag == 'decrypt':
                return self.decrypt_ecb(message)
        elif mode == 'CBC':
            if flag == 'encrypt':
                return self.encrypt_cbc(message)
            elif flag == 'decrypt':
                return self.decrypt_cbc(message)
        elif mode == 'CFB64':
            if flag == 'encrypt':
                return self.encrypt_cfb64(message)
            elif flag == 'decrypt':
                return self.decrypt_cfb64(message)
        else:
            raise ValueError("Invalid mode specified")

# Example usage
