#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define DENSITY_FACTOR 2 // Example factor for density-based compression

char* compress_data(const char *input_file, size_t *compressed_size) {
    FILE *file = fopen(input_file, "rb");
    if (!file) {
        perror("Failed to open input file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t input_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Calculate safe size for compressed data
    *compressed_size = input_size / DENSITY_FACTOR;
    char *compressed_data = (char *)malloc(*compressed_size);
    if (!compressed_data) {
        fclose(file);
        perror("Failed to allocate memory for compressed data");
        return NULL;
    }

    size_t bytes_read = fread(compressed_data, 1, input_size, file);
    if (bytes_read != input_size) {
        free(compressed_data);
        fclose(file);
        perror("Failed to read input file");
        return NULL;
    }
    fclose(file);

    // Simple density-based compression using rand() and bitwise operations
    for (size_t i = 0; i < bytes_read; i++) {
        compressed_data[i % *compressed_size] ^= (compressed_data[i] ^ (rand() % 256));
    }

    return compressed_data;
}
