char *concat_and_correct_path(char *buffer, size_t size, const char *path) {
    char cwd[PATH_MAX];
    static char corrected_path[PATH_MAX];
    char *ptr;

    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        return NULL;
    }

    if (!path || !strlen(path)) {
        snprintf(buffer, size, "%s", cwd);
        return buffer;
    }

    if (path[0] != '/') {
        if (cwd[strlen(cwd) - 1] != '/') {
            snprintf(buffer, size, "%s/%s", cwd, path);
        } else {
            snprintf(buffer, size, "%s%s", cwd, path);
        }
    } else {
        snprintf(buffer, size, "%s", path);
    }

    // Remove duplicate slashes
    while ((ptr = strstr(buffer, "//"))) {
        memmove(ptr, &ptr[1], strlen(&ptr[1]) + 1);
    }

    // Resolve to absolute path
    if (realpath(buffer, corrected_path) == NULL) {
        return NULL;
    }

    return corrected_path;
}
