void CDECL InsertLineAtCursor(HWND hWnd, LPSTR lpszText) {
    HANDLE hMem = NULL;
    LPSTR lpOldText = NULL;
    LPSTR lpNewText = NULL;
    int lenOldText = 0;
    int lenNewText = strlen(lpszText) + 1; // +1 for '\0'
    int lenTotal = GetWindowTextLength(hWnd) + lenNewText;

    if (GetWindowText(hWnd, lpOldText, sizeof(lpOldText)) > 0) {
        lenOldText = strlen(lpOldText);

        hMem = GlobalAlloc(GMEM_MOVEABLE, lenTotal + 1);
        if (hMem != NULL) {
            lpNewText = (LPSTR)GlobalLock(hMem);

            if (lpNewText != NULL) {
                strcpy(lpNewText, lpOldText);

                // Insert new line at current cursor position
                if (GetSelectionInfo(hWnd, NE_CURSORPOS | NE_SELSTART, &selInfo)) {
                    int pos = selInfo.selEnd.cx;
                    memmove(lpNewText + pos, lpNewText + selInfo.selStart.cx, lenOldText - selInfo.selStart.cx);
                    strcat(lpNewText, lpszText);
                    strcat(lpNewText, "\r\n");
                    memmove(lpNewText + pos + lenNewText, lpNewText + lenOldText, lenOldText - pos);

                    SetWindowText(hWnd, lpNewText);
                    GlobalUnlock(hMem);
                }

                GlobalFree(hMem);
            }
        }
    }

    if (lpOldText != NULL) free(lpOldText);
}
