#include <openssl/des.h>

void des_encrypt(unsigned char key[3], unsigned char *plaintext, unsigned char result[3][8]) {
    DES_key_schedule key_schedule;
    unsigned char des_key[8] = {0};

    // Prepare the key (expand 3 bytes to 8 bytes)
    memcpy(des_key, key, 3);
    DES_set_key((DES_cblock *)des_key, &key_schedule);

    for (int i = 0; i < 3; i++) {
        unsigned char block[8] = {0};
        memcpy(block, plaintext + (i * 8), 8); // Get 8 bytes of plaintext for each block
        DES_ecb_encrypt((DES_cblock *)block, (DES_cblock *)result[i], &key_schedule, DES_ENCRYPT);
    }
}

int main() {
    unsigned char key[3] = {0x01, 0x02, 0x03};
    unsigned char plaintext[24] = "This is a test string.";
    unsigned char result[3][8];

    des_encrypt(key, plaintext, result);

    for (int i = 0; i < 3; i++) {
        printf("Encrypted block %d: ", i);
        for (int j = 0; j < 8; j++) {
            printf("%02x ", result[i][j]);
        }
        printf("\n");
    }

    return 0;
}
