#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define MD4_BLOCK_SIZE 64
#define MD4_HASH_SIZE 16

typedef struct {
    uint32_t state[4];
    uint64_t count;
    uint8_t buffer[MD4_BLOCK_SIZE];
} MD4_CTX;

void md4_init(MD4_CTX *ctx) {
    ctx->state[0] = 0x67452301;
    ctx->state[1] = 0xEFCDAB89;
    ctx->state[2] = 0x98BADCFE;
    ctx->state[3] = 0x10325476;
    ctx->count = 0;
    memset(ctx->buffer, 0, MD4_BLOCK_SIZE);
}

static void md4_transform(uint32_t state[4], const uint8_t block[MD4_BLOCK_SIZE]) {
    uint32_t a = state[0], b = state[1], c = state[2], d = state[3];
    uint32_t x[16];

    memcpy(x, block, MD4_BLOCK_SIZE);

    // MD4 transformation rounds
    // Round 1
    a += (b & c) | (~b & d) + x[0]; a = (a << 3) | (a >> (32 - 3));
    d += (a & b) | (~a & c) + x[1]; d = (d << 7) | (d >> (32 - 7));
    c += (d & a) | (~d & b) + x[2]; c = (c << 11) | (c >> (32 - 11));
    b += (c & d) | (~c & a) + x[3]; b = (b << 19) | (b >> (32 - 19));
    // ... (continue with the rest of the rounds)

    // Round 2 and Round 3 would follow similarly
    // Final state update
    state[0] += a;
    state[1] += b;
    state[2] += c;
    state[3] += d;
}

void md4_update(MD4_CTX *ctx, const uint8_t *data, size_t len) {
    size_t i = 0, index = (size_t)(ctx->count >> 3) & 0x3F;
    ctx->count += ((uint64_t)len << 3);

    size_t partLen = MD4_BLOCK_SIZE - index;

    if (len >= partLen) {
        memcpy(&ctx->buffer[index], data, partLen);
        md4_transform(ctx->state, ctx->buffer);
        for (i = partLen; i + MD4_BLOCK_SIZE <= len; i += MD4_BLOCK_SIZE) {
            md4_transform(ctx->state, &data[i]);
        }
        index = 0;
    } else {
        i = 0;
    }

    memcpy(&ctx->buffer[index], &data[i], len - i);
}

void md4_final(MD4_CTX *ctx, uint8_t hash[MD4_HASH_SIZE]) {
    uint8_t padding[MD4_BLOCK_SIZE] = {0x80};
    size_t index = (size_t)(ctx->count >> 3) & 0x3F;
    size_t padLen = (index < 56) ? (56 - index) : (120 - index);

    md4_update(ctx, padding, padLen);
    uint8_t length[8];
    for (int i = 0; i < 8; i++) {
        length[i] = (uint8_t)((ctx->count >> (i * 8)) & 0xFF);
    }
    md4_update(ctx, length, 8);

    memcpy(hash, ctx->state, MD4_HASH_SIZE);
}

void md4(const uint8_t *data, size_t len, uint8_t hash[MD4_HASH_SIZE]) {
    MD4_CTX ctx;
    md4_init(&ctx);
    md4_update(&ctx, data, len);
    md4_final(&ctx, hash);
}
