void ModifyFileExtension(char *filename, int digits, const char *filetype) {
    char new_filename[PATH_MAX + 1];
    char *dot = strrchr(filename, '.');
    if (dot != NULL) {
        *dot = '\0'; // Remove the current extension
    }

    // Create the new filename with the specified number of digits and file type
    snprintf(new_filename, sizeof(new_filename), "%s%0*d.%s", filename, digits, 0, filetype);

