class Octree {
public:
    Octree(int featureSize, int numLeafNodes, int dataCapacity)
        : featureSize(featureSize), numLeafNodes(numLeafNodes), dataCapacity(dataCapacity) {
        initialize();
    }

    ~Octree() {
        delete[] prefixLeafs;
        delete[] data;
    }

private:
    int featureSize;
    int numLeafNodes;
    int dataCapacity;
    int* prefixLeafs = nullptr;
    float* data = nullptr;

    void initialize() {
        if (featureSize <= 0 || numLeafNodes <= 0 || dataCapacity <= 0) {
            throw std::invalid_argument("Feature size, number of leaf nodes, and data capacity must be positive.");
        }

        prefixLeafs = new int[numLeafNodes];
        if (!prefixLeafs) {
            throw std::runtime_error("Memory allocation for prefixLeafs failed.");
        }

        data = new float[dataCapacity * featureSize];
        if (!data) {
            delete[] prefixLeafs;
            throw std::runtime_error("Memory allocation for data failed.");
        }

        // Initialize prefixLeafs and data arrays
        for (int i = 0; i < numLeafNodes; ++i) {
            prefixLeafs[i] = 0; // or some other initialization logic
        }

        for (int i = 0; i < dataCapacity * featureSize; ++i) {
            data[i] = 0.0f; // or some other initialization logic
        }
    }
};
