#include <windows.h>
#include <stdio.h>
#include <stdlib.h>

char* get_jre_installation_path() {
    HKEY hKey;
    DWORD pathSize = MAX_PATH;
    char* jrePath = malloc(pathSize);

    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, 
                      "SOFTWARE\\JavaSoft\\Java Runtime Environment", 
                      0, 
                      KEY_READ, 
                      &hKey) == ERROR_SUCCESS) {

        // Query the current version
        char currentVersion[256];
        DWORD currentVersionSize = sizeof(currentVersion);
        if (RegQueryValueExA(hKey, "CurrentVersion", NULL, NULL, (LPBYTE)currentVersion, &currentVersionSize) == ERROR_SUCCESS) {

            // Open the key for the current version
            HKEY hCurrentVersionKey;
            if (RegOpenKeyExA(hKey, currentVersion, 0, KEY_READ, &hCurrentVersionKey) == ERROR_SUCCESS) {

                // Query the JRE installation path
                DWORD jrePathSize = pathSize;
                if (RegQueryValueExA(hCurrentVersionKey, "JavaHome", NULL, NULL, (LPBYTE)jrePath, &jrePathSize) == ERROR_SUCCESS) {
                    RegCloseKey(hCurrentVersionKey);
                    RegCloseKey(hKey);
                    return jrePath;
                }
                RegCloseKey(hCurrentVersionKey);
            }
        }
        RegCloseKey(hKey);
    }

    free(jrePath);
    return NULL;
}
