void createAndCheckSortedVectorSet() {
    // Create a random number of elements
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dist(1, 100);
    int numElements = dist(gen);

    // Populate the original set with random unique elements
    std::set<int> originalSet;
    while (originalSet.size() < numElements) {
        originalSet.insert(dist(gen));
    }

    // Convert the set to a sorted vector
    std::vector<int> sortedVector(originalSet.begin(), originalSet.end());

    // Check invariants: the vector should be sorted
    if (!std::is_sorted(sortedVector.begin(), sortedVector.end())) {
        std::cerr << "Invariant check failed: vector is not sorted." << std::endl;
        return;
    }

    // Create a new sorted vector set by inserting elements of the original set
    std::vector<int> newSortedVector;
    newSortedVector.insert(newSortedVector.end(), sortedVector.begin(), sortedVector.end());

    // Check that the two sets are equal
    if (sortedVector == newSortedVector) {
        std::cout << "The two sets are equal." << std::endl;
    } else {
        std::cerr << "The two sets are not equal." << std::endl;
    }
}

int main() {
    createAndCheckSortedVectorSet();
    return 0;
}
