class StaticTransformMessage {
public:
    std::string base_frame_id;
    std::string camera_frame_id;

    StaticTransformMessage(const std::string& base_id, const std::string& camera_id)
        : base_frame_id(base_id), camera_frame_id(camera_id) {}

    std::string to_string() const {
        std::ostringstream oss;
        oss << base_frame_id << " -> " << camera_frame_id;
        return oss.str();
    }
};

class MessageWriter {
public:
    void write(const std::string& filename, const std::map<std::string, StaticTransformMessage>& transforms) {
        std::ofstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Could not open file for writing: " + filename);
        }

        for (const auto& pair : transforms) {
            file << pair.second.to_string() << std::endl;
        }

        file.close();
    }
};

void save_transforms(const std::string& prefix, const std::map<std::string, StaticTransformMessage>& camera_poses) {
    static int count = 0;
    std::string filename = prefix + std::to_string(count++) + ".txt";

    MessageWriter writer;
    writer.write(filename, camera_poses);
}
