class RobotClient {
public:
    RobotClient(const std::string& ip, int port) : server_ip(ip), server_port(port), sockfd(-1) {}

    bool initialize() {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            std::cerr << "Error creating socket." << std::endl;
            return false;
        }

        sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(server_port);
        inet_pton(AF_INET, server_ip.c_str(), &server_addr.sin_addr);

        if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
            std::cerr << "Connection failed." << std::endl;
            close(sockfd);
            return false;
        }

        return true;
    }

    bool sendCommand(const std::string& command) {
        if (send(sockfd, command.c_str(), command.size(), 0) < 0) {
            std::cerr << "Error sending command." << std::endl;
            return false;
        }
        return true;
    }

    std::string receiveResponse() {
        char buffer[1024] = {0};
        ssize_t bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            std::cerr << "Error receiving response." << std::endl;
            return "";
        }
        buffer[bytes_received] = '\0';
        return std::string(buffer);
    }

    void closeConnection() {
        if (sockfd != -1) {
            close(sockfd);
            sockfd = -1;
        }
    }

    ~RobotClient() {
        closeConnection();
    }

private:
    std::string server_ip;
    int server_port;
    int sockfd;
};

int main() {
    RobotClient client("192.168.1.100", 8080);

    if (!client.initialize()) {
        return 1;
    }

    std::string command;
    while (true) {
        std::cout << "Enter command (or 'exit' to quit): ";
        std::getline(std::cin, command);
        if (command == "exit") {
            break;
        }

        if (client.sendCommand(command)) {
            std::string response = client.receiveResponse();
            std::cout << "Response from robot: " << response << std::endl;
        }
    }

    client.closeConnection();
    return 0;
}
