void TestIndexedPropertiesWithExternalArrayData(v8::Isolate* isolate) {
    // Allocate memory for external data
    const int length = 5;
    int* external_data = new int[length]{1, 2, 3, 4, 5};

    // Create a new V8 context
    v8::HandleScope handle_scope(isolate);
    v8::Local<v8::Context> context = v8::Context::New(isolate);
    v8::Context::Scope context_scope(context);

    // Create a V8 Object
    v8::Local<v8::Object> obj = v8::Object::New(isolate);

    // Set indexed properties to external array data
    obj->SetIndexedPropertiesToExternalArrayData(
        external_data,
        v8::kExternalIntArray,
        length
    );

    // Check that the object has indexed properties in external array data
    for (int i = 0; i < length; i++) {
        v8::Local<v8::Value> value = obj->Get(context, i).ToLocalChecked();
        if (value->IsInt32()) {
            int32_t int_value = value->Int32Value(context).ToChecked();
            if (int_value != external_data[i]) {
                std::cerr << "Data mismatch at index " << i << ": expected " 
                          << external_data[i] << ", got " << int_value << std::endl;
            }
        } else {
            std::cerr << "Type mismatch at index " << i << std::endl;
        }
    }

    // Check the length
    if (obj->GetIndexedPropertiesExternalArrayDataLength() != length) {
        std::cerr << "Length mismatch: expected " << length 
                  << ", got " << obj->GetIndexedPropertiesExternalArrayDataLength() << std::endl;
    }

    // Free the external data
    delete[] external_data;
}
