std::vector<std::string> retrieveEntitiesByLayer(const std::string& layerName, SQLHDBC dbConnection) {
    if (layerName.empty()) {
        throw std::invalid_argument("Layer name cannot be empty");
    }

    std::vector<std::string> entityIds;
    SQLHSTMT stmt;
    SQLRETURN ret;

    // Prepare SQL statement
    std::string sql = "SELECT entity_id FROM entities WHERE layer_name = ?";
    ret = SQLAllocHandle(SQL_HANDLE_STMT, dbConnection, &stmt);
    if (ret != SQL_SUCCESS) {
        throw std::runtime_error("Failed to allocate statement handle");
    }

    ret = SQLPrepare(stmt, (SQLCHAR*)sql.c_str(), SQL_NTS);
    if (ret != SQL_SUCCESS) {
        SQLFreeHandle(SQL_HANDLE_STMT, stmt);
        throw std::runtime_error("Failed to prepare SQL statement");
    }

    // Bind parameters
    ret = SQLBindParameter(stmt, 1, SQL_PARAM_INPUT, SQL_C_CHAR, SQL_CHAR, layerName.length(), 0, (SQLCHAR*)layerName.c_str(), 0, nullptr);
    if (ret != SQL_SUCCESS) {
        SQLFreeHandle(SQL_HANDLE_STMT, stmt);
        throw std::runtime_error("Failed to bind parameter");
    }

    // Execute the statement
    ret = SQLExecute(stmt);
    if (ret != SQL_SUCCESS) {
        SQLFreeHandle(SQL_HANDLE_STMT, stmt);
        throw std::runtime_error("Failed to execute SQL statement");
    }

    // Fetch results
    SQLCHAR entityId[256];
    while (SQLFetch(stmt) == SQL_SUCCESS) {
        SQLGetData(stmt, 1, SQL_C_CHAR, entityId, sizeof(entityId), nullptr);
        entityIds.push_back(reinterpret_cast<char*>(entityId));
    }

    // Clean up
    SQLFreeHandle(SQL_HANDLE_STMT, stmt);
    return entityIds;
}
