#include <openssl/aes.h>
#include <openssl/ripemd.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

#define AES_BLOCK_SIZE 16
#define HASH_SIZE 20 // RIPEMD-160 produces a 160-bit hash

unsigned char* ecies_encrypt(const unsigned char* plaintext, int plaintext_len, 
                             const unsigned char* key, int key_len, 
                             int* ciphertext_len) {
    EVP_CIPHER_CTX* ctx;
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char* ciphertext;
    int len;

    // Allocate memory for ciphertext
    ciphertext = (unsigned char*)malloc(plaintext_len + AES_BLOCK_SIZE);
    if (!ciphertext) return NULL;

    // Generate a random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        free(ciphertext);
        return NULL;
    }

    // Initialize the AES encryption context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        free(ciphertext);
        return NULL;
    }

    // Initialize the encryption operation
    if (EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        return NULL;
    }

    // Provide the plaintext to be encrypted
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        return NULL;
    }
    *ciphertext_len = len;

    // Finalize the encryption
    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        return NULL;
    }
    *ciphertext_len += len;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    // Prepend IV to ciphertext
    unsigned char* result = (unsigned char*)malloc(*ciphertext_len + AES_BLOCK_SIZE);
    memcpy(result, iv, AES_BLOCK_SIZE);
    memcpy(result + AES_BLOCK_SIZE, ciphertext, *ciphertext_len);
    free(ciphertext);

    return result;
}

unsigned char* ripemd160_hash(const unsigned char* data, int data_len) {
    unsigned char* hash = (unsigned char*)malloc(HASH_SIZE);
    if (!hash) return NULL;

    RIPEMD160(data, data_len, hash);
    return hash;
}
