#include <iostream>
#include <sstream>
#include <vector>
#include <string>

enum TileType {
    EMPTY,
    WALL,
    FLOOR,
    INVALID
};

TileType charToTileType(char c) {
    switch (c) {
        case 'E': return EMPTY;
        case 'W': return WALL;
        case 'F': return FLOOR;
        default: return INVALID;
    }
}

TileType** loadMapFromString(const std::string& mapString, int& rows, int& cols) {
    std::istringstream stream(mapString);
    std::string line;
    std::vector<std::vector<TileType>> map;

    while (std::getline(stream, line)) {
        std::vector<TileType> row;
        std::istringstream lineStream(line);
        char tileChar;

        while (lineStream >> tileChar) {
            TileType tile = charToTileType(tileChar);
            if (tile == INVALID) {
                std::cerr << "Invalid tile character: " << tileChar << std::endl;
                return nullptr;
            }
            row.push_back(tile);
        }
        map.push_back(row);
    }

    rows = map.size();
    if (rows == 0) return nullptr;

    cols = map[0].size();
    TileType** mapArray = new TileType*[rows];
    for (int i = 0; i < rows; ++i) {
        mapArray[i] = new TileType[cols];
        for (int j = 0; j < cols; ++j) {
            mapArray[i][j] = map[i][j];
        }
    }

    return mapArray;
}

// Example usage
int main() {
    std::string mapString = "E W F\nW F E\nF E W";
    int rows, cols;
    TileType** map = loadMapFromString(mapString, rows, cols);

    if (map) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                std::cout << map[i][j] << " ";
            }
            std::cout << std::endl;
        }

        // Clean up
        for (int i = 0; i < rows; ++i) {
            delete[] map[i];
        }
        delete[] map;
    }

    return 0;
}
