#include <memory>

struct Page {
    int id; // Unique identifier for the page
    void* data; // Pointer to the page data
};

class PageManager {
public:
    // Create a new page
    void createPage(int id, void* data) {
        if (pages.find(id) == pages.end()) {
            pages[id] = std::make_unique<Page>(Page{id, data});
        } else {
            std::cerr << "Page with ID " << id << " already exists." << std::endl;
        }
    }

    // Retrieve an existing page
    Page* retrievePage(int id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            return it->second.get();
        }
        return nullptr; // Return null if the page does not exist
    }

    // Delete a page
    void deletePage(int id) {
        auto it = pages.find(id);
        if (it != pages.end()) {
            pages.erase(it);
        } else {
            std::cerr << "Page with ID " << id << " does not exist." << std::endl;
        }
    }

private:
    std::map<int, std::unique_ptr<Page>> pages; // Map to store pages by their unique identifiers
};
