#include <iostream>
#include <set>

void generateWireframeIndices(int* inputArray, int size, 
                               int*& points, int*& lines, 
                               int*& faces, int*& lineIndices, 
                               int& primitiveCount) 
{
    // Allocate memory for indices
    points = new int[size];
    lines = new int[(size - 1) * 2]; // Assuming lines between consecutive points
    faces = new int[0]; // No faces in wireframe
    lineIndices = new int[(size - 1) * 2]; // Same as lines for wireframe representation

    // Copy input array to points
    for (int i = 0; i < size; ++i) {
        points[i] = inputArray[i];
    }

    // Generate lines indices
    for (int i = 0; i < size - 1; ++i) {
        lines[i * 2] = i;       // Start point index
        lines[i * 2 + 1] = i + 1; // End point index
    }

    // Set the primitive count
    primitiveCount = size - 1; // Number of lines

    // Initialize lineIndices same as lines for wireframe representation
    for (int i = 0; i < (size - 1) * 2; ++i) {
        lineIndices[i] = lines[i];
    }
}

// Example usage
int main() {
    int inputArray[] = {0, 1, 2, 3, 4};
    int size = sizeof(inputArray) / sizeof(inputArray[0]);

    int* points;
    int* lines;
    int* faces;
    int* lineIndices;
    int primitiveCount;

    generateWireframeIndices(inputArray, size, points, lines, faces, lineIndices, primitiveCount);

    // Clean up allocated memory
    delete[] points;
    delete[] lines;
    delete[] faces;
    delete[] lineIndices;

    return 0;
}
