#include <vector>
#include <set>
#include <iterator>

template <typename Container>
size_t CountUniqueElements(const Container& container) {
    std::set<typename Container::value_type> uniqueElements(container.begin(), container.end());
    return uniqueElements.size();
}

template <typename Container>
std::vector<size_t> GetUniqueElementCounts(const std::vector<Container>& containers) {
    std::vector<size_t> counts;
    counts.reserve(containers.size());

    for (const auto& container : containers) {
        counts.push_back(CountUniqueElements(container));
    }

    return counts;
}
