template<typename Iterator>
class Graph {
public:
    Graph(Iterator begin, Iterator end) {
        size_t vertex_count = std::distance(begin, end);
        if (vertex_count == 0) {
            throw std::invalid_argument("Vertex range cannot be empty");
        }

        adjacency_list.resize(vertex_count);
        degrees.resize(vertex_count, 0);
        heads.resize(vertex_count, nullptr);

        // Initialize heads
        for (size_t i = 0; i < vertex_count; ++i) {
            heads[i] = &adjacency_list[i];
        }
    }

    void add_edge(size_t from, size_t to) {
        if (from >= adjacency_list.size() || to >= adjacency_list.size()) {
            throw std::out_of_range("Vertex index out of range");
        }
        adjacency_list[from].push_back(to);
        degrees[from]++;
    }

    const std::vector<std::vector<size_t>>& get_adjacency_list() const {
        return adjacency_list;
    }

    const std::vector<size_t>& get_degrees() const {
        return degrees;
    }

private:
    std::vector<std::vector<size_t>> adjacency_list;
    std::vector<size_t> degrees;
    std::vector<std::vector<size_t>*> heads;
};
