#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <miniupnpc/miniupnpc.h>
#include <miniupnpc/upnpcommands.h>
#include <miniupnpc/upnpdev.h>

#define MAX_DEVICES 100

void discover_upnp_devices() {
    struct UPNPDev *devlist;
    struct UPNPUrls urls;
    struct IGDdatas data;
    char lanaddr[64];
    char buf[200];
    int i;

    // Initialize the UPnP library
    UPNP_GetUPNPUrls(&urls);
    devlist = upnpDiscover(2000, NULL, NULL, 0, &urls, NULL);

    if (devlist == NULL) {
        printf("No UPnP devices found.\n");
        return;
    }

    // Iterate through discovered devices
    for (i = 0; devlist != NULL && i < MAX_DEVICES; i++) {
        char *descURL = devlist->descURL;
        printf("Device %d: %s\n", i + 1, descURL);

        // Attempt to get device information
        if (UPNP_GetIGDInfo(&urls, &data, lanaddr, sizeof(lanaddr), buf, sizeof(buf)) == 1) {
            printf("Device found: %s\n", data.servicetype);
        } else {
            printf("Failed to get device info for %s\n", descURL);
        }

        devlist = devlist->pNext;
    }

    // Free resources
    freeUPNPUrls(&urls);
    freeUPNPDevlist(devlist);
}

int main() {
    discover_upnp_devices();
    return 0;
}
