std::string random_string(size_t length, const std::string& chars) {
    if (length == 0 || chars.empty()) {
        return "";
    }

    std::random_device rd;  // Obtain a random number from hardware
    std::mt19937 generator(rd());  // Seed the generator
    std::uniform_int_distribution<> distribution(0, chars.size() - 1);  // Define the range

    std::string result;
    for (size_t i = 0; i < length; ++i) {
        result += chars[distribution(generator)];
    }

    return result;
}

int main() {
    std::string characters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()";
    size_t length = 10;
    std::string randomStr = random_string(length, characters);
