std::vector<uint8_t> encryptWideString(const std::wstring& input) {
    std::vector<uint8_t> encryptedData;
    size_t len = input.length();

    for (size_t i = 0; i < len; ++i) {
        uint8_t byteData[2];
        memcpy(byteData, &input[i], sizeof(wchar_t));
