    pthread_create(&thread1, NULL, copy_and_print, (void*)original_string);
    pthread_create(&thread2, NULL, copy_and_print, (void*)original_string);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    pthread_mutex_destroy(&mutex);
    return 0;
}
