#include <stdio.h>
#include <string.h>

void format_signed_int(char *output, int value) {
    char buffer[50];
    char formatted[60];
    int len = 0;
    int is_negative = value < 0;
    unsigned int abs_value = is_negative ? -value : value;

    // Format the number with thousands separation
    sprintf(buffer, "%u", abs_value);
    int buffer_len = strlen(buffer);

    for (int i = 0; i < buffer_len; i++) {
        if (i > 0 && (buffer_len - i) % 3 == 0) {
            formatted[len++] = ',';
        }
        formatted[len++] = buffer[i];
    }

    if (is_negative) {
        formatted[len++] = '-';
    }

    formatted[len] = '\0';

    // Insert line breaks at 78 characters
    char final_output[100];
    int final_len = 0;
    for (int i = 0; i < len; i++) {
        if (final_len == 78) {
            final_output[final_len++] = '\n';
            final_len = 0;
        }
        final_output[final_len++] = formatted[i];
    }

    final_output[final_len] = '\0';
    strcpy(output, final_output);
}

int main() {
