                (*substrings)[count] = (UChar *)uprv_malloc((len + 1) * sizeof(UChar));
                memcpy((*substrings)[count], &input[start], len * sizeof(UChar));
                (*substrings)[count][len] = 0; // Null-terminate
                (*lengths)[count] = len;
                count++;
            }
            start = i + 1; // Move to the next character
        }
        i++;
