char *strip_whitespace(const char *input) {
    if (!input) {
        return NULL;
    }

    size_t length = strlen(input);
    char *result = malloc(length + 1);
    if (!result) {
        return NULL;
    }

    char *ptr = result;
    for (size_t i = 0; i < length; i++) {
        if (!isspace((unsigned char)input[i])) {
            *ptr++ = input[i];
        }
    }
    *ptr = '\0';

    return result;
