struct TreeNode {
    int value;
    std::vector<TreeNode*> children;

    TreeNode(int val) : value(val) {}
};

TreeNode* build_tree(int n, int* c) {
    if (n <= 0) return nullptr;

    std::vector<TreeNode*> nodes(n);
    for (int i = 0; i < n; ++i) {
        nodes[i] = new TreeNode(i); // Assigning node values as their indices
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 2; ++j) {
            int child_index = c[i * 2 + j];
            if (child_index >= 0 && child_index < n) {
                nodes[i]->children.push_back(nodes[child_index]);
            }
        }
    }

    return nodes[0]; // Return the root node
}
