void verifyFramebufferPixels(GLuint framebuffer, int width, int height, const std::vector<unsigned char>& expectedPixels) {
    // Bind the framebuffer
    glBindFramebuffer(GL_FRAMEBUFFER, framebuffer);

    // Read pixels from the framebuffer
    std::vector<unsigned char> pixels(width * height * 4); // Assuming RGBA format
    glReadPixels(0, 0, width, height, GL_RGBA, GL_UNSIGNED_BYTE, pixels.data());

    // Unbind the framebuffer
    glBindFramebuffer(GL_FRAMEBUFFER, 0);

    // Verify the pixels
    if (pixels.size() != expectedPixels.size()) {
        throw std::runtime_error("Pixel data size mismatch");
    }

    if (std::memcmp(pixels.data(), expectedPixels.data(), pixels.size()) != 0) {
        throw std::runtime_error("Pixel data does not match expected output");
    }
}
