import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import javax.imageio.ImageIO;
import java.io.IOException;

public class ImageGenerator {

    public byte[] generatePPMImage(PageDocument document, int pageNumber, int displayWidth, int displayHeight) throws IOException {
        BufferedImage pageImage = document.getPageImage(pageNumber);
        BufferedImage scaledImage = new BufferedImage(displayWidth, displayHeight, BufferedImage.TYPE_INT_RGB);

        // Scale the image to fit the specified display size
        scaledImage.getGraphics().drawImage(pageImage.getScaledInstance(displayWidth, displayHeight, java.awt.Image.SCALE_SMOOTH), 0, 0, null);

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        // Write the image data to a byte array in PPM format
        ImageIO.write(scaledImage, "ppm", baos);

        return baos.toByteArray();
    }
}
