#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <cstdint>

enum class Format {
    XML,
    BINARY,
    COLLADA
};

void saveData(const std::vector<std::string>& data, const std::string& filename, Format format) {
    std::ofstream file;
    file.open(filename, std::ios::binary);

    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return;
    }

    switch (format) {
        case Format::XML:
            file << "<data>\n";
            for (const auto& item : data) {
                file << "  <item>" << item << "</item>\n";
            }
            file << "</data>\n";
            std::cout << "Saved to " << filename << " in XML format." << std::endl;
            break;

        case Format::BINARY:
            for (const auto& item : data) {
                uint32_t length = static_cast<uint32_t>(item.size());
                file.write(reinterpret_cast<const char*>(&length), sizeof(length));
                file.write(item.c_str(), length);
            }
            std::cout << "Saved to " << filename << " in BINARY format." << std::endl;
            break;

        case Format::COLLADA:
            file << "<COLLADA xmlns=\"http://www.collada.org/2005/11/COLLADASchema\">\n";
            file << "  <library_physics_engines>\n";
            for (const auto& item : data) {
                file << "    <physics_material id=\"" << item << "\"/>\n";
            }
            file << "  </library_physics_engines>\n";
            file << "</COLLADA>\n";
            std::cout << "Saved to " << filename << " in COLLADA format." << std::endl;
            break;
    }

    file.close();
}
