void generate_random_image(int width, int height) {
    std::vector<std::vector<int>> image(height, std::vector<int>(width));
    std::mt19937 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<int> dist(0, 255);

    // Fill the image with random values
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            image[i][j] = dist(rng);
        }
    }

    // Measure performance of different access methods
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int value = image[i][j]; // Direct indexing
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto direct_indexing_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int value = image.at(i).at(j); // Boundary clamping
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto boundary_clamping_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int value = *(image[i].data() + j); // Scalar access
        }
    }
    end = std::chrono::high_resolution_clock::now();
    auto scalar_access_time = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

    // Output execution times
    std::cout << "Direct Indexing Time: " << direct_indexing_time << " microseconds\n";
    std::cout << "Boundary Clamping Time: " << boundary_clamping_time << " microseconds\n";
    std::cout << "Scalar Access Time: " << scalar_access_time << " microseconds\n";
}

int main() {
