void verticalFlip(void *pixels, size_t width, size_t height, size_t pixelSize) {
    if (pixels == NULL || width == 0 || height == 0) {
        return;
    }

    size_t stride = width * pixelSize;
    void *lineBuffer = malloc(stride);
    if (lineBuffer == NULL) {
        return; // Handle memory allocation failure
    }

    unsigned char *top = static_cast<unsigned char *>(pixels);
    unsigned char *bottom = top + (height - 1) * stride;

    for (size_t y = 0; y < height / 2; ++y) {
        memcpy(lineBuffer, top, stride);
        memcpy(top, bottom, stride);
        memcpy(bottom, lineBuffer, stride);
        top += stride;
        bottom -= stride;
    }

    free(lineBuffer);
}
