#include <iostream>
#include <vector>
#include <random>
#include <cmath>

void MatrixProjectionTest(int numSamples, int tableSize, int inputDim) {
    // Generate random matrix and vector
    std::vector<std::vector<float>> matrix(tableSize, std::vector<float>(inputDim));
    std::vector<float> vector(inputDim);

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<float> dis(0.0f, 1.0f);

    for (int i = 0; i < tableSize; ++i) {
        for (int j = 0; j < inputDim; ++j) {
            matrix[i][j] = dis(gen);
        }
    }

    for (int i = 0; i < inputDim; ++i) {
        vector[i] = dis(gen);
    }

    // Perform projection
    std::vector<float> projected(tableSize, 0.0f);
    for (int i = 0; i < tableSize; ++i) {
        for (int j = 0; j < inputDim; ++j) {
            projected[i] += matrix[i][j] * vector[j];
        }
    }

    // Reference implementation (for comparison)
    std::vector<float> referenceProjected(tableSize, 0.0f);
    for (int i = 0; i < tableSize; ++i) {
        for (int j = 0; j < inputDim; ++j) {
            referenceProjected[i] += matrix[i][j] * vector[j]; // Same operation for simplicity
        }
    }

    // Log the results
    std::cout << "Inputs: numSamples=" << numSamples << ", tableSize=" << tableSize 
              << ", inputDim=" << inputDim << std::endl;
    std::cout << "Projected Output: ";
    for (const auto& val : projected) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    std::cout << "Reference Output: ";
    for (const auto& val : referenceProjected) {
        std::cout << val << " ";
    }
    std::cout << std::endl;
}
