#include <string>

bool is_process_running(const std::string& pid_file, const std::string& magic_number) {
    std::ifstream file(pid_file);
    if (!file.is_open()) {
        std::cerr << "Could not open PID file: " << pid_file << std::endl;
        return false;
    }

    std::string pid;
    std::getline(file, pid);
    file.close();

    if (pid == magic_number) {
        return true;
    }
    return false;
}

void check_process_status(const std::string& pid_file, const std::string& magic_number) {
    if (is_process_running(pid_file, magic_number)) {
        std::cout << "Process with PID " << magic_number << " is running." << std::endl;
    } else {
        std::cout << "Process is not running. Please run the command as root for more precise information." << std::endl;
    }
}

int main(int argc, char* argv[]) {
