#include <stdlib.h>
#include <string.h>

char* generateInsertSQL(const char* tableName, const char* geometryColumn, const char* fidColumn, const char* featureValues) {
    // Allocate memory for the SQL command
    size_t sqlSize = strlen("INSERT INTO  () VALUES ();") + strlen(tableName) + strlen(featureValues) + 
                     (geometryColumn ? strlen(geometryColumn) : 0) + 
                     (fidColumn ? strlen(fidColumn) : 0) + 3; // for commas and null terminator
    char* sqlCommand = (char*)malloc(sqlSize);

    if (sqlCommand == NULL) {
        return NULL; // Memory allocation failed
    }

    // Start building the SQL command
    strcpy(sqlCommand, "INSERT INTO ");
    strcat(sqlCommand, tableName);
    strcat(sqlCommand, " (");

    // Add FID column if provided
    if (fidColumn) {
        strcat(sqlCommand, fidColumn);
        strcat(sqlCommand, ", ");
    }

    // Add geometry column if provided
    if (geometryColumn) {
        strcat(sqlCommand, geometryColumn);
        strcat(sqlCommand, ", ");
    }

    // Add the feature values
    strcat(sqlCommand, "values (");
    strcat(sqlCommand, featureValues);
    strcat(sqlCommand, ");");

    return sqlCommand;
}
