double optimizeModularity(Graph& graph, int maxPasses, double epsilon) {
    double currentModularity = graph.calculateModularity();
    double newModularity = currentModularity;
    int passes = 0;

    while (passes < maxPasses) {
        bool improved = false;

        for (int node : graph.getNodes()) {
            graph.rearrangeNode(node);
            newModularity = graph.calculateModularity();

            if (newModularity - currentModularity > epsilon) {
                currentModularity = newModularity;
                improved = true;
            } else {
                // Revert the rearrangement if no significant improvement
                graph.rearrangeNode(node); // Assuming this reverts the change
            }
        }

        if (!improved) {
            break; // Stop if no improvement
        }

        passes++;
    }

    return currentModularity;
}
