#include <vector>
#include <string>
#include <fstream>
#include <iostream>
#include <cstdint>

std::vector<std::vector<uint8_t>> load_descriptors(const std::vector<std::string>& training_files, bool include_alpha) {
    std::vector<std::vector<uint8_t>> descriptors;
    size_t total_descriptors = 0;

    for (const auto& file_path : training_files) {
        std::ifstream file(file_path, std::ios::binary);
        if (!file) {
            std::cerr << "Error opening file: " << file_path << std::endl;
            continue;
        }

        std::vector<uint8_t> file_descriptors;
        uint8_t value;
        while (file.read(reinterpret_cast<char*>(&value), sizeof(value))) {
            file_descriptors.push_back(value);
        }

        if (include_alpha) {
            // Add additional dimensions for alpha values
            for (size_t i = 0; i < file_descriptors.size(); ++i) {
                file_descriptors.push_back(255); // Assuming full alpha value
            }
        }

        total_descriptors += file_descriptors.size();
        descriptors.push_back(std::move(file_descriptors));
    }

    // Resize the matrix to total descriptors
    std::vector<std::vector<uint8_t>> result(total_descriptors, std::vector<uint8_t>(include_alpha ? 2 : 1));
    size_t index = 0;

    for (const auto& desc : descriptors) {
        for (size_t i = 0; i < desc.size(); ++i) {
            result[index][0] = desc[i];
            if (include_alpha) {
                result[index][1] = 255; // Assuming full alpha value
            }
            index++;
        }
    }

    return result;
}
