#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *constraint;
} QueryObject;

void addConstraint(QueryObject *query, const char *state) {
    if (query == NULL || state == NULL) {
        fprintf(stderr, "Invalid query object or state.\n");
        return;
    }

    query->constraint = (char *)malloc(strlen(state) + 1);
    if (query->constraint == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    strcpy(query->constraint, state);

    printf("Added constraint: %s\n", query->constraint);
}

QueryObject *createQueryObject(const char *state) {
    QueryObject *query = (QueryObject *)malloc(sizeof(QueryObject));
    if (query == NULL) {
        fprintf(stderr, "Memory allocation for query object failed.\n");
        return NULL;
    }

    addConstraint(query, state);
    return query;
}
