std::string get_ip_address(const HostAddress& host) {
    char ip_str[INET6_ADDRSTRLEN];

    if (host.addr.ss_family == AF_INET) {
        sockaddr_in* addr_in = reinterpret_cast<sockaddr_in*>(&host.addr);
        if (inet_ntop(AF_INET, &addr_in->sin_addr, ip_str, sizeof(ip_str)) == nullptr) {
