#include <vector>
#include <random>
#include <stdexcept>

std::vector<float>& initializeEmbeddingLayer(size_t embeddingSize, size_t labelWidth, size_t numLabelTypes, float stddev) {
    if (embeddingSize == 0 || labelWidth == 0 || numLabelTypes == 0) {
        throw std::invalid_argument("Embedding size, label width, and number of label types must be greater than zero.");
    }

    size_t totalWeights = embeddingSize * labelWidth * numLabelTypes;
    static std::vector<float> weights(totalWeights);

    std::random_device rd;
    std::mt19937 generator(rd());
    std::normal_distribution<float> distribution(0.0f, stddev);

    for (size_t i = 0; i < totalWeights; ++i) {
        weights[i] = distribution(generator);
    }

    return weights;
}
