int main(int argc, char* argv[]) {
    if (argc < 5) {
        std::cerr << "Usage: " << argv[0] << " <server_address> <username> <password> <bucket_name> [query]" << std::endl;
        return 1;
    }

    std::string server_address = argv[1];
    std::string username = argv[2];
    std::string password = argv[3];
    std::string bucket_name = argv[4];
    std::string query = (argc > 5) ? argv[5] : "SELECT * FROM `" + bucket_name + "`";

    try {
        couchbase::cluster cluster(server_address, username, password);
        auto bucket = cluster.bucket(bucket_name);
        bucket.wait_until_ready();

        couchbase::query_options options;
        auto result = cluster.query(query, options);

        for (const auto& row : result.rows()) {
            std::cout << row << std::endl;
        }
    } catch (const couchbase::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
