#include <CL/cl.h>
#include <vector>
#include <stdexcept>

void executeOpenCLKernel(cl_context context, cl_command_queue queue, cl_program program, 
                          const std::vector<float>& inputData, std::vector<float>& outputData, 
                          std::vector<float>& tempStorage) {
    cl_int err;

    // Allocate device memory
    cl_mem inputBuffer = clCreateBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, 
                                        inputData.size() * sizeof(float), 
                                        (void*)inputData.data(), &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create input buffer");

    cl_mem outputBuffer = clCreateBuffer(context, CL_MEM_WRITE_ONLY, 
                                         outputData.size() * sizeof(float), nullptr, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create output buffer");

    cl_mem tempBuffer = clCreateBuffer(context, CL_MEM_READ_WRITE, 
                                       tempStorage.size() * sizeof(float), nullptr, &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create temp buffer");

    // Set kernel arguments
    cl_kernel kernel = clCreateKernel(program, "myKernel", &err);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to create kernel");

    err = clSetKernelArg(kernel, 0, sizeof(cl_mem), &inputBuffer);
    err |= clSetKernelArg(kernel, 1, sizeof(cl_mem), &outputBuffer);
    err |= clSetKernelArg(kernel, 2, sizeof(cl_mem), &tempBuffer);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to set kernel arguments");

    // Execute the kernel
    size_t globalWorkSize = inputData.size();
    err = clEnqueueNDRangeKernel(queue, kernel, 1, nullptr, &globalWorkSize, nullptr, 0, nullptr, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to enqueue kernel");

    // Copy data back to host
    err = clEnqueueReadBuffer(queue, outputBuffer, CL_TRUE, 0, 
                               outputData.size() * sizeof(float), 
                               outputData.data(), 0, nullptr, nullptr);
    if (err != CL_SUCCESS) throw std::runtime_error("Failed to read output buffer");

    // Clean up
    clReleaseMemObject(inputBuffer);
    clReleaseMemObject(outputBuffer);
    clReleaseMemObject(tempBuffer);
    clReleaseKernel(kernel);
}
