class PacketSender {
public:
    PacketSender(double max_packet_rate)
        : max_packet_rate(max_packet_rate), packet_count(0), total_rtt(0), total_packets(0), lost_packets(0) {}

    void send_packet(int packet_number) {
        packet_count++;

        // Simulate packet loss
        if (simulate_packet_loss()) {
            lost_packets++;
            std::cout << "Packet " << packet_number << " dropped due to packet loss simulation." << std::endl;
            return;
        }

