            start_monitoring();
        }

        // Simulate sending packet and calculate RTT
        auto rtt = simulate_rtt();
        total_rtt += rtt;
        total_packets++;
        std::cout << "Packet " << packet_number << " sent with RTT: " << rtt << " ms." << std::endl;

        // Stop monitoring if conditions are met
        if (packet_number >= 2.2 * max_packet_rate) {
            stop_monitoring();
        }
    }

private:
    double max_packet_rate;
    int packet_count;
    double total_rtt;
    int total_packets;
    int lost_packets;
    bool monitoring_active = false;

    bool simulate_packet_loss() {
        return (rand() % 100) < 10; // 10% packet loss simulation
    }

    double simulate_rtt() {
        return static_cast<double>(rand() % 100) + 1; // RTT between 1 and 100 ms
    }

    void start_monitoring() {
        if (!monitoring_active) {
            monitoring_active = true;
            std::cout << "Monitoring started." << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(random_duration())));
        }
    }

    void stop_monitoring() {
        if (monitoring_active) {
            monitoring_active = false;
            double packet_loss_rate = static_cast<double>(lost_packets) / total_packets * 100;
            std::cout << "Monitoring stopped. Average RTT: " << (total_rtt / total_packets) 
                      << " ms, Packet loss rate: " << packet_loss_rate << "%" << std::endl;
        }
    }

    double random_duration() {
        std::uniform_real_distribution<double> distribution(1.7 * max_packet_rate, 2.2 * max_packet_rate);
        return distribution(rand());
    }
};
