#include <iostream>
#include <fstream>
#include <cstdint>

struct HeightMap {
    int width;
    int height;
    int* data;
};

HeightMap* readBitmapAsHeightMap(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file) {
        std::cerr << "Error opening file." << std::endl;
        return nullptr;
    }

    // Read the bitmap file header
    file.seekg(18); // Width offset
    int width, height;
    file.read(reinterpret_cast<char*>(&width), sizeof(int));
    file.read(reinterpret_cast<char*>(&height), sizeof(int));

    // Allocate memory for the height map
    HeightMap* heightMap = new HeightMap;
    heightMap->width = width;
    heightMap->height = height;
    heightMap->data = new int[width * height];

    // Read pixel data
    file.seekg(54); // Pixel data offset
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            uint8_t pixel[3]; // Assuming 24-bit BMP (BGR format)
            file.read(reinterpret_cast<char*>(pixel), 3);
            // Convert BGR to height value (using the average of RGB)
            heightMap->data[y * width + x] = (pixel[0] + pixel[1] + pixel[2]) / 3;
        }
    }

    file.close();
    return heightMap;
}
