#include <vector>
#include <cstdlib>
#include <ctime>
#include <algorithm>
#include <iostream>

std::pair<int, bool> selectClosestSubset(const std::vector<int>& nums, int target) {
    std::srand(std::time(0));
    int closestSum = 0;
    bool targetReached = false;
    int minCount = nums.size() + 1;

    for (int iteration = 0; iteration < 1000; ++iteration) {
        std::vector<int> selected;
        int currentSum = 0;

        // Randomly select integers from the set
        for (int i = 0; i < nums.size(); ++i) {
            if (std::rand() % 2) { // Randomly include or exclude
                selected.push_back(nums[i]);
                currentSum += nums[i];
            }
        }

        // Check if the current sum is closer to the target
        if (currentSum <= target) {
            if (currentSum == target) {
                targetReached = true;
                return {currentSum, targetReached};
            }
            if (currentSum > closestSum || (currentSum < closestSum && selected.size() < minCount)) {
                closestSum = currentSum;
                minCount = selected.size();
            }
        }
    }

    return {closestSum, targetReached};
}

// Example usage
int main() {
    std::vector<int> nums = {1, 2, 3, 4, 5};
    int target = 10;
    auto result = selectClosestSubset(nums, target);
    std::cout << "Closest Sum: " << result.first << ", Target Reached: " << std::boolalpha << result.second << std::endl;
    return 0;
}
