#include <iostream>

enum DataType {
    BIGINT
};

enum Mode {
    REQUIRED,
    OPTIONAL,
    REPEATED
};

struct FieldMetadata {
    DataType type;
    Mode mode;
};

void printBufferContents(FieldMetadata* metadata, void* buffer) {
