#include <boost/python.hpp>
#include <openssl/sha.h>
#include <openssl/evp.h>
#include <string>
#include <vector>
#include <iomanip>
#include <sstream>

std::string derive_key(const std::string& password, const std::string& master_key, size_t output_length) {
    std::vector<unsigned char> derived_key(SHA_DIGEST_LENGTH);
    unsigned int iterations = 1;
    size_t key_length = output_length;

    std::string concatenated = password + master_key;
    unsigned char hash[SHA_DIGEST_LENGTH];

    while (key_length > 0) {
        SHA1(reinterpret_cast<const unsigned char*>(concatenated.c_str()), concatenated.size(), hash);
        for (size_t i = 0; i < SHA_DIGEST_LENGTH && key_length > 0; ++i, --key_length) {
            derived_key.push_back(hash[i]);
        }
        concatenated = std::string(reinterpret_cast<const char*>(hash), SHA_DIGEST_LENGTH);
        iterations++;
    }

    std::ostringstream oss;
    for (const auto& byte : derived_key) {
        oss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(byte);
    }
    return oss.str();
}

BOOST_PYTHON_MODULE(crypto) {
    using namespace boost::python;
    def("derive_key", derive_key);
}
