void* aligned_malloc(size_t size) {
    const size_t cache_line_size = 64; // Example cache line size
    size_t alignment = cache_line_size;

    // Allocate memory with extra space for alignment
    void* ptr = malloc(size + alignment - 1 + sizeof(void*));
    if (!ptr) {
        return NULL; // Allocation failed
    }

    // Calculate aligned address
    void* aligned_ptr = (void*)(((size_t)ptr + sizeof(void*) + alignment - 1) & ~(alignment - 1));

    // Store the original pointer just before the aligned pointer
    *((void**)(aligned_ptr) - 1) = ptr;

    // Verify alignment
    if ((size_t)aligned_ptr % alignment != 0) {
        free(ptr); // Free original pointer if alignment check fails
        return NULL;
    }

    return aligned_ptr;
}

void aligned_free(void* ptr) {
    if (ptr) {
        // Retrieve the original pointer and free it
        free(*((void**)ptr - 1));
    }
}

