wchar_t* read_file_as_unicode(const char* path) {
    FILE* file = fopen(path, "r, ccs=UTF-8");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    wchar_t* content = (wchar_t*)malloc((length + 1) * sizeof(wchar_t));
    if (content == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    size_t read_length = fread(content, sizeof(wchar_t), length / sizeof(wchar_t), file);
    content[read_length] = L'\0';

    fclose(file);
    return content;
}
