#include <ctime>

typedef std::vector<std::vector<float>> Image;

Image convolution(const Image &inputImage, int filterSize, int stride, float bias) {
    int inputHeight = inputImage.size();
    int inputWidth = inputImage[0].size();
    int outputHeight = (inputHeight - filterSize) / stride + 1;
    int outputWidth = (inputWidth - filterSize) / stride + 1;

    Image outputImage(outputHeight, std::vector<float>(outputWidth, 0));

    // Initialize filter with random values
    std::srand(static_cast<unsigned int>(std::time(0)));
    std::vector<std::vector<float>> filter(filterSize, std::vector<float>(filterSize));
    for (int i = 0; i < filterSize; ++i) {
        for (int j = 0; j < filterSize; ++j) {
            filter[i][j] = static_cast<float>(std::rand()) / RAND_MAX; // Random value between 0 and 1
        }
    }

    // Perform convolution
    for (int y = 0; y < outputHeight; ++y) {
        for (int x = 0; x < outputWidth; ++x) {
            float sum = 0.0f;
            for (int fy = 0; fy < filterSize; ++fy) {
                for (int fx = 0; fx < filterSize; ++fx) {
                    sum += inputImage[y * stride + fy][x * stride + fx] * filter[fy][fx];
                }
            }
            outputImage[y][x] = sum + bias;
        }
    }

    return outputImage;
}
