#include <stdio.h>
#include <stdarg.h>
#include <string.h>

int my_asnprintf(char *buffer, size_t buffer_size, const char *format, ...) {
    va_list args;
    int written;

    va_start(args, format);
    if (buffer == NULL) {
        // Calculate the required size
        written = vsnprintf(NULL, 0, format, args);
        va_end(args);
        return (written < 0) ? -1 : written;
    }

    // Reset args to use it again for vsnprintf
    va_start(args, format);
    written = vsnprintf(buffer, buffer_size, format, args);
    va_end(args);

    if (written < 0 || (size_t)written >= buffer_size) {
        return -1;
    }

    return written;
}
