#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_TOKENS 100
#define MAX_TOKEN_LENGTH 50

char** parse_tokens(const char* input, int* token_count) {
    char** tokens = malloc(MAX_TOKENS * sizeof(char*));
    char buffer[MAX_TOKEN_LENGTH];
    int buf_pos = 0;
    *token_count = 0;

    const char* ptr = input;
    while (*ptr) {
        // Skip leading whitespace
        while (isspace((unsigned char)*ptr)) {
            ptr++;
        }

        // Reset buffer
        buf_pos = 0;

        // Check for negative sign or digit
        if (*ptr == '-' || isdigit((unsigned char)*ptr)) {
            while (isdigit((unsigned char)*ptr) || *ptr == '-') {
                if (buf_pos < MAX_TOKEN_LENGTH - 1) {
                    buffer[buf_pos++] = *ptr;
                }
                ptr++;
            }
            buffer[buf_pos] = '\0';
            if (buf_pos > 0) {
                tokens[*token_count] = strdup(buffer);
                (*token_count)++;
            }
        }
        // Check for quoted string
        else if (*ptr == '\"') {
            ptr++;
            while (*ptr && *ptr != '\"') {
                if (buf_pos < MAX_TOKEN_LENGTH - 1) {
                    buffer[buf_pos++] = *ptr;
                }
                ptr++;
            }
            if (*ptr == '\"') {
                buffer[buf_pos] = '\0';
                tokens[*token_count] = strdup(buffer);
                (*token_count)++;
                ptr++; // Skip closing quote
            }
        } else {
            // Move to next character if not a valid token
            ptr++;
        }
    }

    return tokens;
}

void free_tokens(char** tokens, int token_count) {
    for (int i = 0; i < token_count; i++) {
        free(tokens[i]);
    }
    free(tokens);
}

int main() {
    const char* input = "  -123 \"hello world\" 42 -456 \"another string\" ";
    int token_count = 0;
    char** tokens = parse_tokens(input, &token_count);

    for (int i = 0; i < token_count; i++) {
        printf("Token %d: %s\n", i + 1, tokens[i]);
    }

    free_tokens(tokens, token_count);
    return 0;
}
