std::vector<std::string> extract_url_components(const std::string& url) {
    std::vector<std::string> components(3); // protocol, host, port
    std::string::size_type pos = 0;

    // Extract protocol
    pos = url.find("://");
    if (pos != std::string::npos) {
        components[0] = url.substr(0, pos);
        pos += 3; // Move past "://"
    } else {
        components[0] = ""; // No protocol found
        pos = 0;
    }

    // Extract host and port
    std::string::size_type host_end = url.find('/', pos);
    std::string::size_type port_start = url.find(':', pos);

    if (port_start != std::string::npos && (host_end == std::string::npos || port_start < host_end)) {
        components[1] = url.substr(pos, port_start - pos); // host
        std::string::size_type port_end = host_end != std::string::npos ? host_end : url.length();
        components[2] = url.substr(port_start + 1, port_end - port_start - 1); // port
    } else {
        components[1] = host_end != std::string::npos ? url.substr(pos, host_end - pos) : url.substr(pos);
        components[2] = "80"; // Default port
    }

    return components;
}
