        sendGetRequest();
    }

    void sendGetRequest() {
        // Prepare GET request
        std::string request = "GET /api/resource HTTP/1.1\r\nHost: " + server_ + "\r\n\r\n";
        boost::asio::async_write(socket_, boost::asio::buffer(request),
            boost::bind(&SandeshClient::handleWrite, this, boost::asio::placeholders::error));
    }

    void handleWrite(const boost::system::error_code& error) {
        if (!error) {
            request_count_++;
            boost::asio::async_read_until(socket_, response_, "\r\n",
                boost::bind(&SandeshClient::handleRead, this, boost::asio::placeholders::error));
        } else {
            internal_errors_++;
            std::cerr << "Error on write: " << error.message() << std::endl;
        }
