#include <string.h>

#define MAX_DATES 100
#define DATE_FORMAT_LENGTH 11 // "dd. mm. yyyy" + null terminator

// Function to convert Haab date to days
int haab_to_days(int day, int month, int year) {
    // Haab calendar has 18 months of 20 days and 5 extra days
    int days_in_months = month * 20 + day;
    return days_in_months + (year * 365); // Assuming no leap years for simplicity
}

int main() {
    char dates[MAX_DATES][DATE_FORMAT_LENGTH];
    int num_dates = 0;
    char input[DATE_FORMAT_LENGTH];

    // Read dates from standard input
    while (fgets(input, sizeof(input), stdin) && num_dates < MAX_DATES) {
        input[strcspn(input, "\n")] = 0; // Remove newline character
        strcpy(dates[num_dates++], input);
    }

    if (num_dates < 1) {
        printf("No dates provided.\n");
        return 1;
    }

    // Parse the first date
    int first_day, first_month, first_year;
    sscanf(dates[0], "%d. %d. %d", &first_day, &first_month, &first_year);
    int first_date_days = haab_to_days(first_day, first_month, first_year);

    // Calculate and print the number of days between the first date and each subsequent date
    for (int i = 1; i < num_dates; i++) {
        int day, month, year;
        sscanf(dates[i], "%d. %d. %d", &day, &month, &year);
        int current_date_days = haab_to_days(day, month, year);
        int days_difference = current_date_days - first_date_days;
        printf("%d\n", days_difference);
    }

    return 0;
}
