template<typename Container, typename Func>
void foreach(Container& container, Func func, bool& shouldBreak, bool& shouldContinue) {
    while (!container.empty()) {
        auto item = container.front();
        container.pop(); // Assuming the container supports pop() method

        if (shouldBreak) {
