#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

struct DataPacket {
    char CURP[10];
    char celular[10];
    char partido[5];
};

int main() {
    int sock;
    struct sockaddr_in server_addr;
    struct DataPacket packet;
    char response[1024];
    ssize_t bytes_sent, bytes_received;

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Server address setup
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // Change to your server port
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1"); // Change to your server IP

    // Connect to server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        exit(EXIT_FAILURE);
    }

    // Prepare data packet
    strncpy(packet.CURP, "CURP1234", sizeof(packet.CURP) - 1);
    strncpy(packet.celular, "1234567890", sizeof(packet.celular) - 1);
    strncpy(packet.partido, "PART", sizeof(packet.partido) - 1);

    // Send data packet
    bytes_sent = send(sock, &packet, sizeof(packet), 0);
    if (bytes_sent < 0) {
        perror("Send failed");
        close(sock);
        exit(EXIT_FAILURE);
    }

    // Receive response
    bytes_received = recv(sock, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        close(sock);
        exit(EXIT_FAILURE);
    }

    // Null-terminate and print response
    response[bytes_received] = '\0';
    printf("Response received: %s\n", response);

    // Close socket and exit
    close(sock);
    return 0;
}
