std::string formatString(const char* format, ...) {
    va_list args;
    va_start(args, format);

    // Initial buffer size
    size_t size = 128;
    char* buffer = (char*)malloc(size);
    if (!buffer) {
        va_end(args);
        throw std::bad_alloc();
    }

    // Try to format the string
    while (true) {
        va_list args_copy;
        va_copy(args_copy, args);
        int n = vsnprintf(buffer, size, format, args_copy);
        va_end(args_copy);

        // If the buffer is large enough, break
        if (n > -1 && n < (int)size) {
            break;
        }

        // Resize the buffer
        size = (n > -1) ? (size_t)n + 1 : size * 2;
        char* new_buffer = (char*)realloc(buffer, size);
        if (!new_buffer) {
            free(buffer);
            va_end(args);
            throw std::bad_alloc();
        }
        buffer = new_buffer;
    }

    std::string result(buffer);
    free(buffer);
    va_end(args);
    return result;
}
