#include <iostream>
#include <fstream>
#include <vector>
#include <stdexcept>

struct LinearRegression {
    double slope;
    double intercept;

    void fit(const std::vector<double>& x, const std::vector<double>& y) {
        if (x.size() != y.size() || x.empty()) {
            throw std::invalid_argument("Input vectors must be of the same size and not empty.");
        }

        double n = x.size();
        double sum_x = 0, sum_y = 0, sum_xy = 0, sum_x2 = 0;

        for (size_t i = 0; i < n; ++i) {
            sum_x += x[i];
            sum_y += y[i];
            sum_xy += x[i] * y[i];
            sum_x2 += x[i] * x[i];
        }

        slope = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x);
        intercept = (sum_y - slope * sum_x) / n;
    }
};

int main() {
    std::ifstream file("data.txt");
    if (!file.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return 1;
    }

    std::vector<double> x, y;
    double x_val, y_val;

    while (file >> x_val >> y_val) {
        x.push_back(x_val);
        y.push_back(y_val);
    }
    file.close();

    std::cout << "Number of data points: " << x.size() << std::endl;

    LinearRegression lr;
    lr.fit(x, y);

    std::cout << "Linear Regression Results:" << std::endl;
    std::cout << "Slope: " << lr.slope << std::endl;
    std::cout << "Intercept: " << lr.intercept << std::endl;

    return 0;
}
