class UnicodeString {
public:
    UnicodeString(const wchar_t* str) {
        if (!str) {
            throw std::invalid_argument("Null string provided");
        }
        size_t len = wcslen(str);
        ansiStr = new char[len + 1];
        for (size_t i = 0; i < len; ++i) {
            ansiStr[i] = static_cast<char>(str[i] & 0xFF);
