        delete[] ansiStr;
    }

    // Overload operator+
    UnicodeString operator+(const UnicodeString& other) const {
        size_t len1 = strlen(ansiStr);
        size_t len2 = strlen(other.ansiStr);
        char* newStr = new char[len1 + len2 + 1];
        strcpy(newStr, ansiStr);
        strcat(newStr, other.ansiStr);
        return UnicodeString(newStr);
    }

    // Overload operator==
    bool operator==(const UnicodeString& other) const {
        return strcmp(ansiStr, other.ansiStr) == 0;
    }

    const char* c_str() const {
        return ansiStr;
    }

private:
    char* ansiStr;
};
