char* readChildProcessOutput(const char* command) {
    int pipefd[2];
    pid_t pid;
    char* output = NULL;
    size_t total_length = 0;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        return NULL;
    }

    pid = fork();
    if (pid == -1) {
        perror("fork");
        close(pipefd[0]);
        close(pipefd[1]);
        return NULL;
    }

    if (pid == 0) { // Child process
        close(pipefd[0]); // Close read end
        dup2(pipefd[1], STDOUT_FILENO); // Redirect stdout to pipe
        dup2(pipefd[1], STDERR_FILENO); // Redirect stderr to pipe
        close(pipefd[1]); // Close write end after duplicating
        execlp(command, command, (char *)NULL); // Execute command
        perror("execlp"); // If exec fails
        exit(EXIT_FAILURE);
    } else { // Parent process
        close(pipefd[1]); // Close write end

        // Set the pipe to non-blocking
        fcntl(pipefd[0], F_SETFL, O_NONBLOCK);

        char buffer[128];
        ssize_t bytes_read;

        while (1) {
            bytes_read = read(pipefd[0], buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                total_length += bytes_read;
                output = realloc(output, total_length + 1);
                if (output == NULL) {
                    perror("realloc");
                    close(pipefd[0]);
                    return NULL;
                }
                strcat(output, buffer);
            } else if (bytes_read == -1 && errno != EAGAIN) {
                perror("read");
                break;
            } else {
                break; // No more data to read
            }
        }

        close(pipefd[0]); // Close read end
        waitpid(pid, NULL, 0); // Wait for child process to finish
    }

    return output;
}
