#include <stdlib.h>
#include <math.h>

typedef struct {
    float x;
    float y;
    float z;
} Point;

float length(Point p) {
    return sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
}

Point* compute_normals(Point* points, int num_points) {
    Point* normals = (Point*)alloca(num_points * sizeof(Point));
    for (int i = 1; i < num_points; i++) {
        Point p0 = points[i - 1];
        Point p1 = points[i];
        Point normal;
        normal.x = p1.x - p0.x;
        normal.y = p1.y - p0.y;
        normal.z = p1.z - p0.z;
        float len = length(normal);
        if (len > 0) {
            normal.x *= (1.0f / len);
            normal.y *= (1.0f / len);
            normal.z *= (1.0f / len);
        }
        normals[i - 1] = normal;
    }
    return normals;
}
