#include <wchar.h>
#include <locale.h>

wchar_t *read_file_as_unicode(const char *path) {
    setlocale(LC_ALL, ""); // Set locale for wide character support
    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    wchar_t *buffer = (wchar_t *)malloc((length + 1) * sizeof(wchar_t));
    if (!buffer) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t read_size = fread(buffer, sizeof(wchar_t), length / sizeof(wchar_t), file);
    if (read_size < length / sizeof(wchar_t)) {
        perror("Failed to read file");
        free(buffer);
        fclose(file);
        return NULL;
    }

    buffer[read_size] = L'\0'; // Null-terminate the string
    fclose(file);
    return buffer;
}
