static int process_message(struct socket *sock, struct msghdr *m, size_t buf_len, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *buf;
    struct tipc_msg *msg;
    unsigned int sz;
    u32 user_id;
    int res;

    /* Check for valid buffer length */
    if (unlikely(!buf_len))
        return -EINVAL;

    lock_sock(sk);

    /* Ensure the socket is connected */
    if (unlikely(sock->state == SS_UNCONNECTED)) {
        res = -ENOTCONN;
        goto exit;
    }

    /* Wait for a message to arrive */
    while (skb_queue_empty(&sk->sk_receive_queue)) {
        if (sock->state == SS_DISCONNECTING) {
            res = -ENOTCONN;
            goto exit;
        }
        release_sock(sk);
        wait_event_interruptible(*sk_sleep(sk), tipc_rx_ready(sock));
        lock_sock(sk);
    }

    /* Retrieve the first message from the queue */
    buf = skb_peek(&sk->sk_receive_queue);
    msg = buf_msg(buf);
    sz = msg_data_sz(msg);

    /* Extract user ID from the message (assuming it's at the start) */
    if (sz < sizeof(user_id)) {
        res = -EINVAL;
        goto exit;
    }
    skb_copy_from_linear_data(buf, &user_id, sizeof(user_id));

    /* Prepare the reply message */
    char reply[256];
    snprintf(reply, sizeof(reply), "Reply to user %u", user_id);

