#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int reduce_entries(int *entries, int size, int **unique_entries) {
    if (size == 0) {
        *unique_entries = NULL;
        return 0;
    }

    // Sort the entries
    qsort(entries, size, sizeof(int), compare);

    // Allocate memory for unique entries
    int *temp_unique = malloc(size * sizeof(int));
    if (!temp_unique) {
        return -1; // Memory allocation failed
    }

    int unique_count = 0;
    temp_unique[unique_count++] = entries[0];

    for (int i = 1; i < size; i++) {
        if (entries[i] != entries[i - 1]) {
            temp_unique[unique_count++] = entries[i];
        }
    }

    // Allocate final array for unique entries
    *unique_entries = malloc(unique_count * sizeof(int));
    if (!*unique_entries) {
        free(temp_unique);
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < unique_count; i++) {
        (*unique_entries)[i] = temp_unique[i];
    }

    free(temp_unique);
    return unique_count;
}
