        strncpy(parsed_id, endpoint_id, id_length);
        parsed_id[id_length] = '\0';
    } else {
        strncpy(parsed_id, endpoint_id, len);
        parsed_id[len] = '\0';
    }

    return ERROR_NONE;
}
