char** parse_name_value_pair(const char* input) {
    if (input == NULL) {
        return NULL;
    }

    // Trim leading and trailing whitespace
    while (isspace((unsigned char)*input)) input++;
    size_t len = strlen(input);
    while (len > 0 && isspace((unsigned char)input[len - 1])) len--;

    // Find the colon
    const char* colon = strchr(input, ':');
    if (colon == NULL || colon == input || colon - input == len - 1) {
        return NULL; // No colon or no value
    }

    // Allocate memory for the name and value
    char* name = (char*)malloc(colon - input + 1);
    char* value = (char*)malloc(len - (colon - input) + 1);
    if (name == NULL || value == NULL) {
        free(name);
        free(value);
        return NULL; // Memory allocation failed
    }

    // Copy name and value, trimming whitespace
    strncpy(name, input, colon - input);
    name[colon - input] = '\0';
    strncpy(value, colon + 1, len - (colon - input) - 1);
    value[len - (colon - input) - 1] = '\0';

    // Trim whitespace from name and value
    char* start = name;
    while (isspace((unsigned char)*start)) start++;
    memmove(name, start, strlen(start) + 1);

    start = value;
    while (isspace((unsigned char)*start)) start++;
    memmove(value, start, strlen(start) + 1);

    // Return the result as an array of strings
    char** result = (char**)malloc(2 * sizeof(char*));
    result[0] = name;
    result[1] = value;
    return result;
}
