#define BUFFER_SIZE 256

void aggregate_integers(int *list, size_t count, int key, char *output, size_t output_size) {
    if (output_size < 50) {
        snprintf(output, output_size, "ERROR: Buffer too small");
        return;
    }

    char buffer[BUFFER_SIZE];
    size_t offset = 0;
    int total_length = snprintf(buffer, BUFFER_SIZE, "AGGREGATED-OUTPUT[%d]: ", key);

    if (total_length < 0 || total_length >= BUFFER_SIZE) {
        snprintf(output, output_size, "ERROR: Buffer overflow");
        return;
    }

    offset += total_length;

    for (size_t i = 0; i < count; i++) {
        int length = snprintf(buffer + offset, BUFFER_SIZE - offset, "%d", list[i]);
        if (length < 0 || offset + length >= BUFFER_SIZE) {
            snprintf(output, output_size, "ERROR: Buffer overflow");
            return;
        }
        offset += length;

        if (i < count - 1) {
            if (offset < BUFFER_SIZE) {
                buffer[offset++] = ' ';
            } else {
                snprintf(output, output_size, "ERROR: Buffer overflow");
                return;
            }
        }
    }

    snprintf(output, output_size, "%s", buffer);
}
