    struct stat buffer;

    while (1) {
        printf("Enter a new name for the file (or 'skip' to skip): ");
        fgets(new_name, sizeof(new_name), stdin);
        new_name[strcspn(new_name, "\n")] = 0; // Remove newline character

        if (strcmp(new_name, "skip") == 0) {
            return 0; // Skip renaming
        }

        if (strlen(new_name) == 0 || strlen(new_name) >= MAX_FILENAME_LENGTH) {
            printf("Invalid name. Please try again.\n");
            continue;
        }

        if (stat(new_name, &buffer) == 0) {
            printf("File with the name '%s' already exists. Please choose another name.\n", new_name);
            continue;
        }

        if (rename(old_name, new_name) == 0) {
            printf("File renamed successfully from '%s' to '%s'.\n", old_name, new_name);
            return 1; // Successfully renamed
        } else {
            perror("Error renaming file");
            return -1; // Error occurred
        }
    }
}
