#include <iostream>
#include <vector>
#include <random>
#include <memory>

enum InputType {
    DENSE,
    SPARSE,
    SEQUENCE
};

class Matrix {
public:
    Matrix(size_t rows, size_t cols) : rows_(rows), cols_(cols) {
        data_ = std::make_unique<std::vector<float>>(rows * cols);
    }

    void randomize() {
        std::generate(data_->begin(), data_->end(), []() {
            return static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
        });
    }

    void print() const {
        for (size_t i = 0; i < rows_; ++i) {
            for (size_t j = 0; j < cols_; ++j) {
                std::cout << (*data_)[i * cols_ + j] << " ";
            }
            std::cout << std::endl;
        }
    }

private:
    size_t rows_;
    size_t cols_;
    std::unique_ptr<std::vector<float>> data_;
};

class SparseMatrix {
public:
    SparseMatrix(size_t rows, size_t cols, float sparsity) : rows_(rows), cols_(cols), sparsity_(sparsity) {
        generateSparseData();
    }

    void print() const {
        for (const auto& entry : data_) {
            std::cout << "Row: " << entry.first << ", Col: " << entry.second.first << ", Value: " << entry.second.second << std::endl;
        }
    }

private:
    void generateSparseData() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);

        for (size_t i = 0; i < rows_; ++i) {
            for (size_t j = 0; j < cols_; ++j) {
                if (dis(gen) < sparsity_) {
                    data_.emplace_back(i, std::make_pair(j, static_cast<float>(dis(gen))));
                }
            }
        }
    }

    size_t rows_;
    size_t cols_;
    float sparsity_;
    std::vector<std::pair<size_t, std::pair<size_t, float>>> data_;
};

class SequenceData {
public:
    SequenceData(size_t batch_size, size_t sequence_length) : batch_size_(batch_size), sequence_length_(sequence_length) {
        generateSequenceData();
    }

    void print() const {
        for (const auto& seq : data_) {
            for (const auto& val : seq) {
                std::cout << val << " ";
            }
            std::cout << std::endl;
        }
    }

private:
    void generateSequenceData() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);

        for (size_t i = 0; i < batch_size_; ++i) {
            std::vector<float> sequence(sequence_length_);
            std::generate(sequence.begin(), sequence.end(), [&]() { return static_cast<float>(dis(gen)); });
            data_.push_back(sequence);
        }
    }

    size_t batch_size_;
    size_t sequence_length_;
    std::vector<std::vector<float>> data_;
};

Matrix createRandomInputMatrix(size_t rows, size_t cols, InputType type, float sparsity = 0.1, size_t sequence_length = 10) {
    switch (type) {
        case DENSE: {
            Matrix matrix(rows, cols);
            matrix.randomize();
            return matrix;
        }
        case SPARSE: {
            SparseMatrix sparseMatrix(rows, cols, sparsity);
            sparseMatrix.print();
            break;
        }
        case SEQUENCE: {
            SequenceData sequenceData(rows, sequence_length);
            sequenceData.print();
            break;
        }
    }
    return Matrix(0, 0); // Return an empty matrix for unsupported types
}

int main() {
    size_t rows = 3, cols = 4;
    createRandomInputMatrix(rows, cols, DENSE).print();
    createRandomInputMatrix(rows, cols, SPARSE, 0.3);
    createRandomInputMatrix(2, 5, SEQUENCE, 0.1, 5);
    return 0;
}
