#include <stdio.h>
#include <stdlib.h>

int parse_binary_file(const char *filename, int **block_indices) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    int num_blocks;
    // Assuming the first 4 bytes of the file contain the number of blocks
    if (fread(&num_blocks, sizeof(int), 1, file) != 1) {
        perror("Failed to read number of blocks");
        fclose(file);
        return -1;
    }

    *block_indices = (int *)malloc(num_blocks * sizeof(int));
    if (*block_indices == NULL) {
        fclose(file);
        return -2; // Memory allocation error
    }

    // Assuming the next num_blocks * sizeof(int) bytes contain the block indices
    if (fread(*block_indices, sizeof(int), num_blocks, file) != num_blocks) {
        perror("Failed to read block indices");
        free(*block_indices);
        fclose(file);
        return -1;
    }

    fclose(file);
    return num_blocks; // Success
}
