#include <vector>
#include <iostream>
#include <cmath>

using uchar = unsigned char;

std::vector<std::vector<uchar>> gaussian_filter(const std::vector<std::vector<uchar>>& image, 
                                                int width, int height, 
                                                const std::vector<std::vector<double>>& kernel, 
                                                int kernel_width, int kernel_height) {
    std::vector<std::vector<uchar>> filtered_image(height, std::vector<uchar>(width, 0));
    int kx = kernel_width / 2;
    int ky = kernel_height / 2;

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            double sum = 0.0;
            double weight = 0.0;

            for (int j = -ky; j <= ky; ++j) {
                for (int i = -kx; i <= kx; ++i) {
                    int pixel_x = x + i;
                    int pixel_y = y + j;

                    if (pixel_x >= 0 && pixel_x < width && pixel_y >= 0 && pixel_y < height) {
                        sum += image[pixel_y][pixel_x] * kernel[j + ky][i + kx];
                        weight += kernel[j + ky][i + kx];
                    }
                }
            }

            filtered_image[y][x] = static_cast<uchar>(std::round(sum / weight));
        }
    }

    return filtered_image;
}

int main() {
    // Example usage
    std::vector<std::vector<uchar>> image = {
        {255, 255, 255, 255},
        {255, 0, 0, 255},
        {255, 0, 0, 255},
        {255, 255, 255, 255}
    };

    std::vector<std::vector<double>> kernel = {
        {1.0, 2.0, 1.0},
        {2.0, 4.0, 2.0},
        {1.0, 2.0, 1.0}
    };

    int width = 4;
    int height = 4;
    int kernel_width = 3;
    int kernel_height = 3;

    auto filtered_image = gaussian_filter(image, width, height, kernel, kernel_width, kernel_height);

    for (const auto& row : filtered_image) {
        for (const auto& pixel : row) {
            std::cout << static_cast<int>(pixel) << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
