#include <librealsense2/rs.hpp>
#include <ros/ros.h>
#include <sensor_msgs/PointCloud2.h>
#include <sensor_msgs/Image.h>
#include <cv_bridge/cv_bridge.h>
#include <image_transport/image_transport.h>

class RealSenseCamera {
public:
    RealSenseCamera(ros::NodeHandle& nh) : it_(nh) {
        // Initialize RealSense pipeline
        pipeline_.start();

        // Advertise ROS topics
        point_cloud_pub_ = nh.advertise<sensor_msgs::PointCloud2>("point_cloud", 1);
        image_pub_ = it_.advertise("camera/image", 1);
    }

    void capture() {
        rs::frameset frames = pipeline_.wait_for_frames();
        rs::frame depth = frames.get_depth_frame();
        rs::frame color = frames.get_color_frame();

        if (depth && color) {
            // Create PointCloud2 message
            sensor_msgs::PointCloud2 point_cloud_msg;
            // Fill point_cloud_msg with depth data...

            // Create Image message
            sensor_msgs::ImagePtr image_msg = cv_bridge::CvImage(std_msgs::Header(), "bgr8", cv::Mat(color.get_height(), color.get_width(), CV_8UC3, (void*)color.get_data(), color.get_stride())).toImageMsg();

            // Publish messages
            point_cloud_pub_.publish(point_cloud_msg);
            image_pub_.publish(image_msg);
        }
    }

private:
    rs::pipeline pipeline_;
    image_transport::ImageTransport it_;
    image_transport::Publisher image_pub_;
    ros::Publisher point_cloud_pub_;
};

int main(int argc, char** argv) {
    ros::init(argc, argv, "realsense_camera");
    ros::NodeHandle nh;
    RealSenseCamera camera(nh);

    ros::Rate loop_rate(30);
    while (ros::ok()) {
        camera.capture();
        ros::spinOnce();
        loop_rate.sleep();
    }

    return 0;
}
