void additiveBlitWithAA(int width, int height, int x, int y, const unsigned char* alphaValues, const unsigned char* srcImage, unsigned char* dstImage) {
    for (int j = 0; j < height; ++j) {
        for (int i = 0; i < width; ++i) {
            int dstIndex = (y + j) * width + (x + i);
            int srcIndex = j * width + i;

            if (x + i >= 0 && x + i < width && y + j >= 0 && y + j < height) {
                unsigned char srcPixel = srcImage[srcIndex];
                unsigned char alpha = alphaValues[srcIndex];

                // Perform additive blending
                unsigned char dstPixel = dstImage[dstIndex];
                unsigned char blendedPixel = std::min(255, dstPixel + (srcPixel * alpha) / 255);
                dstImage[dstIndex] = blendedPixel;
            }
        }
    }
