static void update_max_value(const char *filename, int *max_value) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return; // File not present or error opening
    }

    char buffer[BUFFER_SIZE];
    size_t total_length = 0;
    size_t read_length;

    // Read and concatenate the contents of the file
    while ((read_length = fread(buffer, 1, sizeof(buffer) - 1, file)) > 0) {
        buffer[read_length] = '\0'; // Null-terminate the buffer
        total_length += read_length;
    }

    fclose(file);

    // Update the maximum value based on the number of pieces
    if (total_length > 0) {
        int pieces = total_length; // Assuming each character represents a piece
        if (pieces > *max_value) {
            *max_value = pieces;
        }
    }
