class ConnectionManager {
public:
    void addNode(const AddedNodeInfo& node) {
        nodes[node.ipAddress] = node;
    }

    bool hasNode(const std::string& ipAddress) const {
        return nodes.find(ipAddress) != nodes.end();
    }

    AddedNodeInfo getNode(const std::string& ipAddress) const {
        auto it = nodes.find(ipAddress);
        if (it != nodes.end()) {
            return it->second;
        }
        throw std::runtime_error("Node not found");
    }

private:
    std::unordered_map<std::string, AddedNodeInfo> nodes;
};

std::vector<AddedNodeInfo> retrieveNodeInfo(ConnectionManager& manager, const std::string& nodeIdentifier) {
    if (!manager.hasNode(nodeIdentifier)) {
        throw std::runtime_error("Node not found");
    }

    AddedNodeInfo nodeInfo = manager.getNode(nodeIdentifier);
    return {nodeInfo}; // Return as a vector
}
