static bool canAllocateMemory(const std::vector<MemoryBlock>& existingBlocks, uint64_t blockStart, size_t pageSize) {
    uint64_t blockEnd = blockStart + pageSize;

    for (const auto& block : existingBlocks) {
        // Check for overlap
        if (block.start < blockEnd && blockEnd > block.start) {
            return false; // Overlap detected
