#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>

typedef void (*callback_t)(const char *message);

void format_and_call(callback_t cb, const char *format, ...) {
    va_list ap;
    va_start(ap, format);

    // Initial buffer size
    size_t buffer_size = 256;
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        return; // Handle memory allocation failure
    }

    // Try to format the message
    int len = vsnprintf(buffer, buffer_size, format, ap);

    // Check if the buffer was large enough
    if (len < 0) {
        free(buffer);
        return; // Formatting error
    } else if (len >= buffer_size) {
        // Buffer was too small, allocate a larger one
        buffer_size = len + 1; // +1 for the null terminator
        char *new_buffer = realloc(buffer, buffer_size);
        if (new_buffer == NULL) {
            free(buffer);
            return; // Handle memory allocation failure
        }
        buffer = new_buffer;

        // Format the message again with the new buffer size
        vsnprintf(buffer, buffer_size, format, ap);
    }

    // Call the callback function with the formatted message
    cb(buffer);

    // Clean up
    free(buffer);
    va_end(ap);
}
