public class XmlParser
{
    public static Dictionary<string, string> ParseXml(string xmlString, HashSet<string> parametersToExtract)
    {
        var extractedValues = new Dictionary<string, string>();

        XmlReaderSettings settings = new XmlReaderSettings
        {
            IgnoreWhitespace = true,
            IgnoreComments = true
        };

        using (XmlReader reader = XmlReader.Create(new System.IO.StringReader(xmlString), settings))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && parametersToExtract.Contains(reader.Name))
                {
                    string parameterName = reader.Name;
                    if (reader.Read() && reader.NodeType == XmlNodeType.Text)
                    {
                        string parameterValue = reader.Value;
                        extractedValues[parameterName] = parameterValue;
                    }
                }
            }
        }

        return extractedValues;
    }
}
