    {
        Random random = new Random();
        int numberOfElements = random.Next(1, 101); // Random number of elements between 1 and 100
        List<int> originalList = new List<int>();

        for (int i = 0; i < numberOfElements; i++)
        {
            originalList.Add(random.Next(min, max));
        }

        List<int> shuffledList = originalList.OrderBy(x => random.Next()).ToList();
        List<int> sortedList = shuffledList.OrderBy(CustomSort).ToList();

        bool isEqual = sortedList.SequenceEqual(originalList.OrderBy(CustomSort));
        Console.WriteLine($"Original List: {string.Join(", ", originalList)}");
        Console.WriteLine($"Shuffled List: {string.Join(", ", shuffledList)}");
        Console.WriteLine($"Sorted List: {string.Join(", ", sortedList)}");
        Console.WriteLine($"Is Sorted List equal to Original List? {isEqual}");
    }

    private static int CustomSort(int x, int y)
    {
        return x.CompareTo(y);
    }
