using System;

public class DisplacementFieldGenerator
{
    private static Random random = new Random();

    public double[,] GenerateRandomDisplacementField(int width, int height, double stepSize)
    {
        double[,] displacementField = new double[height, width];

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                double displacementX = GenerateGaussianRandom(stepSize);
                double displacementY = GenerateGaussianRandom(stepSize);
                displacementField[y, x] = Math.Sqrt(displacementX * displacementX + displacementY * displacementY);
            }
        }

        return displacementField;
    }

    private double GenerateGaussianRandom(double stepSize)
    {
        double u1 = random.NextDouble();
        double u2 = random.NextDouble();
        double z0 = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Cos(2.0 * Math.PI * u2);
        return z0 * stepSize;
    }
}
