from django.views import View
from django.shortcuts import get_object_or_404
from django.db import transaction
from .models import YourEntityModel  # Replace with your actual model
from .forms import YourEntityForm  # Replace with your actual form

class UpdateEntityView(View):
    def post(self, request, entity_id):
        form = YourEntityForm(request.POST)
        if form.is_valid():
            with transaction.atomic():
                try:
                    obj = get_object_or_404(YourEntityModel, pk=entity_id)
                    for attr, value in form.cleaned_data.items():
                        setattr(obj, attr, value)
                    obj.save()
                    return JsonResponse({'success': True, 'data': obj}, status=200)
                except Exception as e:
                    return JsonResponse({'success': False, 'error': str(e)}, status=400)
        else:
            return JsonResponse({'success': False, 'errors': form.errors}, status=400)
