    public static string DecryptTripleDES(string base64EncodedEncryptedMessage, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(base64EncodedEncryptedMessage))
            return null;

        byte[] encryptedMessage = Convert.FromBase64String(base64EncodedEncryptedMessage);

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
