using UnityEngine;

public class IntersectionRotator : MonoBehaviour
{
    public enum IntersectionType
    {
        ThreeWay,
        Turn
    }

    public void RotateTransform(Transform transform, IntersectionType intersectionType)
    {
        int rotationAngle;

        switch (intersectionType)
        {
            case IntersectionType.ThreeWay:
                rotationAngle = Random.Range(0, 2) == 0 ? 90 : -90;
                break;
            case IntersectionType.Turn:
                rotationAngle = -90;
                break;
            default:
                return;
        }

        transform.Rotate(0, rotationAngle, 0);
    }
}
