using Cassandra;
using System.Collections.Generic;

public class CassandraHelper
{
    public void ExecuteBatchInsert(ISession session, string tableName, Dictionary<string, byte[]> outgoingPayload)
    {
        var batch = new BatchStatement();
        var insertStatement = new SimpleStatement($"INSERT INTO {tableName} (key, value) VALUES (?, ?)");

        foreach (var kvp in outgoingPayload)
        {
            var statement = insertStatement.Bind(kvp.Key, kvp.Value);
            batch.Add(statement);
        }

        var incomingPayload = session.Execute(batch).GetPayload();

        // Assertions
        if (incomingPayload == null || incomingPayload.Count != outgoingPayload.Count)
        {
            throw new System.Exception("Incoming payload is null or does not match outgoing payload count.");
        }

        foreach (var kvp in outgoingPayload)
        {
            if (!incomingPayload.ContainsKey(kvp.Key) || !incomingPayload[kvp.Key].SequenceEqual(kvp.Value))
            {
                throw new System.Exception("Outgoing payload contents do not match incoming payload contents.");
            }
        }
    }
}
