public class EntityService
{
    private readonly string _connectionString;

    public EntityService(string connectionString)
    {
        _connectionString = connectionString;
    }

    public DatabaseEntity CreateEntity(DatabaseEntity entity)
    {
        ValidateEntity(entity);

        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            using (var command = new SqlCommand("INSERT INTO Entities (Name, Email, Password) OUTPUT INSERTED.Id VALUES (@Name, @Email, @Password)", connection))
            {
                command.Parameters.AddWithValue("@Name", entity.Name);
                command.Parameters.AddWithValue("@Email", entity.Email);
                command.Parameters.AddWithValue("@Password", entity.Password);

                entity.Id = (int)command.ExecuteScalar();
            }
        }

        return entity;
    }

    private void ValidateEntity(DatabaseEntity entity)
    {
        if (string.IsNullOrWhiteSpace(entity.Name) || entity.Name.Length < 2 || entity.Name.Length > 100)
        {
            throw new ArgumentException("Name must be between 2 and 100 characters.");
        }

        if (string.IsNullOrWhiteSpace(entity.Email) || !entity.Email.Contains("@"))
        {
            throw new ArgumentException("Email must be a valid email address.");
        }

        if (string.IsNullOrWhiteSpace(entity.Password) || entity.Password.Length < 4)
        {
            throw new ArgumentException("Password must be at least 4 characters long.");
        }
    }
}
