using UnityEngine;

public class RotationHandler : MonoBehaviour
{
    public void RotateTransform(Transform targetTransform, IntersectionType intersectionType, Transform otherTransform)
    {
        float rotationAngle = 90f;

        switch (intersectionType)
        {
            case IntersectionType.TypeA:
                targetTransform.Rotate(0, rotationAngle, 0);
                break;
            case IntersectionType.TypeB:
                targetTransform.Rotate(0, -rotationAngle, 0);
                break;
            case IntersectionType.TypeC:
                Vector3 direction = (otherTransform.position - targetTransform.position).normalized;
                if (Vector3.Dot(direction, Vector3.forward) > 0)
                {
                    targetTransform.Rotate(0, rotationAngle, 0);
                }
                else
                {
                    targetTransform.Rotate(0, -rotationAngle, 0);
                }
                break;
            default:
                break;
        }
    }
}

public enum IntersectionType
{
    TypeA,
    TypeB,
    TypeC
}
