using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Decryptor
{
    public static string DecryptDES(string encryptedMessage, string key)
    {
        byte[] iv = new byte[8]; // DES uses a block size of 8 bytes
        byte[] buffer = Convert.FromBase64String(encryptedMessage);

        using (var des = DES.Create())
        {
            des.Key = Encoding.UTF8.GetBytes(key);
            des.IV = iv;

            using (var decryptor = des.CreateDecryptor(des.Key, des.IV))
            using (var memoryStream = new MemoryStream(buffer))
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            using (var reader = new StreamReader(cryptoStream))
            {
                return reader.ReadToEnd();
            }
        }
    }
}
