using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using System.Collections.Generic;

public class CacheController : ControllerBase
{
    private readonly IMemoryCache _cache;

    public CacheController(IMemoryCache cache)
    {
        _cache = cache;
    }

    [HttpPost]
    [HttpPut]
    [HttpDelete]
    public ActionResult ProcessRequest(string cacheKey, [FromBody] Dictionary<string, string> data)
    {
        if (string.IsNullOrEmpty(cacheKey))
        {
            return BadRequest("Cache key is required.");
        }

        switch (Request.Method)
        {
            case "POST":
                _cache.Set(cacheKey, data);
                return CreatedAtAction(nameof(ProcessRequest), new { cacheKey }, data);

            case "PUT":
                if (_cache.TryGetValue(cacheKey, out _))
                {
                    _cache.Set(cacheKey, data);
                    return Ok(data);
                }
                return NotFound("Cache entry not found.");

            case "DELETE":
                if (_cache.TryGetValue(cacheKey, out _))
                {
                    _cache.Remove(cacheKey);
                    return NoContent();
                }
                return NotFound("Cache entry not found.");

            default:
                return BadRequest("Unsupported request method.");
        }
    }
}
