using System;
using System.Text;
using System.Threading;

public class Publisher
{
    private const string Topic = "example_topic";
    private const int MaxMessageSize = 1024 * 1024; // 1 MB
    private const int MessageCount = 10;

    public void PublishMessages()
    {
        var context = new ZMQ.Context();
        var publisher = context.Socket(ZMQ.SocketType.PUB);
        publisher.Bind("tcp://*:5555");

        // Allow time for the connection to establish
        Thread.Sleep(200);

        for (int i = 0; i < MessageCount; i++)
        {
            try
            {
                // Generate an oversized message
                var oversizedMessage = GenerateOversizedMessage();
                publisher.SendMore(Topic);
                publisher.Send(oversizedMessage);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Exception caught while publishing: {ex.Message}");
                break;
            }
        }

        publisher.Close();
        context.Term();
    }

    private byte[] GenerateOversizedMessage()
    {
        // Create a random oversized message
        var random = new Random();
        var oversizedMessage = new byte[MaxMessageSize];
        random.NextBytes(oversizedMessage);
        return oversizedMessage;
    }
}
