CancellationTokenSource watchdogCts = new CancellationTokenSource();
Task.Run(async () =>
{
var debugOutputPeriod1 = debugOutputPeriod ?? TimeSpan.FromSeconds(1);
int prevSentCount = -1;
int prevRecvCount = -1;
int noProgressCount = 0;
