using System;
using System.Xml.Linq;
using System.Xml.XPath;

public class XmlConfigUpdater
{
    public void AddSearcher(string configFilePath, string searcherName, string searcherType)
    {
        XDocument xDocument = XDocument.Load(configFilePath);

        // Define the XPath to select the existing searchers
        var searchers = xDocument.XPathSelectElements("//searchers").FirstOrDefault();

        if (searchers != null)
        {
            // Create a new searcher element
            XElement newSearcher = new XElement("searcher",
                new XAttribute("name", searcherName),
                new XAttribute("type", searcherType)
            );

            // Add the new searcher to the existing list of searchers
            searchers.Add(newSearcher);
        }

        // Save the updated XML document
        xDocument.Save(configFilePath);
    }
}
