    public async Task<IActionResult> Register(string email, string fullName, string password, string returnUrl = null)
    {
        if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(password))
        {
            ModelState.AddModelError(string.Empty, "Email and password are required.");
            return View("Register", new RegisterViewModel { Email = email, FullName = fullName });
        }

        var result = await _accountService.RegisterUserAsync(email, fullName, password);

        if (result.IsSuccess)
        {
            // Registration successful, redirect to home page or specified return URL
            return Redirect(returnUrl ?? Url.Action("Index", "Home"));
        }

        // Registration failed, handle errors
        foreach (var error in result.Errors)
        {
            ModelState.AddModelError(string.Empty, error);
        }

        return View("Register", new RegisterViewModel { Email = email, FullName = fullName });
    }
}

