        {
            return project.StartupFile;
        }

        int port = GenerateAvailablePort();
        return $"{project.StartupFile}?port={port}";
    }

    private int GenerateAvailablePort()
    {
        Random random = new Random();
        int port;

        do
        {
            port = random.Next(1200, 60001);
        } while (IsPortInUse(port));

        return port;
    }

    private bool IsPortInUse(int port)
    {
        var tcpConnections = IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpConnections();
        return tcpConnections.Any(conn => conn.LocalEndPoint.Port == port);
    }
}
