		}
		if (off < last_off) {
			THROW(ReportedBoundsError);
		}
		last_off = off;
	} /* End WHILE */
	DebugLog(("ATTR: level = %u, Return: len = %u (end of function body)\n",
		  level, off - offset));
	return (off - offset);
}
