public class DatabaseHelper
{
    public static int ExecuteSqlQuery(SqlConnection connection, string sqlQuery, out DataTable resultTable)
    {
        int rowsAffected = 0;
        resultTable = null;

        using (SqlCommand command = new SqlCommand(sqlQuery, connection))
        {
            try
            {
                connection.Open();
                rowsAffected = command.ExecuteNonQuery();

                // If the query is a SELECT statement, retrieve the results into a DataTable
                if (sqlQuery.TrimStart().StartsWith("SELECT", StringComparison.OrdinalIgnoreCase))
                {
                    using (SqlDataAdapter adapter = new SqlDataAdapter(command))
                    {
                        resultTable = new DataTable();
                        adapter.Fill(resultTable);
                    }
                }
            }
            catch (SqlException ex)
            {
                Console.WriteLine($"SQL Error: {ex.Message}");
                rowsAffected = -1; // Indicate an error occurred
            }
            finally
            {
                connection.Close();
            }
        }

        return rowsAffected;
    }
}
