using Cassandra;
using Cassandra.Data.Linq;
using System;

public class CassandraTestCluster
{
    private Cluster cluster;
    private ISession session;

    public void SetUp()
    {
        // Set up the Cassandra cluster
        cluster = Cluster.Builder()
            .AddContactPoint("127.0.0.1")
            .Build();
        session = cluster.Connect();

        // Create keyspace
        session.Execute("CREATE KEYSPACE IF NOT EXISTS test_keyspace WITH REPLICATION = " +
                        "{ 'class' : 'SimpleStrategy', 'replication_factor' : 1 };");

        // Create table
        session.Execute("CREATE TABLE IF NOT EXISTS test_keyspace.test_table (" +
                        "id UUID PRIMARY KEY, " +
                        "name text, " +
                        "value int);");
    }

    public void ExecuteQuery(Guid id, string name, int value)
    {
        // Insert data into the table
        var insertStatement = session.Prepare("INSERT INTO test_keyspace.test_table (id, name, value) VALUES (?, ?, ?);");
        var boundStatement = insertStatement.Bind(id, name, value);
        session.Execute(boundStatement);
    }

    public void TearDown()
    {
        // Clean up
        session.Execute("DROP TABLE IF EXISTS test_keyspace.test_table;");
        session.Execute("DROP KEYSPACE IF EXISTS test_keyspace;");
        session.Dispose();
        cluster.Dispose();
    }
}
