using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class ModelController : Controller
{
    private readonly IDataService _dataService;

    public ModelController(IDataService dataService)
    {
        _dataService = dataService;
    }

    [HttpGet("{id}")]
    public async Task<IActionResult> GetModel(int id)
    {
        var model = await LoadModelAsync(id);
        if (model == null)
        {
            return NotFound();
        }
        return View(model);
    }

    [HttpPost]
    public async Task<IActionResult> CreateModel([FromBody] Model model)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        await _dataService.AddModelAsync(model);
        return Json(model);
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateModel(int id, [FromBody] Model model)
    {
        if (id != model.Id || !ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var existingModel = await LoadModelAsync(id);
        if (existingModel == null)
        {
            return NotFound();
        }

        await _dataService.UpdateModelAsync(model);
        return Json(model);
    }

    private async Task<Model> LoadModelAsync(int id)
    {
        return await _dataService.GetModelByIdAsync(id);
    }
}

public interface IDataService
{
    Task<Model> GetModelByIdAsync(int id);
    Task AddModelAsync(Model model);
    Task UpdateModelAsync(Model model);
}

