using System;
using System.Xml.Linq;
using System.Xml.XPath;

public class XmlConfigUpdater
{
    public void AddSectionAfter(string filePath, string existingSection, XElement newSection)
    {
        XDocument xmlDoc = XDocument.Load(filePath);
        var existingElements = xmlDoc.XPathSelectElements($"//{existingSection}");

        if (existingElements != null)
        {
            foreach (var element in existingElements)
            {
                element.AddAfterSelf(newSection);
            }
            xmlDoc.Save(filePath);
        }
        else
        {
            throw new Exception($"Section '{existingSection}' not found in the XML.");
        }
    }
}
