using System;
using System.Data;
using System.Data.SqlClient;

public class DatabaseConnectionWrapper
{
    private SqlConnection _connection;

    public DatabaseConnectionWrapper(string connectionString)
    {
        _connection = new SqlConnection(connectionString);
    }

    public void Open()
    {
        if (_connection.State != ConnectionState.Open)
        {
            _connection.Open();
        }
    }

    public void Close()
    {
        if (_connection.State != ConnectionState.Closed)
        {
            _connection.Close();
        }
    }

    public byte[] ExecuteNonQuery(string uniqueId, byte[] sqlCommand, IsolationLevel isolationLevel)
    {
        using (var transaction = _connection.BeginTransaction(isolationLevel))
        {
            try
            {
                using (var command = new SqlCommand(System.Text.Encoding.UTF8.GetString(sqlCommand), _connection, transaction))
                {
                    command.ExecuteNonQuery();
                }
                transaction.Commit();
                return null; // Return null for non-query commands
            }
            catch
            {
                transaction.Rollback();
                throw;
            }
        }
    }

    public object ExecuteScalar(string uniqueId, byte[] sqlCommand, IsolationLevel isolationLevel)
    {
        using (var transaction = _connection.BeginTransaction(isolationLevel))
        {
            try
            {
                using (var command = new SqlCommand(System.Text.Encoding.UTF8.GetString(sqlCommand), _connection, transaction))
                {
                    var result = command.ExecuteScalar();
                    transaction.Commit();
                    return result; // Return the scalar result
                }
            }
            catch
            {
                transaction.Rollback();
                throw;
            }
        }
    }

    public byte[] DeriveParameters(string uniqueId, byte[] sqlCommand)
    {
        using (var command = new SqlCommand(System.Text.Encoding.UTF8.GetString(sqlCommand), _connection))
        {
            SqlCommandBuilder.DeriveParameters(command);
            // Convert parameter names to byte array
            var parameters = new byte[command.Parameters.Count][];
            for (int i = 0; i < command.Parameters.Count; i++)
            {
                parameters[i] = System.Text.Encoding.UTF8.GetBytes(command.Parameters[i].ParameterName);
            }
            return parameters; // Return parameter names as byte array
        }
    }
}
