[ApiController]
[Route("api/[controller]")]
public class PageController : ControllerBase
{
    private readonly IPageService _pageService;

    public PageController(IPageService pageService)
    {
        _pageService = pageService;
    }

    [HttpPost("add-element")]
    public async Task<IActionResult> AddElementAsync([FromBody] AddElementRequest request)
    {
        if (request == null || string.IsNullOrEmpty(request.PageSectionId) || string.IsNullOrEmpty(request.ContainerElementId))
        {
            return BadRequest(new { success = false, message = "Invalid input." });
        }

        request.ElementBody = request.ElementBody?.Replace("animated bounce", string.Empty);

        await _pageService.AddElementToPageAsync(request.PageSectionId, request.ContainerElementId, request.ElementBody);

        return Ok(new { success = true });
    }
}

public class AddElementRequest
{
    public string PageSectionId { get; set; }
    public string ContainerElementId { get; set; }
    public string ElementBody { get; set; }
}
