public static class XmlGenerator
{
    public static XDocument GenerateXmlFromType(Type type)
    {
        var xmlElement = new XElement(type.Name);

        var xmlizedClassAttribute = type.GetCustomAttribute<XmlizedClassAttribute>();
        if (xmlizedClassAttribute != null)
