using System.Xml.Linq;

public class TravelItem
{
    public string Coordinates { get; set; }
    public DateTime DateLogged { get; set; }
}

public class GeocacheParser
{
    public List<TravelItem> ExtractGeocacheData()
    {
        List<TravelItem> travelItems = new List<TravelItem>();
        try
        {
            var assembly = Assembly.GetExecutingAssembly();
            var resourceName = "YourNamespace.Resources.geocaches.html"; // Update with your actual resource path

            using (Stream stream = assembly.GetManifestResourceStream(resourceName))
            {
                if (stream == null)
                {
                    throw new FileNotFoundException("Resource not found.");
                }

                using (StreamReader reader = new StreamReader(stream))
                {
                    string htmlContent = reader.ReadToEnd();
                    ParseHtml(htmlContent, travelItems);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading HTML resource: {ex.Message}");
        }

        return travelItems;
    }

    private void ParseHtml(string htmlContent, List<TravelItem> travelItems)
    {
        var regex = new Regex(@"<div class=""geocache"">.*?<span class=""coordinates"">(?<coords>.*?)</span>.*?<span class=""date-logged"">(?<date>.*?)</span>", RegexOptions.Singleline);
        var matches = regex.Matches(htmlContent);

        foreach (Match match in matches)
        {
            var coordinates = match.Groups["coords"].Value;
            var dateLogged = DateTime.Parse(match.Groups["date"].Value);

            travelItems.Add(new TravelItem
            {
                Coordinates = coordinates,
                DateLogged = dateLogged
            });
        }
    }
}
