public class VersionRetriever
{
    private readonly string _connectionString;

    public VersionRetriever(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<int> GetNextVersionAsync(int streamId, int currentVersion)
    {
        const string query = "SELECT MIN(version) FROM Versions WHERE streamId = @streamId AND version > @currentVersion";

        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            using (SqlCommand command = new SqlCommand(query, connection))
            {
                command.Parameters.AddWithValue("@streamId", streamId);
                command.Parameters.AddWithValue("@currentVersion", currentVersion);

                var result = await command.ExecuteScalarAsync();
                if (result != DBNull.Value)
                {
                    return Convert.ToInt32(result);
                }
            }
        }

        return -1;
    }
}
