using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static XmlElement GetFirstElement(string xml, string elementName)
    {
        XmlDocument doc = new XmlDocument();
        doc.LoadXml(xml);
        XPathNavigator navigator = doc.CreateNavigator();
        XPathNodeIterator iterator = navigator.Select($"//{elementName}");

        if (iterator.Count == 0)
        {
            throw new Exception($"No element found with name: {elementName}");
        }
        else if (iterator.Count > 1)
        {
            throw new Exception($"Multiple elements found with name: {elementName}");
        }

        iterator.MoveNext();
        return (XmlElement)iterator.Current.UnderlyingObject;
    }
}
