CREATE FUNCTION GetLastInsertedID(@TableName NVARCHAR(128))
RETURNS INT
AS
BEGIN
    DECLARE @LastID INT;

    DECLARE @SQL NVARCHAR(MAX);
    SET @SQL = N'SELECT @LastID = SCOPE_IDENTITY() FROM ' + QUOTENAME(@TableName);

    EXEC sp_executesql @SQL, N'@LastID INT OUTPUT', @LastID OUTPUT;

    RETURN @LastID;
END;
