using System;
using System.Collections.Generic;
using System.Xml.Linq;

public class ConfigLoader
{
    public static Dictionary<string, string> LoadSettings(string filePath)
    {
        var settings = new Dictionary<string, string>();

        try
        {
            XDocument xmlDoc = XDocument.Load(filePath);
            XElement configuration = xmlDoc.Element("configuration");

            if (configuration != null)
            {
                foreach (XElement setting in configuration.Elements())
                {
                    string key = setting.Name.LocalName;
                    string value = setting.Value;
                    settings[key] = value;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
        }

        return settings;
    }
}
