using System;
using System.Data.SqlClient;

public class Trackable
{
    public int Id { get; set; }
    public int HopCount { get; set; }
    public int InCacheCount { get; set; }
    public int DiscoverCount { get; set; }
}

public class DatabaseUpdater
{
    private readonly SqlConnection _connection;

    public DatabaseUpdater(SqlConnection connection)
    {
        _connection = connection;
    }

    public void UpdateTrackable(Trackable t)
    {
        try
        {
            _connection.Open();
            using (var transaction = _connection.BeginTransaction())
            {
                // Delete existing logs for the trackable item
                var deleteCommand = new SqlCommand("DELETE FROM TrackableLogs WHERE TrackableId = @TrackableId", _connection, transaction);
                deleteCommand.Parameters.AddWithValue("@TrackableId", t.Id);
                deleteCommand.ExecuteNonQuery();

                // Update the trackables table
                var updateCommand = new SqlCommand("UPDATE Trackables SET HopCount = @HopCount, InCacheCount = @InCacheCount, DiscoverCount = @DiscoverCount WHERE Id = @Id", _connection, transaction);
                updateCommand.Parameters.AddWithValue("@HopCount", t.HopCount);
                updateCommand.Parameters.AddWithValue("@InCacheCount", t.InCacheCount);
                updateCommand.Parameters.AddWithValue("@DiscoverCount", t.DiscoverCount);
                updateCommand.Parameters.AddWithValue("@Id", t.Id);
                updateCommand.ExecuteNonQuery();

                transaction.Commit();
            }
        }
        catch (Exception ex)
        {
            // Handle exception (logging, rethrowing, etc.)
            throw new Exception("Error updating trackable", ex);
        }
        finally
        {
            _connection.Close();
        }
    }
}
