public class EncryptionHelper
{
    public static string EncryptString(string plainText, string key)
    {
        using (DESCryptoServiceProvider des = new DESCryptoServiceProvider())
        {
            byte[] keyBytes = Encoding.UTF8.GetBytes(key);
