using System;
using System.Diagnostics;
using System.IO;

public class FileCopier
{
    public void CopyFiles(string sourceDir, string targetDir, string[] includeExtensions, string[] excludeExtensions)
    {
        if (!Directory.Exists(sourceDir))
        {
            throw new DirectoryNotFoundException($"Source directory does not exist: {sourceDir}");
        }

        if (!Directory.Exists(targetDir))
        {
            Directory.CreateDirectory(targetDir);
        }

        var files = Directory.GetFiles(sourceDir, "*.*", SearchOption.AllDirectories);

        foreach (var file in files)
        {
            string extension = Path.GetExtension(file);
            if (ShouldCopyFile(extension, includeExtensions, excludeExtensions))
            {
                string targetFilePath = Path.Combine(targetDir, Path.GetFileName(file));
                Process.Start(new ProcessStartInfo
                {
                    FileName = "cmd.exe",
                    Arguments = $"/c copy \"{file}\" \"{targetFilePath}\"",
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                }).WaitForExit();
            }
        }
    }

    private bool ShouldCopyFile(string extension, string[] includeExtensions, string[] excludeExtensions)
    {
        if (excludeExtensions != null && Array.Exists(excludeExtensions, e => e.Equals(extension, StringComparison.OrdinalIgnoreCase)))
        {
            return false;
        }

        if (includeExtensions != null && Array.Exists(includeExtensions, e => e.Equals(extension, StringComparison.OrdinalIgnoreCase)))
        {
            return true;
        }

        return includeExtensions == null || includeExtensions.Length == 0;
    }
}
