using System;
using System.Diagnostics;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    private static readonly HttpClient httpClient = new HttpClient();
    private const int MaxRetries = 3;
    private const int DelayBetweenRetries = 2000; // in milliseconds

    static async Task Main(string[] args)
    {
        string executablePath = "path_to_your_executable.exe"; // Specify the path to your executable
        StartProcess(executablePath);

        string serviceUrl = "http://your-remote-service/api/method"; // Specify your remote service URL
        await CallRemoteServiceWithRetry(serviceUrl);
    }

    static void StartProcess(string executablePath)
    {
        try
        {
            Process process = new Process();
            process.StartInfo.FileName = executablePath;
            process.Start();
            process.WaitForExit();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while starting the process: {ex.Message}");
        }
    }

    static async Task CallRemoteServiceWithRetry(string url)
    {
        for (int attempt = 1; attempt <= MaxRetries; attempt++)
        {
            try
            {
                HttpResponseMessage response = await httpClient.GetAsync(url);
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();
                Console.WriteLine($"Response from service: {responseBody}");
                return; // Exit if the call was successful
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Attempt {attempt} failed: {ex.Message}");
                if (attempt == MaxRetries)
                {
                    Console.WriteLine("Max retries reached. Exiting.");
                    return;
                }
                await Task.Delay(DelayBetweenRetries);
            }
        }
    }
}
