public class ProjectOpener
{
    public void OpenProject(string projectFilePath)
    {
        if (string.IsNullOrEmpty(projectFilePath) || !File.Exists(projectFilePath))
        {
            throw new ArgumentException("Invalid project file path.");
        }

        string solutionPath = Path.ChangeExtension(projectFilePath, ".sln");
        if (!File.Exists(solutionPath))
        {
            solutionPath = projectFilePath; // If no solution file, use the project file
        }

        Process[] runningProcesses = Process.GetProcessesByName("devenv");
        foreach (var process in runningProcesses)
        {
            // Check if the solution or project is already open
            if (process.MainWindowTitle.Contains(Path.GetFileNameWithoutExtension(solutionPath)))
            {
                return; // Project or solution is already open
            }
        }

        // Launch Visual Studio with the project or solution
        Process.Start("devenv.exe", $"\"{solutionPath}\"");
    }
}
