using System;
using System.Data.SqlClient;

public class ForumService
{
    private string connectionString;

    public ForumService(string connectionString)
    {
        this.connectionString = connectionString;
    }

    public string CreatePost(int forumId, string postContent)
    {
        if (forumId <= 0)
        {
            return "Error: Forum does not exist.";
        }

        if (string.IsNullOrWhiteSpace(postContent))
        {
            return "Error: Post content cannot be empty.";
        }

        using (SqlConnection con = new SqlConnection(connectionString))
        {
            con.Open();
            string checkForumQuery = "SELECT COUNT(*) FROM Forums WHERE ForumId = @ForumId";
            using (SqlCommand checkForumCommand = new SqlCommand(checkForumQuery, con))
            {
                checkForumCommand.Parameters.AddWithValue("@ForumId", forumId);
                int forumExists = (int)checkForumCommand.ExecuteScalar();

                if (forumExists == 0)
                {
                    return "Error: Forum does not exist.";
                }
            }

            string insertPostQuery = "INSERT INTO Posts (ForumId, PostContent, PostTime) VALUES (@ForumId, @PostContent, CURRENT_TIMESTAMP)";
            using (SqlCommand insertPostCommand = new SqlCommand(insertPostQuery, con))
            {
                insertPostCommand.Parameters.AddWithValue("@ForumId", forumId);
                insertPostCommand.Parameters.AddWithValue("@PostContent", postContent);
                insertPostCommand.ExecuteNonQuery();
            }
        }

        return "Post created successfully.";
    }
}
