    static async Task Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Please provide a URL as a command line argument.");
            return;
        }

        string url = args[0];
        string content = await DownloadContentAsync(url);

        if (content != null)
        {
            OpenContentInNewProcess(content);
        }
        else
        {
            Console.WriteLine("Failed to download content from the URL.");
        }
    }

    static async Task<string> DownloadContentAsync(string url)
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                return await client.GetStringAsync(url);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error downloading content: {ex.Message}");
                return null;
            }
        }
    }

    static void OpenContentInNewProcess(string content)
    {
        string tempFilePath = System.IO.Path.GetTempFileName() + ".html";
        System.IO.File.WriteAllText(tempFilePath, content);

        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c start {tempFilePath}",
            UseShellExecute = true
        };

        try
        {
            Process.Start(startInfo);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error opening content: {ex.Message}");
        }
    }
}
