using System.Xml.XPath;

public class ConfigUpdater
{
    public int RemoveSectionFromConfig(string filePath, string sectionXPath)
    {
        XDocument config = XDocument.Load(filePath);
        var sectionsToRemove = config.XPathSelectElements(sectionXPath);
        int removedCount = sectionsToRemove.Count();

        foreach (var section in sectionsToRemove)
        {
            section.Remove();
        }

        config.Save(filePath);
        return removedCount;
    }
}
