class Program
{
    static void Main(string[] args)
    {
        if (args.Length != 1)
        {
            Console.WriteLine("Usage: OCRPdfExtractor <input.pdf>");
            return;
        }

        string inputPdfPath = args[0];
        string outputPdfPath = Path.ChangeExtension(inputPdfPath, ".extracted.pdf");

        try
        {
            ExtractTextFromPdf(inputPdfPath, outputPdfPath);
            OpenPdf(outputPdfPath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    static void ExtractTextFromPdf(string inputPdfPath, string outputPdfPath)
    {
        using (var pdfDocument = PdfReader.Open(inputPdfPath, PdfDocumentOpenMode.ReadOnly))
        {
            using (var outputDocument = new PdfDocument())
            {
                foreach (var page in pdfDocument.Pages)
                {
                    using (var bitmap = RenderPageToBitmap(page))
                    {
                        string extractedText = PerformOcr(bitmap);
                        AddTextToPdfPage(outputDocument, extractedText);
                    }
                }
                outputDocument.Save(outputPdfPath);
            }
        }
    }

    static Bitmap RenderPageToBitmap(PdfPage page)
    {
        var width = (int)page.Width;
        var height = (int)page.Height;
        var bitmap = new Bitmap(width, height);
        using (var graphics = Graphics.FromImage(bitmap))
        {
            graphics.Clear(Color.White);
            XGraphics xGraphics = XGraphics.FromGraphics(graphics, new XSize(width, height));
            XRect box = new XRect(0, 0, width, height);
            xGraphics.DrawImage(XImage.FromPdfPage(page), box);
        }
        return bitmap;
    }

    static string PerformOcr(Bitmap bitmap)
    {
        using (var engine = new TesseractEngine(@"./tessdata", "eng", EngineMode.Default))
        {
            using (var img = PixConverter.ToPix(bitmap))
            {
                var result = engine.Process(img);
                return result.GetText();
            }
        }
    }

    static void AddTextToPdfPage(PdfDocument outputDocument, string text)
    {
        var page = outputDocument.AddPage();
        var gfx = XGraphics.FromPdfPage(page);
        gfx.DrawString(text, new XFont("Verdana", 12, XFontStyle.Regular), XBrushes.Black, new XRect(0, 0, page.Width, page.Height), XStringFormats.TopLeft);
    }

    static void OpenPdf(string pdfPath)
    {
        Process.Start(new ProcessStartInfo
        {
            FileName = pdfPath,
            UseShellExecute = true
        });
    }
