using System;
using System.Xml;

public class XmlUpdater
{
    public string UpdateXmlFile(string filePath, string xpathToRemove, string xpathAfter)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.Load(filePath);

        XmlNode nodeToRemove = xmlDoc.SelectSingleNode(xpathToRemove);
        XmlNode referenceNode = xmlDoc.SelectSingleNode(xpathAfter);

        if (nodeToRemove != null)
        {
            // Remove the node
            nodeToRemove.ParentNode.RemoveChild(nodeToRemove);
        }

        if (referenceNode != null && nodeToRemove != null)
        {
            // Insert the removed node after the reference node
            referenceNode.ParentNode.InsertAfter(nodeToRemove, referenceNode);
        }

        return xmlDoc.OuterXml;
    }
}
