public interface IExportToXmlable
{
    XElement ExportToXml();
}

public static class XmlExporter
{
    public static XDocument ExportObjectToXml(object obj)
    {
        var xmlDocument = new XDocument(new XElement("Root"));

        var properties = obj.GetType().GetProperties()
            .Where(prop => Attribute.IsDefined(prop, typeof(XmlizedPropertyAttribute)));

        foreach (var property in properties)
        {
            var attribute = (XmlizedPropertyAttribute)Attribute.GetCustomAttribute(property, typeof(XmlizedPropertyAttribute));
            var path = attribute.Path;
            var value = property.GetValue(obj);

            XElement xmlNode;

            if (value is IExportToXmlable exportable)
            {
                xmlNode = exportable.ExportToXml();
            }
            else
            {
                xmlNode = new XElement(path, value);
            }

            xmlDocument.Root.Add(xmlNode);
        }

        return xmlDocument;
    }
}
