    public CookieManager(string cookieFilePath)
    {
        _cookieFilePath = cookieFilePath;
    }

    public void SaveCookies(CookieContainer cookieContainer)
    {
        using (FileStream fs = new FileStream(_cookieFilePath, FileMode.Create))
        using (BinaryWriter writer = new BinaryWriter(fs))
        {
            foreach (Cookie cookie in cookieContainer.GetCookies())
            {
                writer.Write(cookie.Name);
                writer.Write(cookie.Value);
                writer.Write(cookie.Domain);
                writer.Write(cookie.Path);
                writer.Write(cookie.Expires.ToBinary());
                writer.Write(cookie.HttpOnly);
                writer.Write(cookie.Secure);
            }
        }
    }

    public CookieContainer LoadCookies()
    {
        CookieContainer cookieContainer = new CookieContainer();

        if (File.Exists(_cookieFilePath))
        {
            using (FileStream fs = new FileStream(_cookieFilePath, FileMode.Open))
            using (BinaryReader reader = new BinaryReader(fs))
            {
                while (fs.Position < fs.Length)
                {
                    string name = reader.ReadString();
                    string value = reader.ReadString();
                    string domain = reader.ReadString();
                    string path = reader.ReadString();
                    DateTime expires = DateTime.FromBinary(reader.ReadInt64());
                    bool httpOnly = reader.ReadBoolean();
                    bool secure = reader.ReadBoolean();

                    Cookie cookie = new Cookie(name, value, path, domain)
                    {
                        Expires = expires,
                        HttpOnly = httpOnly,
                        Secure = secure
                    };
                    cookieContainer.Add(cookie);
                }
            }
        }

        return cookieContainer;
    }
}
