using System.Xml;

public class XmlConfigManager
{
    public void RemoveAndAddConfigNode(string xmlFilePath, string keyValue)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.Load(xmlFilePath);

        // Remove the existing configuration node with the specified key value
        XmlNode nodeToRemove = xmlDoc.SelectSingleNode($"//ConfigurationNode[@key='{keyValue}']");
        if (nodeToRemove != null)
        {
            nodeToRemove.ParentNode.RemoveChild(nodeToRemove);
        }

        // Create a new configuration node with the same key value
        XmlNode newNode = xmlDoc.CreateElement("ConfigurationNode");
        XmlAttribute keyAttribute = xmlDoc.CreateAttribute("key");
        keyAttribute.Value = keyValue;
        newNode.Attributes.Append(keyAttribute);

        // Append the new node to the root or a specific parent node
        xmlDoc.DocumentElement.AppendChild(newNode);

        // Save the changes back to the XML file
        xmlDoc.Save(xmlFilePath);
    }
}
