using System;
using System.Collections.Generic;
using System.Xml;

public class ConfigurationLoader
{
    public List<Setting> LoadSettingsFromXml(string xmlFilePath)
    {
        List<Setting> settingsList = new List<Setting>();

        try
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load(xmlFilePath);
            XmlNodeList settingNodes = xmlDoc.GetElementsByTagName("setting");

            foreach (XmlNode settingNode in settingNodes)
            {
                string name = settingNode.Attributes["name"]?.Value;
                string value = settingNode.Attributes["value"]?.Value;

                if (!string.IsNullOrEmpty(name) && !string.IsNullOrEmpty(value))
                {
                    settingsList.Add(new Setting { Name = name, Value = value });
                }
            }
        }
        catch (XmlException ex)
        {
            Console.WriteLine($"Error while parsing XML file: {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }

        return settingsList;
    }
}

public class Setting
{
    public string Name { get; set; }
    public string Value { get; set; }
}
