    public void PopulatePropertyFromXml(XmlDocument xmlDoc, PropertyInfo propertyInfo, XmlNode xmlNode)
    {
        if (propertyInfo == null || xmlNode == null)
            throw new ArgumentNullException("PropertyInfo or XmlNode cannot be null.");

