import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class CustomIoHandlerAdapter implements IoHandlerAdapter {

    @Override
    public void sessionWriteResponse(SocketChannel session, Object response) {
        try {
            // Handle the response from session write
            if (response instanceof String) {
                String message = (String) response;
                // Write the response to the session
                session.write(java.nio.ByteBuffer.wrap(message.getBytes()));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void setSocketAddress(SocketChannel session, String protocol) {
        try {
            InetSocketAddress socketAddress;
            if ("HTTP".equalsIgnoreCase(protocol)) {
                socketAddress = new InetSocketAddress("http://localhost", 80);
            } else if ("HTTPS".equalsIgnoreCase(protocol)) {
                socketAddress = new InetSocketAddress("https://localhost", 443);
            } else {
                throw new IllegalArgumentException("Unsupported protocol: " + protocol);
            }
            session.connect(socketAddress);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
