import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class MutationUtil {

    public static MutatedValueResult mutateValue(Random random, double value, double stdDevFactor, double range) {
        double mean = value;
        double stdDev = stdDevFactor * range;

        // Generate a mutated value using Gaussian distribution
        double mutatedValue = mean + random.nextGaussian() * stdDev;

        // Ensure the mutated value is within the specified range
        mutatedValue = Math.max(mean - range, Math.min(mutatedValue, mean + range));

        // Generate a list of discrete values within the range
        List<Double> discreteValues = new ArrayList<>();
        for (double i = mean - range; i <= mean + range; i += 0.1) {
            discreteValues.add(i);
        }

        return new MutatedValueResult(mutatedValue, discreteValues);
    }

    public static class MutatedValueResult {
        private final double mutatedValue;
        private final List<Double> discreteValues;

        public MutatedValueResult(double mutatedValue, List<Double> discreteValues) {
            this.mutatedValue = mutatedValue;
            this.discreteValues = discreteValues;
        }

        public double getMutatedValue() {
            return mutatedValue;
        }

        public List<Double> getDiscreteValues() {
            return discreteValues;
        }
    }
}
