public class PairProcessor {

    public static void processPairs(List<Pair<Integer, Boolean>> pairs, double percentage) {
        Random random = new Random();
        int totalPairs = pairs.size();
        int pairsToProcess = (int) (totalPairs * percentage);

        for (int i = 0; i < pairsToProcess; i++) {
            Pair<Integer, Boolean> currentPair = pairs.get(i);
            boolean isLastPair = (i == totalPairs - 1);

