import java.util.Random;
import java.util.logging.Logger;

public class NodeOperations {
    private static final Logger logger = Logger.getLogger(NodeOperations.class.getName());
    private int heartbeatCount = 0;
    private int clearCount = 0;
    private final Random random = new Random();

    public void performRandomOperations(Node node, int expectedHeartbeats, int expectedClears) {
        for (int i = 0; i < 100; i++) { // Perform 100 random operations
            if (random.nextBoolean()) {
                reportHeartbeat(node);
            } else {
                clearPrimary(node);
            }
        }
        logOperationCounts(expectedHeartbeats, expectedClears);
    }

    private void reportHeartbeat(Node node) {
        // Logic to report heartbeat
        heartbeatCount++;
        logger.info("Heartbeat reported for node: " + node.getId());
    }

    private void clearPrimary(Node node) {
        // Logic to clear primary
        clearCount++;
        logger.info("Primary cleared for node: " + node.getId());
    }

    private void logOperationCounts(int expectedHeartbeats, int expectedClears) {
        logger.info("Expected Heartbeats: " + expectedHeartbeats + ", Actual Heartbeats: " + heartbeatCount);
        logger.info("Expected Clears: " + expectedClears + ", Actual Clears: " + clearCount);
    }
}

class Node {
    private String id;

    public Node(String id) {
        this.id = id;
    }

    public String getId() {
        return id;
    }
}
