import java.net.InetSocketAddress;
import java.util.ArrayList;
import java.util.List;

public class ConnectionUtils {

    public static List<InetSocketAddress> createInetSocketAddresses(
            List<String> hostnamesAndPorts, String username, String password,
            String serverId, boolean createEnrichmentConnection,
            String driverLocation, String driverName, int connectionTimeout) {

        List<InetSocketAddress> addresses = new ArrayList<>();

        for (String hostnameAndPort : hostnamesAndPorts) {
            String[] parts = hostnameAndPort.split(":");
            if (parts.length != 2) {
                throw new ArrayIndexOutOfBoundsException("Invalid input format: " + hostnameAndPort);
            }

            String host = parts[0];
            int port;

            try {
                port = Integer.parseInt(parts[1]);
                if (port < 0 || port > 65535) {
                    throw new IllegalArgumentException("Port number out of range: " + port);
                }
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid port number: " + parts[1]);
            }

            InetSocketAddress inetSocketAddress = new InetSocketAddress(host, port);
            addresses.add(inetSocketAddress);
        }

        return addresses;
    }
}
