import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class ObjectModifier {
    private static final Random RANDOM = new Random();

    public List<Double> modifyAndCollectValues(List<Double> originalList) {
        List<Double> modifiedList = new ArrayList<>(originalList);
        List<Double> collectedValues = new ArrayList<>();
        double mean = 0.0;
        double stdDev = 0.2 * originalList.size();

        for (int i = 0; i < modifiedList.size(); i++) {
            if (RANDOM.nextBoolean()) { // Randomly decide to replace the object
                double newValue = mean + RANDOM.nextGaussian() * stdDev;
                modifiedList.set(i, newValue);
            }
        }

        collectedValues.addAll(modifiedList);
        return collectedValues;
    }
}
