import java.io.InputStream;
import java.io.IOException;
import java.net.URL;
import java.net.MalformedURLException;

public class ResourceLoader {

    public InputStream getResourceAsStream(String resourceUrl) throws IOException {
        InputStream inputStream = null;

        // Try to load the resource as a local file
        URL localResource = getClass().getResource(resourceUrl);
        if (localResource != null) {
            inputStream = localResource.openStream();
        } else {
            // If local resource is not found, try to load it as a remote URL
            try {
                URL remoteResource = new URL(resourceUrl);
                inputStream = remoteResource.openStream();
            } catch (MalformedURLException e) {
                throw new IOException("Invalid URL: " + resourceUrl, e);
            } catch (IOException e) {
                throw new IOException("Failed to open stream for URL: " + resourceUrl, e);
            }
        }

        return inputStream;
    }
}
