import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.util.Collection;
import java.util.Map;

public class JsonGenerator {

    @Nonnull
    public static String toJson(@Nonnull Object object) throws IOException {
        if (object == null) {
            return "null";
        }
        if (object instanceof String) {
            return "\"" + escapeString((String) object) + "\"";
        }
        if (object instanceof Number || object instanceof Boolean) {
            return object.toString();
        }
        if (object.getClass().isArray()) {
            return arrayToJson(object);
        }
        if (object instanceof Collection) {
            return collectionToJson((Collection<?>) object);
        }
        if (object instanceof Map) {
            return mapToJson((Map<?, ?>) object);
        }
        return objectToJson(object);
    }

    private static String arrayToJson(Object array) {
        StringBuilder json = new StringBuilder("[");
        int length = Array.getLength(array);
        for (int i = 0; i < length; i++) {
            json.append(toJson(Array.get(array, i)));
            if (i < length - 1) {
                json.append(",");
            }
        }
        json.append("]");
        return json.toString();
    }

    private static String collectionToJson(Collection<?> collection) {
        StringBuilder json = new StringBuilder("[");
        int size = collection.size();
        int i = 0;
        for (Object item : collection) {
            json.append(toJson(item));
            if (i < size - 1) {
                json.append(",");
            }
            i++;
        }
        json.append("]");
        return json.toString();
    }

    private static String mapToJson(Map<?, ?> map) {
        StringBuilder json = new StringBuilder("{");
        int size = map.size();
        int i = 0;
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            json.append("\"").append(escapeString(entry.getKey().toString())).append("\":")
                .append(toJson(entry.getValue()));
            if (i < size - 1) {
                json.append(",");
            }
            i++;
        }
        json.append("}");
        return json.toString();
    }

    private static String objectToJson(Object object) {
        StringBuilder json = new StringBuilder("{");
        Field[] fields = object.getClass().getDeclaredFields();
        int length = fields.length;
        for (int i = 0; i < length; i++) {
            Field field = fields[i];
            field.setAccessible(true);
            try {
                json.append("\"").append(escapeString(field.getName())).append("\":")
                    .append(toJson(field.get(object)));
                if (i < length - 1) {
                    json.append(",");
                }
            } catch (IllegalAccessException e) {
                // Handle exception
            }
        }
        json.append("}");
        return json.toString();
    }

    private static String escapeString(String str) {
        return str.replace("\\", "\\\\")
                  .replace("\"", "\\\"")
                  .replace("\b", "\\b")
                  .replace("\f", "\\f")
                  .replace("\n", "\\n")
                  .replace("\r", "\\r")
                  .replace("\t", "\\t");
    }
}
