import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public class WeightedItemNormalizer {

    public static <T> Map<T, Double> normalizeWeights(List<T> items, Function<T, Double> weightFunction) {
        Map<T, Double> weightMap = new HashMap<>();
        double totalWeight = 0.0;

        // Calculate total weight
        for (T item : items) {
            double weight = weightFunction.apply(item);
            weightMap.put(item, weight);
            totalWeight += weight;
        }

        // Normalize weights
        Map<T, Double> normalizedWeights = new HashMap<>();
        for (Map.Entry<T, Double> entry : weightMap.entrySet()) {
            normalizedWeights.put(entry.getKey(), entry.getValue() / totalWeight);
        }

        return normalizedWeights;
    }
}
