import java.util.HashMap;

public class DisjointPairs {
    private int[] parent;
    private int[] rank;

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public int countDisjointPairs(int[] arr) {
        int n = arr.length;
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }

        int count = 0;
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (find(i) != find(j)) {
                    count++;
                    union(i, j);
                }
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");
        return count;
    }

    public static void main(String[] args) {
        DisjointPairs dp = new DisjointPairs();
        int[] arr = {1, 2, 3, 4, 5};
        int result = dp.countDisjointPairs(arr);
        System.out.println("Number of disjoint pairs: " + result);
    }
}
