import java.util.List;
import java.util.Collections;

public class GeoPointComparator {

    public static void compareGeoPoints(List<List<Double>> set1, List<List<Double>> set2, double tolerance) throws Exception {
        if (set1.size() != set2.size()) {
            throw new Exception("The number of documents in the two sets is not equal.");
        }

        for (int i = 0; i < set1.size(); i++) {
            List<Double> points1 = set1.get(i);
            List<Double> points2 = set2.get(i);

            if (points1.size() != points2.size()) {
                throw new Exception("The number of values in document " + i + " is not equal.");
            }

            if (points1.size() > 0) {
                Collections.sort(points1);
                Collections.sort(points2);

                for (int j = 0; j < points1.size(); j++) {
                    if (Math.abs(points1.get(j) - points2.get(j)) > tolerance) {
                        throw new Exception("Values in document " + i + " at index " + j + " are not equal within the specified tolerance.");
                    }
                }
            }
        }
    }
}
