    private DelegationTokenManagerService tokenManagerService;

    public DelegationTokenManager(DelegationTokenManagerService tokenManagerService) {
        this.tokenManagerService = tokenManagerService;
    }

    public Object manageDelegationToken(String username, String password, String tokenId) {
        try {
            // Create a new delegation token
            String token = tokenManagerService.createToken(username, password);
            return token;
        } catch (TokenCreationException e) {
            // Handle token creation failure
            System.err.println("Token creation failed: " + e.getMessage());
            return null;
        }
    }

    public boolean verifyDelegationToken(String tokenId) {
        try {
            // Verify the existing delegation token
            return tokenManagerService.verifyToken(tokenId);
        } catch (TokenVerificationException e) {
            // Handle token verification failure
            System.err.println("Token verification failed: " + e.getMessage());
            return false;
        }
    }

    public boolean renewDelegationToken(String tokenId) {
        try {
            // Renew the existing delegation token
            return tokenManagerService.renewToken(tokenId);
        } catch (TokenRenewalException e) {
            // Handle token renewal failure
            System.err.println("Token renewal failed: " + e.getMessage());
            return false;
        }
    }

    public boolean cancelDelegationToken(String tokenId) {
        try {
            // Cancel the existing delegation token
            return tokenManagerService.cancelToken(tokenId);
        } catch (TokenCancellationException e) {
            // Handle token cancellation failure
            System.err.println("Token cancellation failed: " + e.getMessage());
            return false;
        }
