import java.util.Random;
import java.util.concurrent.ExecutorService;

public class GraphDatabasePopulator {

    private SQLgGraph graph;

    public GraphDatabasePopulator(SQLgGraph graph) {
        this.graph = graph;
    }

    public void populateGraph(ExecutorService executorService, int iterations) {
        Random random = new Random();

        for (int i = 0; i < iterations; i++) {
            executorService.submit(() -> {
                try {
                    graph.tx().begin();

                    // Create two vertices with random properties
                    Vertex vertex1 = graph.addVertex("label", "Vertex" + random.nextInt(1000));
                    vertex1.property("property1", random.nextInt(100));
                    vertex1.property("property2", "Value" + random.nextInt(100));

                    Vertex vertex2 = graph.addVertex("label", "Vertex" + random.nextInt(1000));
                    vertex2.property("property1", random.nextInt(100));
                    vertex2.property("property2", "Value" + random.nextInt(100));

                    // Create an edge between the two vertices with random properties
                    Edge edge = vertex1.addEdge("connects", vertex2);
                    edge.property("weight", random.nextDouble() * 10);
                    edge.property("type", "relationship" + random.nextInt(5));

                    // Commit the transaction
                    graph.tx().commit();
                } catch (Exception e) {
                    graph.tx().rollback();
                    e.printStackTrace();
                }
            });
        }
    }
}
