import org.apache.hadoop.io.Text;
import org.apache.hadoop.security.UserGroupInformation;
import org.apache.hadoop.security.SecurityUtil;
import org.apache.hadoop.conf.Configuration;

import javax.security.auth.login.LoginContext;
import javax.security.auth.login.LoginException;
import java.net.MalformedURLException;
import java.net.URL;

public class KerberosTokenRetriever {

    public static boolean retrieveDelegationToken(String serverUrl, int port) {
        Text delegationToken = null;
        boolean hasToken = false;

        try {
            // Set up the Kerberos configuration
            Configuration conf = new Configuration();
            conf.set("hadoop.security.authentication", "kerberos");
            UserGroupInformation.setConfiguration(conf);

            // Login using the Kerberos credentials
            LoginContext loginContext = new LoginContext("Client", new KerberosCallbackHandler());
            loginContext.login();

            // Retrieve the delegation token
            URL url = new URL(serverUrl + ":" + port);
            delegationToken = UserGroupInformation.getCurrentUser().getCredentials().getToken(url.toString());

            if (delegationToken != null) {
                hasToken = true;
            }
        } catch (LoginException e) {
            System.err.println("Login failed: " + e.getMessage());
        } catch (MalformedURLException e) {
            System.err.println("Invalid URL: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        }

        return hasToken;
    }
}
