        try {
            String targetUrl = "http://example.com";
            String proxyHost1 = "proxy1.example.com";
            int proxyPort1 = 8080;
            String proxyHost2 = "proxy2.example.com";
            int proxyPort2 = 8081;

            // Set up the first proxy
            Proxy proxy1 = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxyHost1, proxyPort1));
            makeHttpRequest(targetUrl, proxy1);

            // Set up the second proxy
            Proxy proxy2 = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxyHost2, proxyPort2));
            makeHttpRequest(targetUrl, proxy2);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void makeHttpRequest(String targetUrl, Proxy proxy) {
        try {
            URL url = new URL(targetUrl);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection(proxy);
            connection.setRequestMethod("GET");

            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            System.out.println("Response from " + proxy.address() + ": " + response.toString());
        } catch (Exception e) {
            System.out.println("Error using proxy " + proxy.address() + ": " + e.getMessage());
        }
    }
}
