            httpConn.setConnectTimeout(5000); // Set connect timeout
            httpConn.setRequestMethod("GET");
            httpConn.connect();

            // Check the response code
            if (httpConn.getResponseCode() == HttpURLConnection.HTTP_OK) {
                String fileName = fileURL.substring(fileURL.lastIndexOf("/") + 1);
                File file = new File(fileName);
                inputStream = httpConn.getInputStream();
                outputStream = new FileOutputStream(file);

                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
                fileURI = file.toURI().toString(); // Get the file URI
            } else {
                System.out.println("No file to download. Server replied HTTP code: " + httpConn.getResponseCode());
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (outputStream != null) outputStream.close();
                if (inputStream != null) inputStream.close();
                if (httpConn != null) httpConn.disconnect();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return fileURI; // Return the file URI or null if unsuccessful
    }
