import org.apache.zookeeper.server.ZooKeeperServer;
import org.apache.zookeeper.server.ServerCnxnFactory;
import org.apache.zookeeper.server.NIOServerCnxnFactory;

import java.io.File;
import java.io.IOException;
import java.net.BindException;
import java.net.InetSocketAddress;

public class ZooKeeperServerSetup {
    public static void main(String[] args) {
        String transactionLogDir = "path/to/transaction/log"; // Specify your transaction log directory
        int minPort = 2181; // Starting port
        int maxPort = 2191; // Ending port
        int tickTime = 2000; // Tick time in milliseconds
        int sessionTimeout = 60000; // Session timeout in milliseconds

        File logDir = new File(transactionLogDir);
        if (!logDir.exists()) {
            logDir.mkdirs();
        }

        ZooKeeperServer zkServer = new ZooKeeperServer(logDir, logDir, tickTime);
        ServerCnxnFactory factory = null;

        for (int port = minPort; port <= maxPort; port++) {
            try {
                InetSocketAddress address = new InetSocketAddress(port);
                factory = NIOServerCnxnFactory.createFactory(address, 100);
                factory.startup(zkServer);
                System.out.println("ZooKeeper server started on port: " + port);
                break; // Exit loop if server starts successfully
            } catch (BindException e) {
                // Ignore and try the next port
                System.out.println("Port " + port + " is already in use, trying next port.");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        if (factory != null) {
            zkServer.setSessionTimeout(sessionTimeout);
        }
    }
}
