import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class HMMPartOfSpeechTagger {
    private Map<String, String> hmmModel;

    public HMMPartOfSpeechTagger(String modelFilePath) throws IOException {
        this.hmmModel = loadHMMModel(modelFilePath);
    }

    private Map<String, String> loadHMMModel(String modelFilePath) throws IOException {
        Map<String, String> model = new HashMap<>();
        try (BufferedReader br = new BufferedReader(new FileReader(modelFilePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] parts = line.split("\\s+");
                if (parts.length == 2) {
                    model.put(parts[0], parts[1]);
                }
            }
        }
        return model;
    }

    public Map<String, String> tagText(String text) {
        Map<String, String> taggedWords = new HashMap<>();
        String[] words = text.split("\\s+");
        for (String word : words) {
            String tag = hmmModel.getOrDefault(word, "UNKNOWN");
            taggedWords.put(word, tag);
        }
        return taggedWords;
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java HMMPartOfSpeechTagger <modelFilePath> <text>");
            return;
        }

        String modelFilePath = args[0];
        String text = args[1];

        try {
            HMMPartOfSpeechTagger tagger = new HMMPartOfSpeechTagger(modelFilePath);
            Map<String, String> taggedWords = tagger.tagText(text);
            taggedWords.forEach((word, tag) -> System.out.println(word + ": " + tag));
        } catch (IOException e) {
            System.err.println("Error loading HMM model: " + e.getMessage());
        }
    }
}
