        String command = String.format("convert %s -rotate %s rotated_image.jpg", imagePath, rotationAngle);
        Process process = Runtime.getRuntime().exec(command);
        int exitCode = process.waitFor();

        if (exitCode != 0) {
            throw new IOException("Image rotation failed with exit code: " + exitCode);
        }

        displayImage("rotated_image.jpg");
    }

    private static void displayImage(String imagePath) {
        JFrame frame = new JFrame();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        try {
            BufferedImage img = ImageIO.read(new File(imagePath));
            JLabel label = new JLabel(new ImageIcon(img));
            frame.getContentPane().add(label);
            frame.pack();
            frame.setVisible(true);
        } catch (IOException e) {
            System.err.println("Error displaying image: " + e.getMessage());
        }
    }
}
