import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public int startServer(int port) {
    int serverSocket = -1;
    try {
        Selector selector = Selector.open();
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();

        serverSocketChannel.socket().bind(new InetSocketAddress(port), 100);
        serverSocketChannel.socket().setReuseAddress(true);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        ExecutorService executor = Executors.newCachedThreadPool();
        serverSocket = serverSocketChannel.socket().getFD();

        while (true) {
            selector.select();
            if (selector.isOpen()) {
                SelectionKey key = selector.selectedKeys().iterator().next();
                selector.selectedKeys().clear();

                if (key.isAcceptable()) {
                    SocketChannel clientSocketChannel = serverSocketChannel.accept();
                    if (clientSocketChannel != null) {
                        clientSocketChannel.register(selector, SelectionKey.OP_READ);
                        executor.submit(new ServerHandler(clientSocketChannel));
                    }
                }
            } else {
                break;
            }
        }

        selector.close();
        serverSocketChannel.close();
    } catch (IOException e) {
        e.printStackTrace();
    } finally {
        if (serverSocket != -1) {
            try {
                ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
                SocketChannel socketChannel = SocketChannel.open();
                socketChannel.configureBlocking(false);
                socketChannel.connect(new InetSocketAddress("localhost", port));
                serverSocketChannel.register(selector, SelectionKey.OP_CONNECT);
                serverSocketChannel.close();
                socketChannel.close();

                Selector selector = Selector.open();
                while (selector.select() > 0) {
                    SelectionKey key = selector.selectedKeys().iterator().next();
                    selector.selectedKeys().clear();

                    if (key.isConnectable()) {
                        SocketChannel socketChannel = (SocketChannel) key.channel();
                        if (socketChannel.isConnectionPending()) {
                            socketChannel.finishConnect();
                            socketChannel.close();
                        }
                    }
                }

                selector.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    return serverSocket;
}

