import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileHashGenerator {

    public static void generateMD5Hash(String filePath) {
        FileInputStream fis = null;
        FileOutputStream fos = null;
        try {
            File inputFile = new File(filePath);
            File outputFile = new File(filePath + ".md5");

            // Create MD5 hash
            MessageDigest md = MessageDigest.getInstance("MD5");
            fis = new FileInputStream(inputFile);
            byte[] dataBytes = new byte[1024];
            int bytesRead;

            System.out.println("Generating MD5 hash for: " + inputFile.getName());
            while ((bytesRead = fis.read(dataBytes)) != -1) {
                md.update(dataBytes, 0, bytesRead);
            }

            // Convert the byte array to hex format
            StringBuilder sb = new StringBuilder();
            for (byte b : md.digest()) {
                sb.append(String.format("%02x", b));
            }

            // Write the hash to the output file
            fos = new FileOutputStream(outputFile);
            fos.write(sb.toString().getBytes());
            System.out.println("MD5 hash written to: " + outputFile.getName());

        } catch (IOException | NoSuchAlgorithmException e) {
            System.err.println("Error: " + e.getMessage());
        } finally {
            try {
                if (fis != null) fis.close();
