import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Iterator;

public class ETagGenerator {

    public static String generateETag(Change change) {
        StringBuilder stringBuilder = new StringBuilder();
        long lastUpdated = change.getLastUpdated().getTime();
        int rowVersion = change.getRowVersion();
        String accountId = change.getAccountId();

        stringBuilder.append(lastUpdated)
                     .append(rowVersion)
                     .append(accountId);

        ProjectState projectState = change.getProjectState();
        Iterator<Revision> revisions = projectState.getRevisions().iterator();
        while (revisions.hasNext()) {
            Revision revision = revisions.next();
            stringBuilder.append(revision.getId());
        }

        return md5Hash(stringBuilder.toString());
    }

    private static String md5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return "\"" + hexString.toString() + "\"";
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
