        this.host = host;
        this.port = port;
    }

    public void connectAndSend(String message) throws IOException {
        try {
            socket = new Socket(host, port);
            socket.setKeepAlive(true);
            socket.setSoTimeout(5000); // Set a timeout for socket operations

            sendMessage(message);
        } catch (SocketException e) {
            closeSocket();
            throw new IOException("Socket error: " + e.getMessage(), e);
        } catch (IOException e) {
            closeSocket();
            throw new IOException("I/O error: " + e.getMessage(), e);
        }
    }

    public void sendMessage(String message) throws IOException {
        if (socket == null || socket.isClosed()) {
            throw new IOException("Socket is not connected.");
        }

        try (OutputStream outputStream = socket.getOutputStream()) {
            outputStream.write(message.getBytes());
            outputStream.flush();
        } catch (IOException e) {
            closeSocket();
            throw new IOException("Failed to send message: " + e.getMessage(), e);
        }
    }

    public void flushAndResend(String message) throws IOException {
        sendMessage(message); // Re-send the message buffer
    }

    private void closeSocket() {
        if (socket != null) {
            try {
                socket.close();
            } catch (IOException e) {
                // Log or handle the exception
            }
        }
    }
}
