import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamReader;
import javax.xml.transform.Source;
import javax.xml.transform.stream.StreamSource;
import java.io.InputStream;
import java.io.IOException;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

public class XmlParser {

    public static Source parseXml(InputStream inputStream) {
        if (inputStream == null || inputStream.available() == 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Input stream is empty");
        }

        try {
            XMLInputFactory factory = XMLInputFactory.newInstance();
            XMLStreamReader xmlStreamReader = factory.createXMLStreamReader(inputStream);
            return new StreamSource(xmlStreamReader);
        } catch (Exception e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Failed to read XML", e);
        }
    }
}
