class Person implements Serializable {
    private String name;
    private int age;

    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }
}

public class SerializationExample {
    public static void main(String[] args) {
        try {
            // Create an object
            Person originalPerson = new Person("John Doe", 30);

            // Serialize the object to a byte array
            byte[] serializedData = serialize(originalPerson);

            // Deserialize the byte array back to an object
            Person deserializedPerson = (Person) deserialize(serializedData);

            // Verify that the deserialized object has the same properties
            System.out.println("Original Name: " + originalPerson.getName());
            System.out.println("Deserialized Name: " + deserializedPerson.getName());
            System.out.println("Original Age: " + originalPerson.getAge());
            System.out.println("Deserialized Age: " + deserializedPerson.getAge());

            if (originalPerson.getName().equals(deserializedPerson.getName()) &&
                originalPerson.getAge() == deserializedPerson.getAge()) {
                System.out.println("The deserialized object matches the original.");
            } else {
                System.out.println("The deserialized object does not match the original.");
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

    private static byte[] serialize(Serializable obj) throws IOException {
        try (ByteArrayOutputStream byteOut = new ByteArrayOutputStream();
             ObjectOutputStream out = new ObjectOutputStream(byteOut)) {
            out.writeObject(obj);
            return byteOut.toByteArray();
        }
    }

    private static Object deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream byteIn = new ByteArrayInputStream(data);
             ObjectInputStream in = new ObjectInputStream(byteIn)) {
            return in.readObject();
        }
    }
}
