public class DiscoveryActor extends AbstractActor {
    private final ActorRef tcpManager;
    private final int port;
    private final String remoteAddress;
    private final int remotePort;

    public DiscoveryActor(int port, String remoteAddress, int remotePort) {
        this.port = port;
        this.remoteAddress = remoteAddress;
        this.remotePort = remotePort;
        this.tcpManager = Tcp.get(getContext().getSystem()).getManager();
    }

    @Override
    public Receive createReceive() {
        return receiveBuilder()
                .match(Tcp.Bound.class, this::onBound)
                .match(Tcp.Received.class, this::onReceived)
                .match(Tcp.CommandFailed.class, this::onCommandFailed)
                .build();
    }

    private void onBound(Tcp.Bound bound) {
        System.out.println("Listening on port: " + port);
        sendDiscoveryMessage();
    }

    private void onReceived(Tcp.Received received) {
        // Handle incoming messages if needed
    }

    private void onCommandFailed(Tcp.CommandFailed commandFailed) {
        System.out.println("Command failed: " + commandFailed);
    }

    private void sendDiscoveryMessage() {
        String message = "Discovery Message";
        ByteString data = ByteString.fromString(message);
        InetSocketAddress remote = new InetSocketAddress(remoteAddress, remotePort);
        tcpManager.tell(Tcp.connect(remote), getSelf());
        tcpManager.tell(Tcp.write(data), getSelf());
    }

