        LoginContext loginContext = new LoginContext("YourLoginModule");
        loginContext.login();

        // Resolve the host address
        InetAddress localAddress = InetAddress.getByName(host);
        if (!localAddress.isLoopbackAddress() && !localAddress.isLinkLocalAddress()) {
            throw new UnknownHostException("Invalid local address: " + host);
        }

        // Create socket and set timeout
        Socket socket = new Socket();
        socket.connect(new java.net.InetSocketAddress(host, port), timeout);

        // Set socket options
        socket.setSoTimeout(timeout);
        socket.setKeepAlive(true);

        // Optionally wrap the socket with SSL
        SSLSocketFactory sslSocketFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
        socket = sslSocketFactory.createSocket(socket, host, port, true);

        // Start pinging the server at the specified interval
        startPing(socket);

        return socket;
    }

    private void startPing(Socket socket) {
        new Thread(() -> {
            try {
                while (!socket.isClosed()) {
                    // Implement ping logic here
                    Thread.sleep(pingInterval);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }).start();
    }
}
