public class ProcessExecutor {

    public boolean executeProcess(List<String> command) {
        Process process = null;
        try {
            // Convert the command list to an array
            String[] commandArray = command.toArray(new String[0]);
            // Start the process
            process = Runtime.getRuntime().exec(commandArray);
            logExecutionDetails(commandArray);

            // Start a watchdog thread to monitor the process
            new Thread(() -> {
                try {
                    int exitCode = process.waitFor();
                    logProcessExit(exitCode);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }).start();

            return true; // Process started successfully
        } catch (Exception e) {
            e.printStackTrace();
            return false; // Failed to start process
        }
    }

    private void logExecutionDetails(String[] command) {
        System.out.println("Executing command: " + String.join(" ", command));
