public class SerializationTest {

    public static void main(String[] args) {
        try {
            MyObject obj = new MyObject("Test", 123);
            long totalTime = 0;
            int totalSize = 0;

            for (int i = 0; i < 500; i++) {
                long startTime = System.nanoTime();

                // Serialize
                ByteArrayOutputStream byteOut = new ByteArrayOutputStream();
                ObjectOutputStream out = new ObjectOutputStream(byteOut);
                out.writeObject(obj);
                out.flush();
                out.close();

                byte[] serializedData = byteOut.toByteArray();
                totalSize += serializedData.length;

                // Deserialize
                ByteArrayInputStream byteIn = new ByteArrayInputStream(serializedData);
                ObjectInputStream in = new ObjectInputStream(byteIn);
                MyObject deserializedObj = (MyObject) in.readObject();
                in.close();

                long endTime = System.nanoTime();
                totalTime += (endTime - startTime);
            }

            System.out.println("Total time taken for 500 serializations and deserializations: " + (totalTime / 1_000_000) + " ms");
            System.out.println("Total size of serialized data: " + totalSize + " bytes");

        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

