import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class CommandExecutor {

    public String executeCommand(String command, boolean waitForCompletion) {
        StringBuilder outputBuilder = new StringBuilder();
        Process process = null;

        try {
            process = Runtime.getRuntime().exec(command);
            if (waitForCompletion) {
                process.waitFor();
            }

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
            }

            if (!waitForCompletion) {
                process.waitFor(); // Ensure we wait if not already done
            }

        } catch (IOException e) {
            outputBuilder.append("Error executing command: ").append(e.getMessage());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            outputBuilder.append("Command execution interrupted: ").append(e.getMessage());
        } finally {
            if (process != null) {
                process.destroy();
            }
        }

        return outputBuilder.toString().trim();
    }
}
