import java.io.*;
import java.nio.file.*;
import java.sql.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.xml.sax.SAXException;

public class FileDataExtractor {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: FileDataExtractor <directory> <output_file>");
            return;
        }

        String directoryPath = args[0];
        String outputFilePath = args[1];
        StringBuilder extractedData = new StringBuilder();

        try {
            Files.walk(Paths.get(directoryPath)).forEach(filePath -> {
                if (Files.isRegularFile(filePath)) {
                    try {
                        if (filePath.toString().endsWith(".xml")) {
                            extractedData.append(parseXML(filePath.toFile()));
                        } else if (filePath.toString().endsWith(".sql")) {
                            extractedData.append(parseSQL(filePath.toFile()));
                        } else {
                            System.out.println("Unsupported file format: " + filePath);
                        }
                    } catch (Exception e) {
                        System.err.println("Error processing file: " + filePath + " - " + e.getMessage());
                    }
                }
            });

            writeOutput(outputFilePath, extractedData.toString());
        } catch (IOException e) {
            System.err.println("Error reading directory: " + e.getMessage());
        }
    }

    private static String parseXML(File file) throws IOException, SAXException, ParserConfigurationException {
        StringBuilder result = new StringBuilder();
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(file);
        doc.getDocumentElement().normalize();

        NodeList nodeList = doc.getElementsByTagName("*");
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);
            result.append(node.getNodeName()).append(": ").append(node.getTextContent()).append("\n");
        }
        return result.toString();
    }

    private static String parseSQL(File file) throws IOException {
        StringBuilder result = new StringBuilder();
        try (Connection conn = DriverManager.getConnection("jdbc:sqlite::memory:")) {
            Statement stmt = conn.createStatement();
            String sql = new String(Files.readAllBytes(file.toPath()));
            ResultSet rs = stmt.executeQuery(sql);
            ResultSetMetaData metaData = rs.getMetaData();
            int columnCount = metaData.getColumnCount();

            while (rs.next()) {
                for (int i = 1; i <= columnCount; i++) {
                    result.append(metaData.getColumnName(i)).append(": ").append(rs.getString(i)).append("\n");
                }
                result.append("\n");
            }
        } catch (SQLException e) {
            System.err.println("SQL error processing file: " + file + " - " + e.getMessage());
        }
        return result.toString();
    }

    private static void writeOutput(String outputFilePath, String data) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFilePath))) {
            writer.write(data);
        } catch (IOException e) {
            System.err.println("Error writing output file: " + e.getMessage());
        }
    }
}
