import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.Serializable;

public class SingletonLoader<T extends Serializable> {
    private static T instance;
    private static final String FILE_PATH = "singleton_instance.ser";

    public static synchronized T getInstance(Class<T> clazz) {
        if (instance == null) {
            File file = new File(FILE_PATH);
            if (file.exists()) {
                try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                    instance = clazz.cast(ois.readObject());
                } catch (IOException | ClassNotFoundException e) {
                    e.printStackTrace();
                    instance = createNewInstance(clazz);
                }
            } else {
                instance = createNewInstance(clazz);
            }
        }
        return instance;
    }

    private static <T> T createNewInstance(Class<T> clazz) {
        try {
            return clazz.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
