import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathFactory;
import org.w3c.dom.Document;

public class XmlEvaluator {

    public static String evaluateXPath(String responseValue, String xpathExpression) throws Exception {
        if (responseValue == null || xpathExpression == null) {
            throw new IllegalArgumentException("Response value and XPath expression must not be null");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new java.io.ByteArrayInputStream(responseValue.getBytes()));

        XPathFactory xPathFactory = XPathFactory.newInstance();
        XPath xpath = xPathFactory.newXPath();
        XPathExpression expression = xpath.compile(xpathExpression);

        Boolean result = (Boolean) expression.evaluate(document, XPathConstants.BOOLEAN);

        if (result) {
            return null; // No failure detail
        } else {
            return "Failure: XPath expression returned false"; // Failure detail
        }
    }
}
