        try {
            NFA originalNFA = new NFA(5);
            byte[] serializedNFA = serializeNFA(originalNFA);
            NFA deserializedNFA = deserializeNFA(serializedNFA);

            System.out.println("Original NFA: " + originalNFA.getWindowLength());
            System.out.println("Deserialized NFA: " + deserializedNFA.getWindowLength());
            System.out.println("Are they equal? " + originalNFA.equals(deserializedNFA));
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
