public void executeProcess(String[] command) {
    int timeOut = 60000; // Default timeout
    boolean processRunning = true;

    while (processRunning) {
        Process proc = null;
        try {
            proc = Runtime.getRuntime().exec(command);
            StringBuilder outputBuilder = new StringBuilder();
            StringBuilder errorBuilder = new StringBuilder();

            // Read output
            try (BufferedReader br = new BufferedReader(new InputStreamReader(proc.getInputStream()))) {
                String line;
                while ((line = br.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
            } catch (IOException e) {
                logger.warn("Error reading stdout: {}", e.getMessage());
            }

            // Read error stream
            try (BufferedReader br = new BufferedReader(new InputStreamReader(proc.getErrorStream()))) {
                String line;
                while ((line = br.readLine()) != null) {
                    errorBuilder.append(line).append("\n");
                }
            } catch (IOException e) {
                logger.warn("Error reading stderr: {}", e.getMessage());
            }

            // Wait for process to finish
            boolean finished = proc.waitFor(timeOut, TimeUnit.MILLISECONDS);
            if (!finished) {
                logger.warn("Process timed out, terminating...");
                proc.destroyForcibly();
            }

            // Log output and error
            logger.info("Process output: {}", outputBuilder.toString());
            logger.error("Process error: {}", errorBuilder.toString());

            processRunning = false; // Exit loop if process completes

        } catch (IOException | InterruptedException e) {
            logger.warn("Exception occurred while executing process: {}", e.getMessage());
            if (proc != null) {
                proc.destroyForcibly(); // Ensure process is terminated
            }
        }
    }
}
