import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.TimeUnit;

public class QueryGenerator {

    private static final String COMMAND_TEMPLATE = "path/to/external/tool --generate-query %s";
    private static final int TIME_OUT = 60000; // 60 seconds

    public void generateQuery(String template) {
        String commandLine = String.format(COMMAND_TEMPLATE, template);
        Process proc = null;

        try {
            proc = Runtime.getRuntime().exec(commandLine);
            StringBuilder outputBuilder = new StringBuilder();
            StringBuilder errorBuilder = new StringBuilder();

            // Read the output
            try (BufferedReader br = new BufferedReader(new InputStreamReader(proc.getInputStream()))) {
                String line;
                while ((line = br.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
            } catch (IOException e) {
                System.err.println("Error reading output: " + e.getMessage());
            }

            // Read the error stream
            try (BufferedReader br = new BufferedReader(new InputStreamReader(proc.getErrorStream()))) {
                String line;
                while ((line = br.readLine()) != null) {
                    errorBuilder.append(line).append("\n");
                }
            } catch (IOException e) {
                System.err.println("Error reading error stream: " + e.getMessage());
            }

            // Wait for the process to complete
            boolean finished = proc.waitFor(TIME_OUT, TimeUnit.MILLISECONDS);
            if (!finished) {
                System.err.println("Process timed out, terminating...");
                proc.destroyForcibly();
            }

            // Output results
            System.out.println("Output:\n" + outputBuilder.toString());
            System.err.println("Errors:\n" + errorBuilder.toString());

        } catch (IOException e) {
            System.err.println("Error executing command: " + e.getMessage());
        } catch (InterruptedException e) {
            System.err.println("Process was interrupted: " + e.getMessage());
        } finally {
            if (proc != null) {
                proc.destroy();
            }
        }
    }

    public static void main(String[] args) {
        QueryGenerator generator = new QueryGenerator();
        generator.generateQuery("your-template-here");
    }
