public class ShellCommandExecutor {

    public int executeCommand(String[] command) {
        Process process = null;
        int exitValue = -1;

        try {
            process = Runtime.getRuntime().exec(command);
            // Wait for the process to complete
            exitValue = process.waitFor();
        } catch (IOException e) {
            System.err.println("IOException occurred while executing command: " + e.getMessage());
        } catch (InterruptedException e) {
            System.err.println("InterruptedException occurred while waiting for command to finish: " + e.getMessage());
            Thread.currentThread().interrupt(); // Restore interrupted status
        } finally {
            if (process != null) {
                process.destroy(); // Ensure the process is destroyed
            }
        }

        return exitValue;
    }

    public static void main(String[] args) {
        ShellCommandExecutor executor = new ShellCommandExecutor();
        String[] command = {"ls", "-l"}; // Example command
        int exitCode = executor.executeCommand(command);
        System.out.println("Command exited with code: " + exitCode);
    }
}
