public class CommandExecutor {

    public static void executeCommand(String command) {
        try {
            // Check if the command is a Windows shell script
            if (command.endsWith(".bat") || command.endsWith(".cmd")) {
                command = "cmd.exe /c " + escapeWindowsCommand(command);
            } else {
                command = escapeWindowsCommand(command);
            }

            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static String escapeWindowsCommand(String command) {
        StringBuilder escapedCommand = new StringBuilder();
        for (char c : command.toCharArray()) {
            switch (c) {
                case '%':
                case '!':
                case '"':
                case '\'':
                case '#':
                case '&':
                case ';':
                case '`':
                case '|':
                case '*':
                case '?':
                case '~':
                case '<':
                case '>':
                case '^':
                case '(':
                case ')':
                case '[':
                case ']':
                case '{':
                case '}':
                case '$':
                case '\\':
                    escapedCommand.append('^'); // Escape special characters
                    // fall through
                default:
                    escapedCommand.append(c);
            }
        }
        return escapedCommand.toString();
    }

    public static void main(String[] args) {
        executeCommand("your_command_here");
    }
}
