import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;

public class XmlPropertyModifier {

    public boolean modifyProperty(String propertyGroup, String propertyName, String newValue, String xmlFilePath) {
        try {
            File xmlFile = new File(xmlFilePath);
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(xmlFile);

            XPath xpath = XPathFactory.newInstance().newXPath();
            String xpathExpression = String.format("//%s/%s", propertyGroup, propertyName);
            XPathExpression expr = xpath.compile(xpathExpression);

            Node propertyNode = (Node) expr.evaluate(doc, XPathConstants.NODE);
            if (propertyNode != null) {
                propertyNode.setTextContent(newValue);

                // Save the changes back to the XML file
                TransformerFactory transformerFactory = TransformerFactory.newInstance();
                Transformer transformer = transformerFactory.newTransformer();
                DOMSource source = new DOMSource(doc);
                OutputStream outputStream = new FileOutputStream(xmlFile);
                StreamResult result = new StreamResult(outputStream);
                transformer.transform(source, result);
                outputStream.close();
                return true;
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return false;
    }
}
