import java.net.InetAddress;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class NodeIdentifier {

    public static long generateNodeId() {
        try {
            // Get the local host address
            InetAddress localHost = InetAddress.getLocalHost();
            byte[] addressBytes = localHost.getAddress();

            // Generate MD5 hash
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hash = md.digest(addressBytes);

            // Convert the first 8 bytes of the hash to a long
            long nodeId = 0;
            for (int i = 0; i < 8; i++) {
                nodeId = (nodeId << 8) | (hash[i] & 0xFF);
            }

            // Ensure the upper 8 bits are set to 0
            return nodeId & 0x00FFFFFFFFFFFFFFL; // Mask to keep only the lower 56 bits
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate node ID", e);
        }
    }

    public static void main(String[] args) {
        long nodeId = generateNodeId();
        System.out.println("Generated Node ID: " + nodeId);
    }
}
