import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public class MGF1 {

    public static byte[] generateMask(int maskLength, byte[] seed, String digestAlgorithm) throws NoSuchAlgorithmException {
        int hashLength = getDigestLength(digestAlgorithm);
        int d = (int) Math.ceil((double) maskLength / hashLength);
        byte[] mask = new byte[maskLength];
        byte[] buffer = new byte[seed.length + 4];
        MessageDigest digest = MessageDigest.getInstance(digestAlgorithm);

        for (int i = 0; i < d; i++) {
            // Copy seed into buffer
            System.arraycopy(seed, 0, buffer, 0, seed.length);
            // Append the integer i as a 4-byte big-endian value
            buffer[seed.length] = (byte) (i >> 24);
            buffer[seed.length + 1] = (byte) (i >> 16);
            buffer[seed.length + 2] = (byte) (i >> 8);
            buffer[seed.length + 3] = (byte) (i);

            // Hash the buffer
            byte[] hash = digest.digest(buffer);
            // Copy the hash into the mask
            int offset = i * hashLength;
            int length = Math.min(hashLength, maskLength - offset);
            System.arraycopy(hash, 0, mask, offset, length);
        }

        return mask;
    }

    private static int getDigestLength(String algorithm) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        return digest.getDigestLength();
    }
}
