protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    String configFilePath = "/path/to/configuration/file.txt"; // Specify the path to the configuration file
    response.setContentType("text/plain");

    try (InputStream in = getServletContext().getResourceAsStream(configFilePath)) {
        if (in == null) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "Configuration file not found.");
            return;
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(in));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null) {
            content.append(line).append("\n");
        }

        response.getWriter().write(content.toString());
        response.getWriter().flush();
    } catch (IOException e) {
        response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Error reading configuration file.");
        log("Error reading configuration file: " + e.getMessage(), e);
    }
