import secrets

def generate_unique_identifier(length: int, base: int, seed: str = '') -> str:
    """
    Generate a unique identifier of specified length using random numbers in a given base.
    If the input seed is empty, a new identifier is generated.
    If the seed is provided, it is used to seed the random number generator.
