const fs = require('fs');

function writeResultsToFile(command) {
    const { resultsTo, results } = command;
    const output = results.map(item => {
        return item.error ? `****ERROR ${item.error}` : item.result;
    }).join('\n');

    fs.writeFile(resultsTo, output, (err) => {
        if (err) {
            console.error('Error writing to file:', err);
        }
    });
}
