void parse_openflow_action(uint8_t *buffer, uint32_t offset, ActionDict *result, ErrorDict *error) {
    if (offset + sizeof(uint16_t) > sizeof(buffer)) {
        error->error_code = ERROR_INVALID_LENGTH;
        error->message = "Buffer length is insufficient for action length";
        return;
    }

    uint16_t action_length = (buffer[offset] << 8) | buffer[offset + 1];
    if (action_length < sizeof(Action)) {
        error->error_code = ERROR_INVALID_LENGTH;
        error->message = "Invalid action length";
        return;
    }

    if (buffer[offset + 2] != 1) { // Assuming 1 is a valid action type
        error->error_code = ERROR_INVALID_TYPE;
        error->message = "Invalid action type";
        return;
    }

    // Parse the action
    result->action.type = buffer[offset + 2];
    result->action.length = action_length;
    // Parse other fields as necessary...

    result->updated_offset = offset + action_length;
}
