const config = {};

function getValue(key) {
    // Check if the value exists in the config object
    if (config.hasOwnProperty(key)) {
        return config[key];
    }

    // Check for a JavaScript file in the current or parent directory
    const currentDir = __dirname;
    const parentDir = path.resolve(currentDir, '..');
    const jsFilePath = path.join(currentDir, 'config.js');
    const parentJsFilePath = path.join(parentDir, 'config.js');

    let value;

    if (fs.existsSync(jsFilePath)) {
        const requiredConfig = require(jsFilePath);
        value = requiredConfig[key];
    } else if (fs.existsSync(parentJsFilePath)) {
        const requiredConfig = require(parentJsFilePath);
        value = requiredConfig[key];
    }

    // If value is still not found, check package.json
    if (value === undefined) {
        const packageJsonPath = path.join(currentDir, 'package.json');
        if (fs.existsSync(packageJsonPath)) {
            const packageJson = require(packageJsonPath);
            value = packageJson[key];
        }
    }

    // Set the value in the config object for future reference
    if (value !== undefined) {
        config[key] = value;
    }

    return value;
}
