const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const cloneRepository = (repoUrl, targetDir, symlinkDir) => {
    // Clone the repository
    exec(`git clone ${repoUrl} ${targetDir}`, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error cloning repository: ${stderr}`);
            return;
        }
        console.log(`Repository cloned: ${stdout}`);

        // Create a symbolic link to the binary executable
        const binaryName = path.basename(repoUrl, '.git'); // Assuming the binary name is the same as the repo name
        const binaryPath = path.join(targetDir, 'bin', binaryName); // Adjust path as necessary

        fs.symlink(binaryPath, path.join(symlinkDir, binaryName), 'file', (err) => {
            if (err) {
                console.error(`Error creating symlink: ${err}`);
            } else {
                console.log(`Symbolic link created at: ${path.join(symlinkDir, binaryName)}`);
            }
        });
    });
};

// Example usage
const repoUrl = 'https://github.com/user/repo.git';
const targetDir = './cloned-repo';
const symlinkDir = './bin';

cloneRepository(repoUrl, targetDir, symlinkDir);
