function createSIPTransaction(requestSender, sipRequest, transportMethod) {
    const transactionId = generateUniqueId();
    const logger = createLogger();

    const transaction = {
        requestSender: requestSender,
        request: sipRequest,
        transport: transportMethod,
        transactionId: transactionId,
        logger: logger,
        sendRequest: function() {
            this.logger.log(`Sending request with ID: ${this.transactionId}`);
            this.transport.send(this.request);
        }
    };

    return transaction;
}

function generateUniqueId() {
    return 'txn-' + Math.random().toString(36).substr(2, 9);
}

function createLogger() {
    return {
        log: function(message) {
            console.log(`[SIP Transaction Logger]: ${message}`);
        }
    };
}
