const canvas = document.getElementById('particleCanvas');
const ctx = canvas.getContext('2d');
let particle = { x: canvas.width / 2, y: canvas.height / 2 };

function updateParticlePosition() {
    const randomOffsetX = (Math.random() - 0.5) * 10; // Random offset between -5 and 5
    const randomOffsetY = (Math.random() - 0.5) * 10; // Random offset between -5 and 5
    particle.x += randomOffsetX;
    particle.y += randomOffsetY;

    // Keep particle within canvas bounds
    particle.x = Math.max(0, Math.min(canvas.width, particle.x));
    particle.y = Math.max(0, Math.min(canvas.height, particle.y));
}

function drawParticle() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
}

function handleKeyPress(event) {
    switch (event.key) {
        case 'ArrowUp':
            particle.y -= 5;
            break;
        case 'ArrowDown':
            particle.y += 5;
            break;
        case 'ArrowLeft':
            particle.x -= 5;
            break;
        case 'ArrowRight':
            particle.x += 5;
            break;
    }
    updateParticlePosition();
    drawParticle();
}

document.addEventListener('keydown', handleKeyPress);
setInterval(() => {
    updateParticlePosition();
    drawParticle();
}, 100);
