function calculateTotalValue(dataset, options) {
    // Filter dataset for years after 2001
    const filteredData = _.filter(dataset, function(item) {
        return item.year > 2001;
    });

    // Calculate total value for the specified field
    const totalValue = _.reduce(filteredData, function(sum, item) {
        return sum + item[options.field];
    }, 0);

    // Display total value and year in HTML elements
    $('#totalValue').text('Total Value: ' + totalValue);
    $('#years').text('Years: ' + _.pluck(filteredData, 'year').join(', '));
}

// Example usage
const dataset = [
    { year: 2002, value: 100 },
    { year: 2003, value: 200 },
    { year: 2001, value: 150 },
    { year: 2004, value: 250 }
];

const options = { field: 'value' };
calculateTotalValue(dataset, options);
