const identifierStore = new Map();

function generateUniqueId(key) {
    if (identifierStore.has(key)) {
        return identifierStore.get(key);
    }

    const randomPostfix = Math.random().toString(36).substring(2, 8);
    const uniqueId = Symbol(key + '_' + randomPostfix);
    identifierStore.set(key, uniqueId);

    return uniqueId;
}
