function animateGameElements(title, button, minesImage, callback) {
    const randomDuration = Phaser.Math.Between(5000, 10000);

    const titleTween = this.tweens.add({
        targets: title,
        angle: Phaser.Math.Between(0, 360),
        duration: randomDuration,
        ease: 'Linear',
        onComplete: onAnimationComplete
    });

    const buttonTween = this.tweens.add({
        targets: button,
        angle: Phaser.Math.Between(0, 360),
        duration: randomDuration,
        ease: 'Linear',
        onComplete: onAnimationComplete
    });

    const minesImageTween = this.tweens.add({
        targets: minesImage,
        angle: Phaser.Math.Between(0, 360),
        duration: randomDuration,
        ease: 'Linear',
        onComplete: onAnimationComplete
    });

    let animationsCompleted = 0;

    function onAnimationComplete() {
        animationsCompleted++;
        if (animationsCompleted === 3) {
            callback();
        }
    }
}
