import re

def escape_unescape_string(input_string, character_map, unescape=False):
    """Escapes or unescapes special characters in a string based on a character map."""

    if unescape:
        pattern = re.compile('|'.join(re.escape(k) for k in character_map.values()))
        return pattern.sub(lambda match: next(k for k, v in character_map.items() if v == match.group(0)), input_string)
    else:
        pattern = re.compile('|'.join(re.escape(k) for k in character_map.keys()))
        return pattern.sub(lambda match: character_map[match.group(0)], input_string)

# Example usage:
character_map = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
