        "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk",
        "Zephaniah", "Haggai", "Zechariah", "Malachi"
    ];

    const bookRegex = new RegExp(`\\b(${oldTestamentBooks.join('|')})\\b`, 'gi');
    const bookCounts = {};

    const matches = text.match(bookRegex);
    if (matches) {
        matches.forEach(book => {
            const normalizedBook = book.trim();
            bookCounts[normalizedBook] = (bookCounts[normalizedBook] || 0) + 1;
