function decodeWBXML(wbxmlString) {
    const codepageData = {};
    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(wbxmlString, "application/xml");

    const codepageElements = xmlDoc.getElementsByTagName("CodePage");
    for (let i = 0; i < codepageElements.length; i++) {
        const codepage = codepageElements[i];
        const id = codepage.getAttribute("id");
        const name = codepage.getAttribute("name");
        const values = {};

        const valueElements = codepage.getElementsByTagName("Value");
        for (let j = 0; j < valueElements.length; j++) {
            const valueElement = valueElements[j];
            const key = valueElement.getAttribute("key");
            const value = valueElement.textContent;
            values[key] = value;
        }

        codepageData[id] = {
            name: name,
            values: values
        };
    }

    return codepageData;
}
