function createParticleSystem(m) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    document.body.appendChild(canvas);

    // Create bitmap of the message
    ctx.font = '48px sans-serif';
    const textWidth = ctx.measureText(m).width;
    canvas.width = textWidth;
    canvas.height = 60; // Arbitrary height
    ctx.fillStyle = 'white';
    ctx.fillText(m, 0, 50);

    const particles = [];
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height).data;

    // Create particles based on the bitmap
    for (let y = 0; y < canvas.height; y++) {
        for (let x = 0; x < canvas.width; x++) {
            const index = (y * canvas.width + x) * 4;
            const alpha = imageData[index + 3];
            if (alpha > 0) {
                particles.push({ x, y, vx: 0, vy: 0 });
            }
        }
    }

    function explode() {
        particles.forEach(particle => {
            particle.vx = (Math.random() - 0.5) * 10; // Random velocity in x
            particle.vy = (Math.random() - 0.5) * 10; // Random velocity in y
        });
    }

    return { explode };
}

