// Import necessary Three.js components
import * as THREE from 'three';

// Create the scene
const scene = new THREE.Scene();

// Create a camera
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.z = 5;

// Create a renderer
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Create materials
const headMaterial = new THREE.MeshStandardMaterial({ color: 0xffcc99 });
const bodyMaterial = new THREE.MeshStandardMaterial({ color: 0x00ff00 });
const limbMaterial = new THREE.MeshStandardMaterial({ color: 0x0000ff });
const bodyTexture = new THREE.TextureLoader().load('path/to/body_texture.jpg');
const texturedBodyMaterial = new THREE.MeshStandardMaterial({ map: bodyTexture });

// Create head
const headGeometry = new THREE.SphereGeometry(0.5, 32, 32);
const head = new THREE.Mesh(headGeometry, headMaterial);
head.position.y = 1.5;

// Create body
const bodyGeometry = new THREE.BoxGeometry(1, 1.5, 0.5);
const body = new THREE.Mesh(bodyGeometry, texturedBodyMaterial);
body.position.y = 0;

// Create limbs
const limbGeometry = new THREE.BoxGeometry(0.25, 1, 0.25);
const leftArm = new THREE.Mesh(limbGeometry, limbMaterial);
leftArm.position.set(-0.75, 0.5, 0);

const rightArm = new THREE.Mesh(limbGeometry, limbMaterial);
rightArm.position.set(0.75, 0.5, 0);

const leftLeg = new THREE.Mesh(limbGeometry, limbMaterial);
leftLeg.position.set(-0.25, -1, 0);

const rightLeg = new THREE.Mesh(limbGeometry, limbMaterial);
rightLeg.position.set(0.25, -1, 0);

// Add all parts to the scene
scene.add(head);
scene.add(body);
scene.add(leftArm);
scene.add(rightArm);
scene.add(leftLeg);
scene.add(rightLeg);

// Add a light
const light = new THREE.PointLight(0xffffff, 1, 100);
light.position.set(5, 5, 5);
scene.add(light);

// Animation loop
function animate() {
    requestAnimationFrame(animate);
    renderer.render(scene, camera);
}
animate();
