function CookieManager() {}

CookieManager.prototype.setCookie = function(name, value, days) {
    let expires = "";
    if (days) {
        const date = new Date();
        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
        expires = "; expires=" + date.toUTCString();
    }
    document.cookie = name + "=" + (value || "") + expires + "; path=/";
};

CookieManager.prototype.getCookie = function(name) {
    const nameEQ = name + "=";
    const ca = document.cookie.split(';');
    for (let i = 0; i < ca.length; i++) {
        let c = ca[i];
        while (c.charAt(0) === ' ') c = c.substring(1, c.length);
        if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
    }
    return null;
};

CookieManager.prototype.removeCookie = function(name) {
    document.cookie = name + '=; Max-Age=-99999999; path=/';
};

// Usage
const cookieManager = new CookieManager();
cookieManager.setCookie('test', 'value', 7); // Set cookie
console.log(cookieManager.getCookie('test')); // Get cookie
cookieManager.removeCookie('test'); // Remove cookie
