function createListObject(defaultList = []) {
    const lists = {
        default: defaultList,
        custom: []
    };

    return function dispatch(action, item) {
        switch (action) {
            case 'add':
                lists.custom.push(item);
                break;
            case 'remove':
                lists.custom = lists.custom.filter(i => i !== item);
                break;
            case 'reset':
                lists.custom = [...lists.default];
                break;
            default:
                throw new Error('Invalid action');
        }
        return lists.custom;
    };
}
