function createBenchmarkHarness(b) {
    return function(benchmarkFunction, iterations) {
        b.tic();
        let result;

        for (let i = 0; i < iterations; i++) {
            result = benchmarkFunction();
            if (!b.ok(result)) {
                b.end();
                return;
            }
        }

        b.toc();
    };
}
