class NumberListManager {
    constructor(sortedList = []) {
        this.sortedList = sortedList.sort((a, b) => a - b);
    }

    addNumber(num) {
        this.sortedList.push(num);
        this.sortedList.sort((a, b) => a - b);
    }

    removeNumber(num) {
        const index = this.sortedList.indexOf(num);
        if (index > -1) {
            this.sortedList.splice(index, 1);
        }
    }

    getSortedList() {
        return this.sortedList;
    }
}

