const fs = require('fs');
const path = require('path');

function loadHandlersAndHelpers({ apiKey, failCount }) {
    const handlers = {};
    const helpers = {};

    const loadFiles = (dir, target) => {
        fs.readdirSync(dir).forEach(file => {
            const filePath = path.join(dir, file);
            const stat = fs.statSync(filePath);

            if (stat.isDirectory()) {
                loadFiles(filePath, target);
            } else if (file.endsWith('.js') && file !== 'index.js') {
                const module = require(filePath);
                const propertyName = path.basename(file, '.js');
                target[propertyName] = module;
            }
        });
    };

    loadFiles(path.join(__dirname, 'handlers'), handlers);
    loadFiles(path.join(__dirname, 'helpers'), helpers);

    return { handlers, helpers, apiKey, failCount };
}

module.exports = loadHandlersAndHelpers;
