function generateNestedArray(dimensions) {
    if (!Array.isArray(dimensions) || dimensions.length === 0) {
        throw new Error("Dimensions must be a non-empty array.");
    }

    function createArray(dimensions, currentDim = 0) {
        const size = dimensions[currentDim];
        const array = new Array(size);

        if (currentDim < dimensions.length - 1) {
            for (let i = 0; i < size; i++) {
                array[i] = createArray(dimensions, currentDim + 1);
            }
        } else {
            for (let i = 0; i < size; i++) {
                array[i] = null; // or any default value
            }
        }

        return array;
    }

    const nestedArray = createArray(dimensions);
    return nestedArray;
