// Extending the Number prototype
Number.prototype.$family = function() {
    if (this === null) {
        return 'null';
    }
    return Number.isFinite(this) ? 'finite' : 'infinite';
};

Number.prototype.random = function(min, max) {
    if (typeof min !== 'number' || typeof max !== 'number') {
        throw new TypeError('Arguments must be numbers');
    }
    return Math.random() * (max - min) + min;
};

// Extending Object prototype with forEach method
Object.prototype.forEach = function(callback, bind) {
    if (typeof callback !== 'function') {
        throw new TypeError('Callback must be a function');
    }
    for (let key in this) {
        if (this.hasOwnProperty(key)) {
            callback.call(bind, this[key], key, this);
        }
    }
};
