function reloadCommand(commandName, client) {
    // Delete the old command
    delete client.commands[commandName];

    // Re-require the command module
    const command = require(`./commands/${commandName}`);

    // Update the command's aliases
    if (command.aliases) {
        command.aliases.forEach(alias => {
            client.commands[alias] = command;
        });
    }

    // Set the new command
    client.commands[commandName] = command;
}
