    console.error(`Error: ${error.message}`);
}

function copyFolder(source, destination) {
    fs.mkdirSync(destination, { recursive: true });
    fs.readdirSync(source).forEach(file => {
        const srcFile = path.join(source, file);
        const destFile = path.join(destination, file);
        if (fs.lstatSync(srcFile).isDirectory()) {
            copyFolder(srcFile, destFile);
        } else {
            fs.copyFileSync(srcFile, destFile);
        }
    });
}

function codesignFile(file, identity) {
    return new Promise((resolve, reject) => {
        exec(`codesign --sign "${identity}" "${file}"`, (error, stdout, stderr) => {
            if (error) {
                return reject(new Error(`Code signing failed: ${stderr}`));
            }
            resolve(stdout);
        });
    });
}

async function buildPackage(source, destination, identity) {
    try {
        copyFolder(source, destination);
        console.log(`Copied folder from ${source} to ${destination}`);

        const files = fs.readdirSync(destination);
        for (const file of files) {
            const filePath = path.join(destination, file);
            if (!fs.lstatSync(filePath).isDirectory()) {
                await codesignFile(filePath, identity);
                console.log(`Signed file: ${filePath}`);
            }
        }
        console.log('Package build completed successfully.');
    } catch (error) {
        logError(error);
    }
}

if (!options.source || !options.destination || !options.signingIdentity) {
    console.error('Usage: node script.js <source_folder> <destination_folder> <signing_identity>');
    process.exit(1);
}

