function traverseDOM(node, selector, regex) {
    const matches = [];

    function recursiveTraverse(currentNode) {
        if (!currentNode) return;

        // Check if the current node matches the selector
        if (currentNode.matches(selector)) {
            // Check if the class or ID matches the regex
            if (regex.test(currentNode.className) || regex.test(currentNode.id)) {
                matches.push(currentNode);
            }
        }

        // Recursively traverse child nodes
        currentNode.childNodes.forEach(child => {
            recursiveTraverse(child);
        });
    }

    recursiveTraverse(node);
    return matches;
}
