function updatePolicyConfiguration(policy, formData) {
    // Update policy configuration based on form input
    if (formData.policyName) {
        policy.name = formData.policyName;
    }
    if (formData.policyDescription) {
        policy.description = formData.policyDescription;
    }
    if (formData.resources) {
        policy.resources = formData.resources.split(',').map(resource => resource.trim());
    }
    if (formData.applyPolicies) {
        policy.applyPolicies = formData.applyPolicies.split(',').map(applyPolicy => applyPolicy.trim());
    }

    // Stringify resources and applyPolicies arrays
    policy.resources = JSON.stringify(policy.resources);
    policy.applyPolicies = JSON.stringify(policy.applyPolicies);

    return policy;
}
