import PropTypes from 'prop-types';

const VersionList = ({ jsonDataUrl, repositoryUrl }) => {
    const [versions, setVersions] = useState([]);
    const [selectedVersion, setSelectedVersion] = useState('');

    useEffect(() => {
        const fetchVersions = async () => {
            const response = await fetch(jsonDataUrl);
            const data = await response.json();
            setVersions(data.versions);
            setSelectedVersion(data.latestStableVersion);
        };

        fetchVersions();
    }, [jsonDataUrl]);

    const handleVersionChange = (event) => {
        setSelectedVersion(event.target.value);
    };

    return (
        <div>
            <h1>Project Versions</h1>
            <h2>Latest Stable Version: {selectedVersion}</h2>
            <select value={selectedVersion} onChange={handleVersionChange}>
                {versions.map((version) => (
                    <option key={version} value={version}>
                        {version}
                    </option>
                ))}
            </select>
            <div>
                <a href={`${repositoryUrl}/releases/tag/${selectedVersion}`} target="_blank" rel="noopener noreferrer">
