const zlib = require('zlib');

function decodeAndDecompress(base64String, callback) {
    const buffer = Buffer.from(base64String, 'base64');

    zlib.inflate(buffer, (err, decompressedBuffer) => {
        if (err) {
            return callback(err);
        }

        const asciiHexCodes = decompressedBuffer.toString('ascii').split('\n');
        const codeFragments = [];
        const timeOffsets = [];

        asciiHexCodes.forEach((line, index) => {
            const [codeFragment, timeOffset] = line.split(',');
            if (codeFragment && timeOffset) {
                codeFragments.push(codeFragment);
                timeOffsets.push(parseFloat(timeOffset));
            }
        });

        const fingerprint = {
            codeFragments: codeFragments,
            timeOffsets: timeOffsets
        };

        callback(null, fingerprint);
    });
}
