function createMessageChannel() {
    if (typeof MessageChannel !== 'undefined') {
        const channel = new MessageChannel();
        return {
            send: (message) => channel.port1.postMessage(message),
            onMessage: (callback) => channel.port2.onmessage = (event) => callback(event.data)
        };
    } else if (typeof window !== 'undefined' && window.postMessage) {
        return {
            send: (message) => window.postMessage(message, '*'),
            onMessage: (callback) => {
                window.addEventListener('message', (event) => callback(event.data));
            }
        };
    } else if (typeof document !== 'undefined' && document.readyState) {
        const queue = [];
        let readyStateChangeHandler = null;

        const send = (message) => {
            queue.push(message);
            if (readyStateChangeHandler) {
                readyStateChangeHandler();
            }
        };

        const onMessage = (callback) => {
            readyStateChangeHandler = () => {
                while (queue.length > 0) {
                    callback(queue.shift());
                }
            };
            document.onreadystatechange = readyStateChangeHandler;
        };

        return { send, onMessage };
    } else {
        throw new Error('No message passing mechanism available');
    }
}

