function createDraggableObject(draggable, minX, maxX, leftButton, rightButton) {
    // Ensure initial styles
    draggable.style.left = draggable.style.left || '0px';
    draggable.style.right = draggable.style.right || '0px';

    let offsetX = 0;
    let isDragging = false;

    function onDragStart(event) {
        isDragging = true;
        offsetX = event.clientX - draggable.getBoundingClientRect().left;
        document.addEventListener('mousemove', onDrag);
        document.addEventListener('mouseup', onDragEnd);
    }

    function onDrag(event) {
        if (isDragging) {
            let newX = event.clientX - offsetX;
            if (newX < minX) newX = minX;
            if (newX > maxX) newX = maxX;
            draggable.style.left = newX + 'px';
        }
    }

    function onDragEnd() {
        isDragging = false;
        document.removeEventListener('mousemove', onDrag);
        document.removeEventListener('mouseup', onDragEnd);
    }

    draggable.addEventListener('mousedown', onDragStart);
    leftButton.addEventListener('click', () => {
        let currentX = parseInt(draggable.style.left) || 0;
