char* concatenate_buffers(char** buffers, size_t num_buffers) {
    size_t total_length = 0;
    char* result;

    // Calculate total length of all buffers
    for (size_t i = 0; i < num_buffers; i++) {
        total_length += strlen(buffers[i]);
