import PropTypes from 'prop-types';

function withPropTypesValidation<T>(validate: (props: T) => void, componentName: string) {
    const cache: { [key: string]: boolean } = {};

    return function validateProps(props: T) {
        const propsKey = JSON.stringify(props);

        if (cache[propsKey]) {
            return;
        }

        try {
            validate(props);
            cache[propsKey] = true;
        } catch (error) {
            console.warn(`Invalid prop types for component ${componentName}:`, error);
            throw new Error(`Invalid prop types for component ${componentName}: ${error.message}`);
        }
    };
}

// Example usage
const MyComponentPropTypes = {
    name: PropTypes.string.isRequired,
    age: PropTypes.number,
};

const validateMyComponentProps = (props: { name: string; age?: number }) => {
    PropTypes.checkPropTypes(MyComponentPropTypes, props, 'prop', 'MyComponent');
};

const validateMyComponent = withPropTypesValidation(validateMyComponentProps, 'MyComponent');

// Usage in a component
const props = { name: 'John', age: 30 };
validateMyComponent(props); // Valid props
