function* coroutine(iterator) {
    let controlToken;
    while (true) {
        controlToken = yield;
        if (controlToken !== undefined) {
            // If a control token is yielded, put the coroutine back in the list
            // of iterators to be processed again on the next loop iteration.
            iterator = (function* () {
                yield controlToken;
            })();
        }
        const result = iterator.next(controlToken);
        if (result.done) break;
        yield result.value;
    }
}
