function normalizeURL(url) {
    const urlParts = url.split('/');
    const normalizedParts = [];

    for (const part of urlParts) {
        if (part === '' || part === '.') {
            continue;
        }
        if (part === '..') {
            normalizedParts.pop();
        } else {
            normalizedParts.push(part);
        }
    }

    return normalizedParts.length > 0 ? '/' + normalizedParts.join('/') : '/';
}
