const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const admin = require('firebase-admin');

// Initialize Firebase
const serviceAccount = require('./path/to/serviceAccountKey.json');

admin.initializeApp({
    credential: admin.credential.cert(serviceAccount),
    databaseURL: 'https://<YOUR-FIREBASE-PROJECT>.firebaseio.com'
});

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

const LED_DEVICE_PATH = '/path/to/led/device'; // Replace with actual LED device path

// Function to update LED state
function updateLEDState(state) {
    // Synchronously write the new state to the LED device
    const fs = require('fs');
    fs.writeFileSync(LED_DEVICE_PATH, state ? '1' : '0');
}

// Socket.io connection
io.on('connection', (socket) => {
    console.log('A client connected');

    socket.on('ledStateChange', (message) => {
        try {
            const data = JSON.parse(message);
            const newState = data.state;

            // Update LED state
            updateLEDState(newState);

            // Store new state in Firebase
            const db = admin.database();
            const ref = db.ref('ledState');
            ref.set({ state: newState })
                .then(() => {
                    console.log('LED state updated in Firebase:', newState);
                })
                .catch((error) => {
                    console.error('Error updating Firebase:', error);
                });
        } catch (error) {
            console.error('Error parsing message:', error);
        }
    });

    socket.on('disconnect', () => {
        console.log('A client disconnected');
    });
});

// Start the server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
