function readI2CDevice(i2c, address, register, callback) {
    if (typeof register === 'undefined') {
        return Promise.reject(new Error('Register is undefined'));
    }

    return new Promise((resolve, reject) => {
        const buffer = Buffer.alloc(1);
        i2c.readI2cBlock(address, register, 1, buffer, (err) => {
            if (err) {
                if (callback) {
                    callback(err, null);
                }
                return reject(err);
            }
            if (callback) {
                callback(null, buffer);
            }
            resolve(buffer);
        });
    });
}
