function splitString(input, delimiter) {
    const result = [];
    const regex = new RegExp(`(.*?)(${delimiter})(.*)`);
    let match;

    while ((match = regex.exec(input)) !== null) {
        result.push(match[1]);
        input = match[3];
    }
    result.push(input); // Push the remaining part of the string

    return result;
}
