function parseMidiMetaEvent(dataStream) {
    const event = {};
    const eventType = dataStream[0]; // Assuming the first byte indicates the event type
    const length = dataStream[1]; // Assuming the second byte indicates the length of the data

    switch (eventType) {
        case 0x58: // Time Signature
            if (length !== 4) throw new Error('Invalid length for Time Signature event');
            event.subtype = 'timeSignature';
            event.numerator = dataStream[2]; // Numerator
            event.denominator = Math.pow(2, dataStream[3]); // Denominator as a power of 2
            break;

        case 0x59: // Key Signature
            if (length !== 2) throw new Error('Invalid length for Key Signature event');
            event.subtype = 'keySignature';
            event.key = dataStream[2]; // Key
            event.scale = dataStream[3]; // Scale
            break;

        case 0x7F: // Sequencer Specific
            if (length < 1) throw new Error('Invalid length for Sequencer Specific event');
            event.subtype = 'sequencerSpecific';
            event.data = dataStream.slice(2, 2 + length); // Data array
            break;

        default:
            event.subtype = 'unknown';
            console.error('Unknown meta event subtype:', eventType);
            break;
    }

    return event;
}
