function encryptString($plaintext, $key) {
    // Check if the mcrypt extension is loaded
    if (!function_exists('mcrypt_encrypt')) {
        return false; // Error: mcrypt extension not available
    }

    // Generate an initialization vector (IV) for AES-256 CTR
    $iv = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-ctr'));

    // Encrypt the plaintext
    $encrypted = mcrypt_encrypt(MCRYPT_RIJNDAEL_256, $key, $plaintext, MCRYPT_MODE_CTR, $iv);

    // Combine the IV and the encrypted data
    $result = base64_encode($iv . $encrypted);

    return $result;
}
