function is_file_writable($filePath) {
    // Check if the file exists
    if (!file_exists($filePath)) {
        return false;
    }

    // Check if the file is writable using PHP's is_writable function
    if (is_writable($filePath)) {
        return true;
    }

    // Check if the file is writable using file permissions
    $permissions = fileperms($filePath);
    if (($permissions & 0x0080) || // Owner can write
        (($permissions & 0x0020) && is_writable(dirname($filePath))) || // Group can write and group has write permission on the directory
        (($permissions & 0x0002) && is_writable(dirname($filePath)))) { // Others can write and others have write permission on the directory
        return true;
    }

    return false;
}
