function getNextChunk($requestBody, $chunkSize) {
    static $offset = 0;

    // Get the next chunk of the request body
    $chunk = substr($requestBody, $offset, $chunkSize);
    $offset += strlen($chunk);

    // If the end of the request body is reached, reset the offset
    if ($offset >= strlen($requestBody)) {
        $offset = 0;
    }

