    if (!$ldapConnection) {
        return "Could not connect to LDAP server.";
    }

    // Set LDAP options
    ldap_set_option($ldapConnection, LDAP_OPT_PROTOCOL_VERSION, 3);

    // Bind to the LDAP server
    if (!ldap_bind($ldapConnection, $ldapUser, $ldapPassword)) {
        return "LDAP bind failed.";
    }

    // Construct LDAP query
    $ldapQuery = "(uid=" . ldap_escape($sanitizedInput, '', LDAP_ESCAPE_FILTER) . ")";

    // Perform the LDAP search
    $result = ldap_search($ldapConnection, "ou=users,dc=example,dc=com", $ldapQuery);

    // Check for errors in the search
    if ($result === false) {
        ldap_unbind($ldapConnection);
        return "LDAP search failed.";
    }

    // Fetch results
