class ConversationLoader
{
    private $dataDirectory;
    private $memoryFile;

    public function __construct($dataDirectory)
    {
        $this->dataDirectory = rtrim($dataDirectory, '/') . '/';
        $this->memoryFile = $this->dataDirectory . 'memory.json';
    }

    public function loadConversation($entity)
    {
        if (!file_exists($this->memoryFile)) {
            return $this; // Memory file does not exist, return current instance
        }

        $conversationData = json_decode(file_get_contents($this->memoryFile), true);
        if ($conversationData === null) {
            throw new Exception("Failed to load conversation data from memory file.");
        }

        // Assuming $entity has a method to add conversation data
        $entity->addConversation($conversationData);

        return $this; // Return current instance for fluent interface
    }
}
