import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class QueryBuilder {
    private Map<String, Object> parameters;
    private StringBuilder whereClauses;

    public QueryBuilder() {
        this.parameters = new HashMap<>();
        this.whereClauses = new StringBuilder();
    }

    public QueryBuilder addWhereClause(String where, Object value) {
        if (value != null) {
            String hashedName = generateSHA1Hash(value.toString());
            whereClauses.append(String.format("%s==%s", where, hashedName));
            parameters.put(hashedName, value);
        } else {
            whereClauses.append(where);
        }
        return this;
    }

    private String generateSHA1Hash(String value) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] hash = digest.digest(value.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public String getWhereClause() {
        return whereClauses.toString();
    }

    public Map<String, Object> getParameters() {
        return parameters;
    }
}
