CREATE FUNCTION createUserAccount(
    p_username VARCHAR(255),
    p_password VARCHAR(255),
    p_email VARCHAR(255),
    p_role VARCHAR(50)
) RETURNS VARCHAR(255)
BEGIN
    DECLARE userExists INT;

    -- Escape bad characters
    SET p_username = REPLACE(REPLACE(p_username, ';', ''), '--', '');
    SET p_password = REPLACE(REPLACE(p_password, ';', ''), '--', '');
    SET p_email = REPLACE(REPLACE(p_email, ';', ''), '--', '');
    SET p_role = REPLACE(REPLACE(p_role, ';', ''), '--', '');

    -- Check if user already exists
    SELECT COUNT(*) INTO userExists FROM users WHERE username = p_username;
    IF userExists > 0 THEN
        RETURN 'User already exists';
    END IF;

    -- Insert new user into users table
    INSERT INTO users (username, password, email, role) VALUES (p_username, p_password, p_email, p_role);

    -- Create a new table for the user in the kin database
    SET @createTableSQL = CONCAT('CREATE TABLE kin.', p_username, ' (id INT AUTO_INCREMENT PRIMARY KEY, data VARCHAR(255));');
    PREPARE stmt FROM @createTableSQL;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    RETURN 'User account created successfully';
END //

DELIMITER ;
