function authUser($username, $password, $pdo) {
    if (empty($username)) {
        return null;
    }

    // Prepare the SQL statement to retrieve user information
    $stmt = $pdo->prepare("SELECT id, username, password, last_login, action_list, supplier_id, salt FROM users WHERE username = :username");
    $stmt->execute(['username' => $username]);
    $user = $stmt->fetch(PDO::FETCH_ASSOC);

    if ($user === false || !$user['is_active']) {
        // Log failed login attempt
        error_log("Login failed for username: " . $username);
        return null;
    }

    // Hash the provided password with the user's salt
    $hashedPassword = hash('sha256', $user['salt'] . $password);

    if ($hashedPassword === $user['password']) {
        // Update last login time or any other user state if necessary
        $updateStmt = $pdo->prepare("UPDATE users SET last_login = NOW() WHERE id = :id");
        $updateStmt->execute(['id' => $user['id']]);

        return [
            'id' => $user['id'],
            'username' => $user['username'],
            'password' => $user['password'],
            'last_login' => $user['last_login'],
            'action_list' => $user['action_list'],
            'supplier_id' => $user['supplier_id']
        ];
    } else {
        // Log failed login attempt
        error_log("Login failed for username: " . $username);
        return null;
    }
}
