function validateFormData($data, $files) {
    // Check if the content length is set and valid
    if (!isset($_SERVER['CONTENT_LENGTH']) || $_SERVER['CONTENT_LENGTH'] <= 0) {
        return false;
    }

    // Validate the input data
    foreach ($data as $key => $value) {
        if (empty($value)) {
            return false; // Required field is empty
        }
    }

    // Validate uploaded files
    if (!empty($files)) {
        foreach ($files['error'] as $error) {
            if ($error !== UPLOAD_ERR_OK) {
                return false; // File upload error
            }
        }

        // Check file types and sizes
        foreach ($files['tmp_name'] as $index => $tmpName) {
            $fileType = mime_content_type($tmpName);
            $fileSize = filesize($tmpName);

            // Example validation: allow only images and limit size to 2MB
            if (!preg_match('/^image\/(jpeg|png|gif)$/', $fileType) || $fileSize > 2 * 1024 * 1024) {
                return false; // Invalid file type or size
            }
        }
    }

    return true; // All checks passed
}
