function deleteContentElement($id, $pdo) {
    try {
        // Begin transaction
        $pdo->beginTransaction();

        // Delete the content element
        $stmt = $pdo->prepare("DELETE FROM content WHERE id = :id");
        $stmt->execute([':id' => $id]);

        // Update positions of subsequent elements
        $stmt = $pdo->prepare("UPDATE content SET position = position - 1 WHERE position > (SELECT position FROM content WHERE id = :id)");
        $stmt->execute([':id' => $id]);

        // Commit transaction
        $pdo->commit();
    } catch (Exception $e) {
        // Rollback transaction in case of error
        $pdo->rollBack();
        error_log($e->getMessage());
    }
}
