function processFileAndSearchXML($filePath, $xmlPath) {
    // Read the value from the file
    $value = file_get_contents($filePath);
    if ($value === false) {
        return "Error reading the file.";
    }

    // Perform an arithmetic operation (e.g., add 10)
    $result = intval($value) + 10;

    // Load the XML file
    $xmlDoc = xmlParseFile($xmlPath);
    if ($xmlDoc === false) {
        return "Error parsing the XML file.";
    }

    // Search for a match in the XML
    $root = xmlDocGetRootElement($xmlDoc);
    $found = false;

    // Iterate through the XML nodes
    for ($node = $root->children; $node; $node = $node->next) {
        if ($node->type == XML_ELEMENT_NODE && (string)$node->content == (string)$result) {
            $found = true;
            break;
        }
    }

    // Free the XML document
    xmlFreeDoc($xmlDoc);

    return $found ? "Match found for value: $result" : "No match found for value: $result";
}
