function createGraphvizImage($dotFilePath, $outputImagePath) {
    // Check if the dot file exists
    if (!file_exists($dotFilePath)) {
        throw new Exception("The specified dot file does not exist: " . $dotFilePath);
    }

    // Check if the output image already exists
    if (file_exists($outputImagePath)) {
        return $outputImagePath; // Return the existing image path
    }

    // Command to generate the image using Graphviz
    $command = escapeshellcmd("dot -Tpng " . escapeshellarg($dotFilePath) . " -o " . escapeshellarg($outputImagePath));

    // Execute the command
    exec($command, $output, $returnVar);

    // Check for errors during execution
    if ($returnVar !== 0) {
        throw new Exception("Error generating image: " . implode("\n", $output));
    }

    return $outputImagePath; // Return the path to the generated image
}
