function runPhpApplication($scriptPath, $args) {
    $output = $err = $exitStatus = null;

    if (!file_exists($scriptPath)) {
        echo "Error: PHP script not found at specified path.\n";
        return;
    }

    $cmd = "php " . escapeshellarg($scriptPath) . " " . escapeshellarg($args);

    try {
        $output = [];
        $exitStatus = null;
        exec($cmd . ' 2>&1', $output, $exitStatus);

        if ($exitStatus === 0) {
            echo "Success: " . implode("\n", $output) . "\n";
        } else {
            echo "Error: Command failed with exit status $exitStatus.\n";
            echo "Output: " . implode("\n", $output) . "\n";
        }
    } catch (Exception $e) {
        echo "Exception: " . $e->getMessage() . "\n";
    }
}

