    if (!empty($_SERVER['HTTP_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_CLIENT_IP'];
    }
    if (empty($ip) && !empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        $ip = $_SERVER['HTTP_X_FORWARDED_FOR'];
    }
    if (empty($ip) && !empty($_SERVER['HTTP_X_REAL_IP'])) {
        $ip = $_SERVER['HTTP_X_REAL_IP'];
    }
    if (empty($ip) && !empty($_SERVER['HTTP_PROXY_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_PROXY_CLIENT_IP'];
    }
    if (empty($ip) && !empty($_SERVER['HTTP_WL_PROXY_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_WL_PROXY_CLIENT_IP'];
    }
    if (empty($ip)) {
        $ip = $_SERVER['REMOTE_ADDR'];
    }

    if (filter_var($ip, FILTER_VALIDATE_IP)) {
        return $ip;
    }

