class UserDatabase {
    private $pdo;

    public function __construct($pdo) {
        $this->pdo = $pdo;
    }

    public function createUser($acronym, $email, $name) {
        $password = bin2hex(random_bytes(8)); // Generate a random password
        $hashedPassword = password_hash($password, PASSWORD_DEFAULT);
        $creationDate = date('Y-m-d H:i:s');
        $activationDate = date('Y-m-d H:i:s');

        $stmt = $this->pdo->prepare("INSERT INTO users (acronym, password, email, name, created_at, activated_at) VALUES (:acronym, :password, :email, :name, :created_at, :activated_at)");
        $stmt->bindParam(':acronym', $acronym);
        $stmt->bindParam(':password', $hashedPassword);
        $stmt->bindParam(':email', $email);
        $stmt->bindParam(':name', $name);
        $stmt->bindParam(':created_at', $creationDate);
        $stmt->bindParam(':activated_at', $activationDate);

        if ($stmt->execute()) {
            return true; // User created successfully
        } else {
            return false; // Failed to create user
        }
    }
}
