function createOrUpdateRecord($pdo, $url, $trackId, $userId, $site, $shortUrl, $httpClientIp, $httpXForwardedFor, $remoteAddr) {
    // Create a unique hash for the record
    $hash = md5($url . $trackId . $userId);

    // Check if a record with the same hash already exists
    $stmt = $pdo->prepare("SELECT views FROM records WHERE hash = :hash");
    $stmt->execute(['hash' => $hash]);
    $existingRecord = $stmt->fetch(PDO::FETCH_ASSOC);

    if ($existingRecord) {
        // Update the views field for the existing record
        $views = $existingRecord['views'] + 1; // Increment views
        $updateStmt = $pdo->prepare("UPDATE records SET views = :views WHERE hash = :hash");
        $updateStmt->execute(['views' => $views, 'hash' => $hash]);
    } else {
        // Insert a new record
        $createTime = date('H:i:s');
        $createDate = date('Y-m-d');
        $hour = date('H');

        $insertStmt = $pdo->prepare("INSERT INTO records (url, track_id, user_id, create_time, create_date, hour, site, short_url, http_client_ip, http_x_forwarded_for, remote_addr, hash, views) 
                                      VALUES (:url, :trackId, :userId, :createTime, :createDate, :hour, :site, :shortUrl, :httpClientIp, :httpXForwardedFor, :remoteAddr, :hash, 1)");
        $insertStmt->execute([
            'url' => $url,
            'trackId' => $trackId,
            'userId' => $userId,
            'createTime' => $createTime,
            'createDate' => $createDate,
            'hour' => $hour,
