function pingback($url, $previouslyPingedUrls, $userAgent) {
    // Check if the URL is valid
    if (!filter_var($url, FILTER_VALIDATE_URL)) {
        return "Invalid URL.";
    }

    // Parse the URL to get the host
    $parsedUrl = parse_url($url);
    $host = $parsedUrl['host'];

    // Check if the URL has already been pinged
    if (in_array($url, $previouslyPingedUrls)) {
        return "URL has already been pinged.";
    }

    // Get the IP address of the host
    $ipAddress = gethostbyname($host);
    if ($ipAddress === $host) {
        return "Host does not exist.";
    }

    // Check if the IP address is local
    if (filter_var($ipAddress, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE) === false) {
        return "Local IP address detected.";
    }

    // Sleep for 1 second before making the request
    sleep(1);

    // Prepare the headers for the request
    $headers = [
        "User-Agent: $userAgent",
        "Content-Type: application/xml"
    ];

    // Make the pingback request
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, "pingback_data"); // Replace with actual pingback data

    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    // Check for errors in the response
    if ($httpCode !== 200) {
        return "Pingback failed with HTTP code: $httpCode.";
    }

    return "Pingback successful.";
}
