function updateUserPassword($userId, $newPassword, $pdo) {
    try {
        // Hash the new password
        $passwordHash = password_hash($newPassword, PASSWORD_BCRYPT);

        // Prepare the SQL statement to update the password and deactivate the reset token
        $sql = "UPDATE users SET password_hash = ?, reset_token = NULL WHERE user_id = ?";
        $stmt = $pdo->prepare($sql);
        $stmt->execute([$passwordHash, $userId]);

        // Check if the password was updated
        if ($stmt->rowCount() > 0) {
            // Send status email to the user
            $userEmail = getUserEmailById($userId, $pdo); // Assume this function retrieves the user's email
            mail($userEmail, "Password Updated", "Your password has been successfully updated.");
            echo "Password changed and email sent!";
        } else {
            echo "No changes made to the password.";
        }
    } catch (PDOException $e) {
        echo "Error: " . $e->getMessage();
    }
}

function getUserEmailById($userId, $pdo) {
    $stmt = $pdo->prepare("SELECT email FROM users WHERE user_id = ?");
    $stmt->execute([$userId]);
    return $stmt->fetchColumn();
}
