class UserMapper {
    private $filePath;

    public function __construct($filePath) {
        $this->filePath = $filePath;
    }

    public function saveUser($userData) {
        $users = $this->getAllUsers();
        $users[] = $userData;
        file_put_contents($this->filePath, json_encode($users, JSON_PRETTY_PRINT));
