session_start();

function authenticateUser($clientId, $clientSecret, $redirectUri, $authCode) {
    $tokenUrl = 'https://oauth2provider.com/token';
    $userInfoUrl = 'https://oauth2provider.com/userinfo';

    // Step 1: Exchange authorization code for access token
    $postFields = [
        'grant_type' => 'authorization_code',
        'code' => $authCode,
        'redirect_uri' => $redirectUri,
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $tokenUrl);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($postFields));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    curl_close($ch);

    $tokenResponse = json_decode($response, true);

    if (isset($tokenResponse['access_token'])) {
        // Store access token in session
        $_SESSION['access_token'] = $tokenResponse['access_token'];

        // Step 2: Retrieve user information using access token
        $accessToken = $_SESSION['access_token'];
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $userInfoUrl);
        curl_setopt($ch, CURLOPT_HTTPHEADER, [
            'Authorization: Bearer ' . $accessToken,
        ]);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        $userInfoResponse = curl_exec($ch);
        curl_close($ch);

        return json_decode($userInfoResponse, true);
    }

    return null; // Authentication failed
}
