class UserDAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updateUserPassword($userId, $newPassword) {
        if (!$this->isPasswordStrong($newPassword)) {
            throw new Exception("Password does not meet strength requirements.");
        }

        try {
            $stmt = $this->db->prepare("SELECT id_uzytkownika FROM uzytkownicy WHERE id = ?");
            $stmt->bindParam(1, $userId);
            $stmt->execute();

            if ($stmt->rowCount() === 0) {
                throw new Exception("User not found.");
            }

            $user = $stmt->fetch(PDO::FETCH_ASSOC);
            $userID = $user['id_uzytkownika'];

            $stmt = $this->db->prepare("UPDATE uzytkownicy SET haslo = :password WHERE id_uzytkownika = :userID");
            $stmt->bindParam(':password', password_hash($newPassword, PASSWORD_DEFAULT));
            $stmt->bindParam(':userID', $userID);
            $stmt->execute();

            return true;
        } catch (Exception $e) {
            // Log error message if needed
            return false;
        }
    }

    private function isPasswordStrong($password) {
        return preg_match('/^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/', $password);
    }
}
