import random
import sys

def sample_population(population, num_samples=1, with_replacement=False, std_devs=1):
    if num_samples < 0:
        raise ValueError("Number of samples cannot be negative.")

    if not population:
        return []

    max_samples = int(std_devs * len(population))
    if num_samples > max_samples:
        num_samples = max_samples

    if with_replacement:
        return [random.choice(population) for _ in range(num_samples)]
    else:
        random.shuffle(population)
        return population[:num_samples]
