def login_to_server(username: str, password: str, server_url: str) -> dict:
    """
    Establish a connection to the server and send a login request.

    Args:
        username (str): The username for login.
        password (str): The password for login.
        server_url (str): The URL of the server to connect to.

    Returns:
        dict: A dictionary containing the server's response data.
    """

    headers = {
        'Content-Type': 'application/json',
    }

    data = {
        'userName': username,
        'password': password
    }

