import os
import subprocess
import sys

class KickstartConfigError(Exception):
    pass

def create_kickstart_config(hostname, basedir, timezone):
    config_content = f"""
# Kickstart configuration file
install
url --url={basedir}
lang en_US.UTF-8
keyboard us
network --bootproto=dhcp --hostname={hostname}
timezone --utc {timezone}
rootpw --plaintext password
firewall --enabled --service=ssh
selinux --enforcing
reboot
    """
    return config_content.strip()

def write_file(filepath, content):
    try:
        with open(filepath, 'w') as f:
            f.write(content)
    except IOError as e:
        raise KickstartConfigError(f"Error writing to file {filepath}: {e}")

def copy_scripts(scripts_dir, destination):
    try:
        for script in os.listdir(scripts_dir):
            full_script_path = os.path.join(scripts_dir, script)
            if os.path.isfile(full_script_path):
                subprocess.run(['cp', full_script_path, destination], check=True)
    except subprocess.CalledProcessError as e:
        raise KickstartConfigError(f"Error copying scripts: {e}")

def main():
    hostname = "centos7-server"
    basedir = "http://example.com/centos7"
    timezone = "America/New_York"
    kickstart_file = "/tmp/ks.cfg"
    scripts_dir = "/path/to/scripts"
    destination_dir = "/tmp/scripts"

    try:
        config_content = create_kickstart_config(hostname, basedir, timezone)
        write_file(kickstart_file, config_content)
        os.makedirs(destination_dir, exist_ok=True)
        copy_scripts(scripts_dir, destination_dir)
        print("Kickstart configuration and scripts setup successfully.")
    except KickstartConfigError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
