def gff3_to_gtf(gff3_file, gtf_file, dialect='default'):
    def extract_gff3_contents(file):
        if file.endswith('.gz'):
            with gzip.open(file, 'rt') as f:
                return f.readlines()
        else:
            with open(file, 'r') as f:
                return f.readlines()

    gff3_lines = extract_gff3_contents(gff3_file)

