CREATE OR REPLACE FUNCTION manage_table(lock_name TEXT)
RETURNS INTEGER AS $$
DECLARE
    affected_rows INTEGER := 0;
BEGIN
    -- Create table with auto-incrementing primary key
    CREATE TABLE IF NOT EXISTS my_table (
        id SERIAL PRIMARY KEY,
        name TEXT UNIQUE
    );

    -- Insert two unique rows
    INSERT INTO my_table (name) VALUES ('Alice'), ('Bob');
    affected_rows := affected_rows + 2;

    -- Acquire a write lock on the table
    EXECUTE format('LOCK TABLE my_table IN EXCLUSIVE MODE');

    -- Attempt to insert a third row with a non-unique name
    BEGIN
        INSERT INTO my_table (name) VALUES ('Alice');
        affected_rows := affected_rows + 1;
    EXCEPTION
        WHEN unique_violation THEN
            RAISE EXCEPTION 'Unique constraint violation: cannot insert duplicate name';
    END;

    -- Release the lock
    EXECUTE format('UNLOCK TABLE my_table');

    RETURN affected_rows;
END;
$$ LANGUAGE plpgsql;
