import sqlite3

def get_table_row_counts(table_names):
    """
    Returns the number of rows in each specified table.

    @param table_names: List of table names to query.
    @return: Dictionary with table names as keys and row counts as values.
    @raises ValueError: If any table has zero rows or if the tables have different schemas.
    """
    conn = sqlite3.connect('your_database.db')
    cursor = conn.cursor()

    row_counts = {}
    schemas = {}

    try:
        for table in table_names:
            cursor.execute(f"SELECT * FROM {table}")
            rows = cursor.fetchall()
            row_count = len(rows)
            row_counts[table] = row_count

            # Get schema for comparison
            cursor.execute(f"PRAGMA table_info({table})")
            schema = cursor.fetchall()
            schemas[table] = {col[1]: col[2] for col in schema}  # {column_name: column_type}

            if row_count == 0:
                raise ValueError(f"Table '{table}' has zero rows.")

        # Check if all schemas are the same
        first_schema = next(iter(schemas.values()))
        for schema in schemas.values():
            if schema != first_schema:
                raise ValueError("Tables have different schemas.")

    finally:
        cursor.close()
        conn.close()

    return row_counts
