import subprocess
import json
from collections import defaultdict

def get_commit_history(repo_path):
    command = ['hg', 'log', '--template', '{node}\n']
    result = subprocess.run(command, cwd=repo_path, capture_output=True, text=True)
    return result.stdout.strip().splitlines()

def get_commit_parents(commit, repo_path):
    command = ['hg', 'log', '--template', '{parents}\n', commit]
    result = subprocess.run(command, cwd=repo_path, capture_output=True, text=True)
    return result.stdout.strip().splitlines()

def analyze_commit_history(repo_path):
    commit_history = get_commit_history(repo_path)
    branch_count = defaultdict(int)
    commit_parents = {}

    for commit in commit_history:
        parents = get_commit_parents(commit, repo_path)
        commit_parents[commit] = parents
        branch_count[len(parents)] += 1

    return branch_count, commit_parents

if __name__ == "__main__":
    repo_path = '/path/to/your/repo'  # Change this to your repository path
    branch_count, commit_parents = analyze_commit_history(repo_path)

    print("Number of branches at each commit:")
    for num_parents, count in branch_count.items():
        print(f"{num_parents} parent(s): {count} commit(s)")

    print("\nCommit parents:")
    print(json.dumps(commit_parents, indent=2))
