import sqlite3

def fetch_column_values(table_name, where_clause, column_name, db_path):
    """
    Fetches values from a specified column in a given table based on a where clause.

    @param table_name: Name of the table to query.
    @param where_clause: SQL where clause to filter results.
    @param column_name: Name of the column to retrieve values from.
    @param db_path: Path to the SQLite database file.
    @return: A list of values from the specified column.
    """
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    try:
        query = f"SELECT {column_name} FROM {table_name} WHERE {where_clause}"
        cursor.execute(query)
        results = cursor.fetchall()
        return [row[0] for row in results]
    except sqlite3.Error as e:
