import subprocess
from io import TextIOWrapper

def execute_command(command, mode='r'):
    """Execute a command and return the output as a TextIOWrapper object.

    Args:
        command (str): The command to execute.
        mode (str): The mode for the TextIOWrapper ('r' for reading, 'w' for writing).

    Returns:
        TextIOWrapper: The output of the command as a TextIOWrapper object.
    """
    if mode not in ['r', 'w']:
        raise ValueError("Mode must be 'r' for reading or 'w' for writing.")

    process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    if mode == 'r':
        output, _ = process.communicate()
        return TextIOWrapper(io.BytesIO(output), encoding='utf-8')
    elif mode == 'w':
        return TextIOWrapper(process.stdin, encoding='utf-8')
