import json
import os

class FileIterator:
    def __init__(self, source, fail_on_missing=False):
        self.source = source
        self.fail_on_missing = fail_on_missing
        self._file = None

    def __iter__(self):
        if isinstance(self.source, str):
            if not os.path.exists(self.source):
                if self.fail_on_missing:
                    raise FileNotFoundError(f"File not found: {self.source}")
                return iter([])  # Return empty iterator if file not found and not failing
            self._file = open(self.source, 'r')
        else:
            raise ValueError("Source must be a file path as a string.")

        return self

    def __next__(self):
        if self._file is None:
            raise StopIteration
        line = self._file.readline()
        if not line:
            self._file.close()
            self._file = None
            raise StopIteration
        return line.strip()

    def load_from_json(self, json_str):
        data = json.loads(json_str)
        self.source = data.get('source')
        self.fail_on_missing = data.get('fail_on_missing', False)

    def to_json(self):
        return json.dumps({
            'source': self.source,
            'fail_on_missing': self.fail_on_missing
        })
