from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

def connect_to_databases(db_configs):
    connections = {}
    sessions = {}

    try:
        for db_name, config in db_configs.items():
            engine = create_engine(config['url'], echo=config.get('echo', False))
            connections[db_name] = engine
            Session = sessionmaker(bind=engine)
            sessions[db_name] = Session()

        return sessions
    except Exception as e:
        print(f"Error connecting to databases: {e}")
        close_connections(connections, sessions)

def close_connections(connections, sessions):
    for session in sessions.values():
        session.close()
    for engine in connections.values():
        engine.dispose()

# Example usage
db_configs = {
    'db1': {'url': 'sqlite:///db1.sqlite', 'echo': True},
    'db2': {'url': 'postgresql://user:password@localhost/db2', 'echo': True}
}

sessions = connect_to_databases(db_configs)
# Use the sessions for database operations
# After use, close the connections
close_connections(sessions)
