import hashlib

def hash_strings(strings, hash_function='sha256', unit=None):
    if hash_function not in hashlib.algorithms_available:
        raise ValueError("Unrecognized hash function")

    # Concatenate the strings
    combined_string = ''.join(strings)

    # Get the hash
    hash_object = hashlib.new(hash_function)
    hash_object.update(combined_string.encode('utf-8'))
    hash_value = hash_object.hexdigest()

    # Handle unit conversion if necessary
    if unit is not None:
        if unit == 'bytes':
            return bytes.fromhex(hash_value)
        elif unit == 'int':
            return int(hash_value, 16)
        else:
            raise ValueError("Unrecognized unit")

    return hash_value
