    with open(file_path, 'r') as file:
        return file.readlines()

def delete_directory(directory_path):
    try:
        subprocess.run(['rm', '-rf', directory_path], check=True)
    except subprocess.CalledProcessError as e:
        print(f"Error deleting directory {directory_path}: {e}")

def get_filenames_and_versions(file_contents):
    filenames_versions = []
    for line in file_contents:
        parts = line.strip().split()
        if len(parts) == 2:  # Assuming format: filename version
            filenames_versions.append((parts[0], parts[1]))
    return filenames_versions

def main(file_path, directory_path):
    file_contents = read_file_contents(file_path)
    delete_directory(directory_path)
    return get_filenames_and_versions(file_contents)

