def generate_gravatar_url(email, params=None):
    # Hash the email address using MD5
    email_hash = hashlib.md5(email.strip().lower().encode('utf-8')).hexdigest()

    # Create a canonized parameter dictionary
    if params is None:
        params = {}

    # Canonize parameters (e.g., remove empty values)
    canonized_params = {k: v for k, v in params.items() if v}

    # Build the Gravatar URL
    base_url = "https://www.gravatar.com/avatar/"
    query_string = urllib.parse.urlencode(canonized_params)

    if query_string:
        return f"{base_url}{email_hash}?{query_string}"
    else:
        return f"{base_url}{email_hash}"
