pub fn create_and_update_checksum(data: &[u8]) -> Option<GChecksum> {
    unsafe {
        // Create a new checksum object
        let checksum = g_checksum_new(0); // 0 for G_CHECKSUM_MD5, for example
        if checksum.is_null() {
            return None; // Handle error if checksum creation fails
