fn null_terminated_to_str(slice: *const i8) -> &'static str {
    if slice.is_null() {
        return "";
    }

    let mut len = 0;
    unsafe {
        while *slice.add(len) != 0 {
            len += 1;
        }
    }

    let bytes = unsafe { std::slice::from_raw_parts(slice as *const u8, len) };
    std::str::from_utf8(bytes).unwrap_or("")
}
