def parse_command_line_args(arg_string):
    if not arg_string:
        return []

    args = []
    current_arg = []
    in_quotes = False

    for char in arg_string:
        if char == '"':
            in_quotes = not in_quotes
        elif char.isspace() and not in_quotes:
            if current_arg:
                args.append(''.join(current_arg).strip())
                current_arg = []
        else:
            current_arg.append(char)

    if current_arg:
        args.append(''.join(current_arg).strip())

    return args
