use std::collections::HashSet;

struct ConcurrentBag {
    elements: Arc<Mutex<HashSet<i32>>>,
}

impl ConcurrentBag {
    fn new() -> Self {
        ConcurrentBag {
            elements: Arc::new(Mutex::new(HashSet::new())),
