use sha1::{Sha1, Digest};
use base64;

fn hash_and_encode(input: &[u8]) -> String {
    // Create a SHA-1 hasher
    let mut hasher = Sha1::new();

    // Write input data
    hasher.update(input);

    // Read the hash digest
    let result = hasher.finalize();

    // Convert the hash to a base64 encoded string
    let encoded = base64::encode(&result);

    // Print the hashed message and the base64 encoded output
    println!("Hashed message: {:?}", result);
    println!("Base64 encoded output: {}", encoded);

    encoded
}
