use std::io::{self, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};
use std::thread;
use std::thread::spawn;
use flate2::write::GzEncoder;
use flate2::Compression;

fn handle_client(mut stream: TcpStream) {
    let mut buffer = Vec::new();
    if let Err(e) = stream.read_to_end(&mut buffer) {
        eprintln!("Failed to read from client: {}", e);
        return;
    }

    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    if let Err(e) = encoder.write_all(&buffer) {
        eprintln!("Failed to compress data: {}", e);
        return;
    }

    let compressed_data = match encoder.finish() {
        Ok(data) => data,
        Err(e) => {
            eprintln!("Failed to finish compression: {}", e);
            return;
        }
    };

    if let Err(e) = stream.write_all(&compressed_data) {
        eprintln!("Failed to send data to client: {}", e);
    }
}

fn main() -> io::Result<()> {
    let address = "127.0.0.1:7878";
    let listener = TcpListener::bind(address)?;
    println!("Listening on {}", address);

    let num_cpus = num_cpus::get();
    let pool = Arc::new(Mutex::new(Vec::with_capacity(num_cpus)));

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let pool = Arc::clone(&pool);
                let handle = spawn(move || {
                    handle_client(stream);
                });
                pool.lock().unwrap().push(handle);
            }
            Err(e) => {
                eprintln!("Connection failed: {}", e);
            }
        }
    }

    Ok(())
}
