use getopts::Options;
use std::env;

pub fn print_usage(program_name: &str, options: &[(char, &str, &str)]) {
    let mut opts = Options::new();

    for &(short, long, desc) in options {
        opts.opt(short, long, desc, "");
    }

    let usage = format!("Usage: {} [options]", program_name);
    println!("{}", usage);
    println!("\nOptions:");

    for &(short, long, desc) in options {
        let short_flag = format!("-{}", short);
        let long_flag = format!("--{}", long);
        println!("  {} | {}", short_flag, long_flag);
        println!("      {}", desc);
