#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

void copy_files(const char *src, const char *dest, const char *lib_path) {
    struct stat st;
    if (stat(src, &st) != 0) {
        perror("stat");
        return;
    }

    if (S_ISDIR(st.st_mode)) {
        mkdir(dest, 0755);
        DIR *dir = opendir(src);
        struct dirent *entry;

        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                char src_path[PATH_MAX];
                char dest_path[PATH_MAX];
                snprintf(src_path, sizeof(src_path), "%s/%s", src, entry->d_name);
                snprintf(dest_path, sizeof(dest_path), "%s/%s", dest, entry->d_name);
                copy_files(src_path, dest_path, lib_path);
            }
        }
        closedir(dir);
    } else {
        char lib_file_path[PATH_MAX];
        snprintf(lib_file_path, sizeof(lib_file_path), "%s/%s", lib_path, basename((char *)src));

        if (access(lib_file_path, F_OK) == 0) {
            // Copy library file to destination
            FILE *src_file = fopen(lib_file_path, "rb");
            FILE *dest_file = fopen(dest, "wb");
            if (src_file && dest_file) {
                char buffer[BUFSIZ];
                size_t n;
                while ((n = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
                    fwrite(buffer, 1, n, dest_file);
                }
                fclose(src_file);
                fclose(dest_file);
                chmod(dest, 0755); // Set executable bit
            }
        } else {
            // Copy source file to destination
            FILE *src_file = fopen(src, "rb");
            FILE *dest_file = fopen(dest, "wb");
            if (src_file && dest_file) {
                char buffer[BUFSIZ];
                size_t n;
                while ((n = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
                    fwrite(buffer, 1, n, dest_file);
                }
                fclose(src_file);
                fclose(dest_file);
            }
        }
    }
}

void copy_directory(const char *src_dir, const char *dest_dir, const char *lib_path) {
