use aes::Aes256;
use block_modes::{BlockMode, Cbc};
use block_modes::block_padding::Pkcs7;
use base64::decode;
use sha2::{Sha256, Digest};
use std::error::Error;

type Aes256Cbc = Cbc<Aes256, Pkcs7>;

fn decrypt_blob(encrypted_blob: &str, device_id: &str, username: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if encrypted_blob.is_empty() {
        return Ok(vec![]);
    }

    let key = derive_key(device_id, username);
    let decoded_blob = decode(encrypted_blob)?;

    let iv_length = 16; // AES block size for CBC
    if decoded_blob.len() < iv_length {
        return Err("Invalid encrypted blob".into());
    }

    let (iv, data) = decoded_blob.split_at(iv_length);
    let cipher = Aes256Cbc::new_from_slices(&key, iv)?;

    let decrypted_data = cipher.decrypt_vec(data)?;
    Ok(decrypted_data)
}

fn derive_key(device_id: &str, username: &str) -> Vec<u8> {
    let mut hasher = Sha256::new();
    hasher.update(device_id);
    hasher.update(username);
    hasher.finalize().to_vec()
}
