use hmac::{Hmac, Mac, NewMac};
use percent_encoding::{utf8_percent_encode, NON_ALPHANUMERIC};
use sha1::Sha1;

pub fn generate_signature(method: &str, uri: &str, query: &str, consumer_secret: &str) -> String {
    let encoded_uri = utf8_percent_encode(uri, NON_ALPHANUMERIC).to_string();
    let encoded_query = utf8_percent_encode(query, NON_ALPHANUMERIC).to_string();

    let base_string = format!("{}&{}&{}", method, encoded_uri, encoded_query);

    let mut mac = Hmac::<Sha1>::new_from_slice(consumer_secret.as_bytes())
        .expect("HMAC can take key of any size");

    mac.update(base_string.as_bytes());

    let result = mac.finalize();
    let signature_bytes = result.into_bytes();

    base64::encode(signature_bytes)
}
