use md5::{Md5, Digest};

fn hash_string(input: &str, iterations: usize) -> String {
    let mut hasher = Md5::new();
    hasher.update(input);

    for _ in 1..iterations {
        let result = hasher.finalize_reset();
        hasher.update(&result);
    }

    let final_result = hasher.finalize();
    final_result.iter().map(|byte| format!("{:02x}", byte)).collect()
}
