use serde::{Deserialize, Serialize};
use serde_json::Result;
use std::fs;
use std::path::Path;

#[derive(Serialize, Deserialize, Debug)]
struct Config {
    server_port: u16,
    password: String,
    method: Option<String>,
    fast_open: Option<bool>,
    mode: Option<String>,
    plugin: Option<String>,
    plugin_opts: Option<String>,
}

fn setup_network_config(serialized_config: &str, dir_path: &str) -> Result<Config> {
    let config: Config = serde_json::from_str(serialized_config)?;

    // Validate configuration
    if config.server_port == 0 {
        return Err(serde_json::Error::custom("Invalid server port"));
    }
    if config.password.is_empty() {
        return Err(serde_json::Error::custom("Password cannot be empty"));
    }

    // Create the configuration file path
    let config_file_path = Path::new(dir_path).join(format!(".full_node_{}.conf", config.server_port));

    // Serialize the validated configuration back to a string
    let config_string = serde_json::to_string_pretty(&config)?;

    // Write the configuration to a file
    fs::write(config_file_path, config_string).map_err(|e| serde_json::Error::custom(e.to_string()))?;

    Ok(config)
}
