struct User {
    username: String,
    password: String,
    salt: Option<String>,
}

impl User {
    fn new(username: &str, password: &str, salt: Option<&str>) -> Self {
        User {
            username: username.to_string(),
            password: password.to_string(),
            salt: salt.map(|s| s.to_string()),
        }
    }

    fn check_password(&self, password: &str) -> bool {
        if let Some(ref salt) = self.salt {
            let mut hasher = Md5::new();
            hasher.update(format!("{}{}", password, salt));
            let result = hasher.finalize();
            let hashed_password = format!("{:x}", result);
            return hashed_password == self.password;
        }
        self.password == password
    }
}

fn authenticate_user(users: &HashMap<String, User>, username: &str, password: &str) -> Result<String, String> {
    match users.get(username) {
        Some(user) => {
            if user.check_password(password) {
                Ok(format!("Welcome, {}!", username))
            } else {
                Err("Authentication failed: Incorrect password.".to_string())
            }
        }
        None => Err("Authentication failed: User not found.".to_string()),
    }
}

