use actix_web::{web, App, HttpResponse, HttpServer, Result, middleware::Middleware};
use sqlx::{PgPool, Transaction};

pub async fn setup_db_connection(db_url: &str) -> (Transaction<'static>, App, impl Fn(web::HttpRequest, Result<HttpResponse>) -> Result<HttpResponse>) {
    // Run database migration command
    Command::new("migrate")
        .arg("up")
        .arg(db_url)
        .output()
        .expect("Failed to migrate the database");

    // Create a connection pool
    let pool = PgPool::connect(db_url).await.expect("Failed to connect to the database");

    // Start a transaction
    let transaction = pool.begin().await.expect("Failed to start transaction");

    // Define middleware function
    let middleware = move |req: web::HttpRequest, result: Result<HttpResponse>| {
        match result {
            Ok(response) => {
                // Commit transaction if the request was successful
                if let Some(tx) = req.extensions().get::<Transaction<'static>>() {
                    let _ = tx.commit(); // Handle commit result as needed
                }
                Ok(response)
            },
            Err(err) => {
                // Rollback transaction on error
                if let Some(tx) = req.extensions().get::<Transaction<'static>>() {
                    let _ = tx.rollback(); // Handle rollback result as needed
                }
                Err(err)
            }
        }
    };

    (transaction, App::new().app_data(web::Data::new(pool)), middleware)
}
