use rust_bencode::{BDict, Bencode, DecodeResult};
use rust_sha1::Sha1;
use std::collections::HashMap;

fn hash_chunks(data: Vec<u8>, chunk_size: usize) -> DecodeResult<BDict> {
    let mut final_dict = BDict::new();
    let mut hasher = Sha1::new();
    let mut position = 0;

    while position < data.len() {
        let end = std::cmp::min(position + chunk_size, data.len());
        let chunk = &data[position..end];

        hasher.update(chunk);
        let hash = hasher.digest().to_vec();

        let mut chunk_dict = BDict::new();
        chunk_dict.insert("hash".into(), hash.into());
        chunk_dict.insert("data".into(), chunk.to_vec().into());

        final_dict.insert(position.to_string().into(), chunk_dict.into());
        position += chunk_size;
        hasher = Sha1::new(); // Reset hasher for the next chunk
    }

    Ok(final_dict)
}
