position: Some(0),
kind: DecodeErrorKind::ExpectedByte('d'),
});
} else if bytes.len() < 2 {
return Err(DecodeError {
position: Some(1),
kind: DecodeErrorKind::EndOfStream,
});
}
let mut map = BTreeMap::new();
position += 1;
loop {
if position >= bytes.len() {
