use std::fs::File;
use std::io::{self, Write};
use std::path::Path;

struct History {
    entries: Vec<String>,
    max_size: usize,
}

impl History {
    fn new(max_size: usize) -> Self {
        History {
            entries: Vec::new(),
            max_size,
        }
    }

    fn push(&mut self, entry: String) {
        if self.entries.len() < self.max_size {
            self.entries.push(entry);
        }
    }

    fn commit(&self, filename: &str) -> io::Result<usize> {
        let path = Path::new(filename);
        let mut file = File::create(&path)?;
        for entry in &self.entries {
            writeln!(file, "{}", entry)?;
        }
        Ok(self.entries.len())
    }
}

fn main() -> io::Result<()> {
    let max_size = 5;
    let mut history = History::new(max_size);

    for i in 0..max_size {
        history.push(format!("Buffer {}", i));
    }

    let committed_length = history.commit("history.txt")?;
    assert_eq!(committed_length, max_size);

    Ok(())
}
```

