int create_temp_file_descriptors(int *read_fd, int *write_fd) {
    char template[] = "/tmp/tempfileXXXXXX";
    int fd;

    // Create a temporary file
    fd = mkstemp(template);
    if (fd == -1) {
        perror("Failed to create temporary file");
        return -1; // Error code for failure
    }

    // Set the file descriptor for writing
    *write_fd = fd;

    // Set the file descriptor for reading
    *read_fd = dup(fd);
    if (*read_fd == -1) {
        perror("Failed to duplicate file descriptor");
        close(fd);
        return -2; // Error code for failure
    }

    // Set the file descriptor flags
    if (fcntl(*read_fd, F_SETFD, FD_CLOEXEC) == -1) {
        perror("Failed to set file descriptor flags");
        close(fd);
        close(*read_fd);
        return -3; // Error code for failure
    }

    // Return success
    return 0; // Success
}
