use std::collections::HashMap;
use std::env;

#[derive(Debug)]
struct Config {
    server_port: Option<u16>,
    user_data_path: Option<String>,
    rally_point_port: Option<u16>,
}

impl Config {
    fn new() -> Self {
        Config {
            server_port: None,
            user_data_path: None,
            rally_point_port: None,
        }
    }
}

fn parse_args() -> Config {
    static mut CACHE: Option<Config> = None;

    unsafe {
        if let Some(ref cached) = CACHE {
            return cached.clone();
        }
    }

    let args: Vec<String> = env::args().collect();
    let mut config = Config::new();

    for arg in &args[1..] {
        if let Some((key, value)) = arg.split_once('=') {
            match key {
                "server_port" => config.server_port = value.parse().ok(),
                "user_data_path" => config.user_data_path = Some(value.to_string()),
                "rally_point_port" => config.rally_point_port = value.parse().ok(),
                _ => continue,
            }
        }
    }

    unsafe {
        CACHE = Some(config.clone());
    }

    config
}

fn main() {
    let config = parse_args();
    println!("{:?}", config);
}
