using json = nlohmann::json;

std::string createGenesisTransaction(const std::vector<json>& nodeTransactions, const std::string& poolName) {
    // Create directory for the pool if it does not exist
    std::filesystem::path poolDir = std::filesystem::path("./") / poolName;
    if (!std::filesystem::exists(poolDir)) {
        std::filesystem::create_directory(poolDir);
    }

    // Prepare the genesis transaction data
    json genesisTransaction;
    genesisTransaction["transactions"] = nodeTransactions;

    // Set client and node details from the first node transaction
    if (!nodeTransactions.empty()) {
        const auto& firstNode = nodeTransactions[0];
        genesisTransaction["client_ip"] = firstNode["client_ip"];
        genesisTransaction["client_port"] = firstNode["client_port"];
        genesisTransaction["node_ip"] = firstNode["node_ip"];
        genesisTransaction["node_port"] = firstNode["node_port"];
        genesisTransaction["services"] = firstNode["services"];
    }

    // Write the genesis transaction to a file
    std::string filePath = (poolDir / (poolName + ".txn")).string();
    std::ofstream outFile(filePath);
    if (!outFile) {
        throw std::runtime_error("Failed to create genesis transaction file.");
    }
    outFile << genesisTransaction.dump(4); // Pretty print with 4 spaces
    outFile.close();

    return filePath;
}
