void printHelp() {
    std::cout << "Usage: exchange [options] <path1> <path2>\n"
              << "Options:\n"
              << "  -h, --help          Show this help message\n"
              << "  -v, --version       Show version information\n"
              << "  --non-atomic        Perform a non-atomic exchange\n";
}

void printVersion() {
    std::cout << "Exchange Tool Version 1.0\n";
}

void exchangeContents(const std::string& path1, const std::string& path2, bool nonAtomic) {
    std::ifstream src1(path1, std::ios::binary);
    std::ifstream src2(path2, std::ios::binary);
    std::ofstream dst1(path1 + ".tmp", std::ios::binary);
    std::ofstream dst2(path2 + ".tmp", std::ios::binary);

    if (!src1 || !src2 || !dst1 || !dst2) {
        std::cerr << "Error opening files for exchange.\n";
        return;
    }

    dst1 << src2.rdbuf();
    dst2 << src1.rdbuf();

    if (!nonAtomic) {
        std::rename((path1 + ".tmp").c_str(), path1.c_str());
        std::rename((path2 + ".tmp").c_str(), path2.c_str());
    } else {
        std::cout << "Non-atomic exchange performed. Temporary files created.\n";
    }

    std::cout << "Contents exchanged successfully.\n";
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Error: At least two paths are required.\n";
        return 1;
    }

    bool nonAtomic = false;

    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "-h" || std::string(argv[i]) == "--help") {
            printHelp();
            return 0;
        } else if (std::string(argv[i]) == "-v" || std::string(argv[i]) == "--version") {
            printVersion();
            return 0;
        } else if (std::string(argv[i]) == "--non-atomic") {
            nonAtomic = true;
        }
    }

    std::string path1 = argv[argc - 2];
    std::string path2 = argv[argc - 1];

    exchangeContents(path1, path2, nonAtomic);

    return 0;
}
