use std::env;
use std::process::Command;

fn open_file_with_default_command(path: &str) -> Option<String> {
    // Get the BROWSER environment variable
    if let Ok(browser) = env::var("BROWSER") {
        return Some(browser);
    }

    // Fallback to a list of alternative commands
    let alternatives = vec![
        "xdg-open", // Linux
        "open",     // macOS
        "explorer", // Windows
    ];

    for command in alternatives {
        if Command::new(command).arg(path).output().is_ok() {
            return Some(command.to_string());
        }
    }

    None
}
