use std::process::Command;

pub fn create_command(command_line: &str, flavor: Option<&str>) -> Command {
    let is_batch_script = command_line.ends_with(".bat") || command_line.ends_with(".cmd");
    let mut command = if is_batch_script {
        Command::new("cmd")
            .arg("/C")
            .arg(command_line)
    } else {
        Command::new(command_line)
    };

    if let Some(flavor) = flavor {
        command.env("FLAVOR", flavor);
    }

    command
}
