use std::env;
use std::io;

fn open_file_with_command(path: &str) -> Result<String, Vec<String>> {
    let commands = vec![
        env::var("BROWSER").unwrap_or_else(|_| "xdg-open".to_string()),
        "xdg-open".to_string(),
        "gnome-open".to_string(),
        "kde-open".to_string(),
    ];

    let mut failed_commands = Vec::new();

    for command in commands {
        let output = Command::new(&command)
            .arg(path)
            .output();

        match output {
            Ok(status) if status.status.success() => return Ok(command),
            _ => failed_commands.push(command),
        }
    }

    Err(failed_commands)
}
