use std::sync::{Arc, Mutex};
use std::thread;
use std::sync::mpsc;
use std::time::Duration;

struct ThreadPoolExecutor {
    workers: Vec<Worker>,
    sender: mpsc::Sender<Job>,
}

type Job = Box<dyn FnOnce() + Send + 'static>;

impl ThreadPoolExecutor {
    fn new(size: usize) -> ThreadPoolExecutor {
        let (sender, receiver) = mpsc::channel();
        let receiver = Arc::new(Mutex::new(receiver));
        let mut workers = Vec::with_capacity(size);

        for id in 0..size {
            workers.push(Worker::new(id, Arc::clone(&receiver)));
        }

        ThreadPoolExecutor { workers, sender }
    }

    fn execute<F>(&self, f: F)
    where
        F: FnOnce() + Send + 'static,
    {
        let job = Box::new(f);
        self.sender.send(job).unwrap();
    }
}

struct Worker {
    id: usize,
    thread: Option<thread::JoinHandle<()>>,
}

impl Worker {
    fn new(id: usize, receiver: Arc<Mutex<mpsc::Receiver<Job>>>) -> Worker {
        let thread = thread::spawn(move || loop {
            let job = receiver.lock().unwrap().recv().unwrap();
            println!("Worker {} got a job; executing.", id);
            job();
        });

        Worker {
            id,
            thread: Some(thread),
        }
    }
}

struct DBSupervisor {
    pool: ThreadPoolExecutor,
}

impl DBSupervisor {
    fn new(pool_size: usize) -> DBSupervisor {
        DBSupervisor {
            pool: ThreadPoolExecutor::new(pool_size),
        }
    }

    fn process_query(&self, query: String) {
        self.pool.execute(move || {
            println!("Processing query: {}", query);
            thread::sleep(Duration::from_secs(1)); // Simulate query processing
            println!("Query processed: {}", query);
        });
    }
}

struct QueryClient {
    supervisor: DBSupervisor,
}

impl QueryClient {
    fn new(supervisor: DBSupervisor) -> QueryClient {
        QueryClient { supervisor }
    }

    fn send_query(&self, query: String) {
        self.supervisor.process_query(query);
    }
}

fn main() {
    let supervisor = DBSupervisor::new(4);
    let client = QueryClient::new(supervisor);

    client.send_query("SELECT * FROM users".to_string());
    client.send_query("UPDATE users SET active = 1 WHERE id = 1".to_string());

    // Give some time for threads to finish processing
    thread::sleep(Duration::from_secs(5));
}
